// _darwin.mjs — shared invocation helper for the `@metaharness/darwin` CLI.
//
// Mirrors `_harness.mjs` for the umbrella `metaharness` / `harness` binaries,
// but targets the separate darwin binary (`metaharness-darwin`) which is
// published as its own npm package (`@metaharness/darwin@~0.8.0`).
//
// Shared plumbing (degraded classification, --json injection, trailing-JSON
// parse, degraded emitter) lives in `_invoke.mjs`. What stays here is the
// genuinely-darwin part: the ASYNC STREAMING variant (`runDarwinAsync`) that
// long `evolve` runs need for per-generation progress visibility.
//
// Three subcommands surfaced (matches darwin 0.8.x — same verbs as 0.3.x,
// with GEPA-engine evolve flags added upstream: --selection modes,
// --crossover, --epistasis, --curriculum, --mutator ruvllm, --sandbox):
//   - `metaharness-darwin evolve <repo> [...]`         — harness self-improvement
//   - `metaharness-darwin bench <create|verify> ...`   — bench-suite lifecycle
//   - `metaharness-darwin security bench [...]`        — Darwin Shield (upstream ADR-155)
//
// CONTRACT (identical to runMetaharness/runHarness):
//   - returns `{ stdout, stderr, exitCode, json|null, durationMs, degraded, reason? }`
//   - `--json` is appended automatically when `opts.json !== false`
//   - subprocess hard timeout (default 60s, override with opts.timeoutMs)
//   - on MODULE_NOT_FOUND / network failure / "not installed", returns
//     `degraded: true, reason: 'metaharness-darwin-not-available'` — never throws
//     (ADR-150 graceful-degradation rule #3; ADR-153 §"Architecture" constraint 3)
//
// IMPORTANT — evolve has long timeouts:
//   `evolve` is the only long-running verb in the metaharness family. A real
//   evolution with --generations 10 --children 5 --concurrency 2 takes
//   minutes-to-hours, NOT seconds. Callers MUST pass an explicit `timeoutMs`
//   matched to their --generations × --children × sandbox cost; the 60s
//   default is for `bench verify` and `security bench --population 2 --cycles 1`
//   smoke shapes only.

import { spawnSync, spawn } from 'node:child_process';
import {
  classifyDegraded,
  importOptionalLibrary,
  injectJson,
  makeDegradedEmitter,
  parseTrailingJson,
} from './_invoke.mjs';

const DEFAULT_TIMEOUT_MS = 60_000;

// Pinned semver range. Bump in lock-step with optionalDependencies in
// @claude-flow/cli/package.json + ruflo/package.json. The `~` allows
// patch upgrades without re-pinning.
const DARWIN_PKG = '@metaharness/darwin';
const DARWIN_PIN_VERSION = '~0.8.0';
const DARWIN_PIN = `${DARWIN_PKG}@${DARWIN_PIN_VERSION}`;

const REASON_PREFIX = 'metaharness-darwin';

function buildArgv(args, wantJson) {
  // `metaharness-darwin` historically does NOT take --json on every
  // subcommand (some emit plain text reports — security bench in
  // particular is markdown). We still append --json for callers that
  // explicitly request it, but never silently inject it on subcommands
  // that don't accept it. The shape that does support --json is the
  // single-verb `evolve` and `bench verify`.
  return injectJson(args, wantJson);
}

// darwin's evolve emits a final JSON object at end of stdout when --json
// is passed; everything before is human-readable progress. Grab the LAST
// {...} block, not the first — the first may be a per-generation log line.
// (This last-block parse is now the family-wide shared implementation.)
const maybeParseJson = parseTrailingJson;

/**
 * Sync invocation. Use for short subcommands (`bench verify`, smoke shapes).
 * Async variant below for long-running `evolve` calls.
 */
export function runDarwin(args, opts = {}) {
  const start = Date.now();
  const timeoutMs = opts.timeoutMs ?? DEFAULT_TIMEOUT_MS;
  const wantJson = opts.json !== false;
  const argv = buildArgv(args, wantJson);
  const r = spawnSync('npx', ['-y', '-p', DARWIN_PIN, 'metaharness-darwin', ...argv], {
    stdio: ['ignore', 'pipe', 'pipe'],
    encoding: 'utf-8',
    timeout: timeoutMs,
    cwd: opts.cwd,
    env: { ...process.env, ...(opts.env || {}) },
    shell: process.platform === 'win32',
  });
  const durationMs = Date.now() - start;
  const stdout = r.stdout || '';
  const stderr = r.stderr || '';
  const classified = classifyDegraded(stderr, r.status, REASON_PREFIX);
  if (classified.degraded) {
    return {
      stdout, stderr,
      exitCode: r.status ?? 127,
      json: null,
      durationMs,
      degraded: true,
      reason: classified.reason,
    };
  }
  return {
    stdout, stderr,
    exitCode: r.status ?? 0,
    json: wantJson ? maybeParseJson(stdout) : null,
    durationMs,
    degraded: false,
  };
}

/**
 * Async invocation with streaming. Required for `evolve` because the run
 * can take 10+ minutes and the caller wants progress visibility.
 *
 * If `opts.onProgress(line)` is provided, called once per stderr line.
 * darwin writes per-generation progress to stderr, structured result to
 * stdout. Cancellable via opts.signal (AbortSignal).
 */
export function runDarwinAsync(args, opts = {}) {
  return new Promise((resolve) => {
    const start = Date.now();
    const timeoutMs = opts.timeoutMs ?? DEFAULT_TIMEOUT_MS;
    const wantJson = opts.json !== false;
    const argv = buildArgv(args, wantJson);
    const p = spawn('npx', ['-y', '-p', DARWIN_PIN, 'metaharness-darwin', ...argv], {
      stdio: ['ignore', 'pipe', 'pipe'],
      cwd: opts.cwd,
      env: { ...process.env, ...(opts.env || {}) },
      shell: process.platform === 'win32',
    });
    let stdout = '', stderr = '', stderrBuf = '';
    p.stdout?.on('data', (d) => { stdout += d.toString(); });
    p.stderr?.on('data', (d) => {
      const s = d.toString();
      stderr += s;
      if (opts.onProgress) {
        stderrBuf += s;
        const lines = stderrBuf.split('\n');
        stderrBuf = lines.pop() ?? '';
        for (const line of lines) opts.onProgress(line);
      }
    });
    let timedOut = false;
    const timer = setTimeout(() => {
      timedOut = true;
      try { p.kill('SIGTERM'); } catch { /* ignore */ }
    }, timeoutMs);
    if (opts.signal) {
      opts.signal.addEventListener('abort', () => {
        try { p.kill('SIGTERM'); } catch { /* ignore */ }
      }, { once: true });
    }
    p.on('error', (e) => {
      clearTimeout(timer);
      resolve({
        stdout,
        stderr: stderr + String(e?.message ?? e),
        exitCode: 127, json: null, durationMs: Date.now() - start,
        degraded: true, reason: `${REASON_PREFIX}-not-available`,
      });
    });
    p.on('close', (code) => {
      clearTimeout(timer);
      const durationMs = Date.now() - start;
      const classified = classifyDegraded(stderr, timedOut ? null : code, REASON_PREFIX);
      if (classified.degraded) {
        resolve({
          stdout, stderr,
          exitCode: code ?? 127, json: null, durationMs,
          degraded: true, reason: classified.reason,
        });
        return;
      }
      resolve({
        stdout, stderr,
        exitCode: code ?? 0,
        json: wantJson ? maybeParseJson(stdout) : null,
        durationMs,
        degraded: false,
      });
    });
  });
}

/**
 * Match the existing `emitDegradedJsonAndExit` shape used by the
 * metaharness-umbrella scripts so MCP tool consumers see one contract.
 * Exit 0 — ADR-150 architectural constraint: ruflo continues to function
 * when MetaHarness is absent. Same posture as the umbrella scripts.
 */
export const emitDarwinDegradedJsonAndExit = makeDegradedEmitter(DARWIN_PKG, DARWIN_PIN_VERSION);

export const DARWIN_VERSION_PIN = DARWIN_PIN;

/**
 * Resolver for the darwin GEPA LIBRARY entry (`@metaharness/darwin/gepa`).
 * Lives here (not in gepa.mjs) because gepa.mjs is a CLI script that runs
 * main() on import — this module is the import-safe home for the darwin
 * pin. Used by gepa.mjs (genome/validate/render/analyze ops) and by
 * evolve.mjs --diagnose (failure-class analysis of run transcripts).
 * Returns the module namespace or null. Never throws on absence.
 */
export function importGepa() {
  return importOptionalLibrary({
    specifier: '@metaharness/darwin/gepa',
    pkg: DARWIN_PKG,
    pinVersion: DARWIN_PIN_VERSION,
    entryRelPath: 'dist/gepa/index.js',
  });
}

// _harness.mjs — shared invocation helper for the metaharness/harness CLIs.
//
// All ruflo-metaharness skills shell out to the upstream CLI rather than
// linking the library — this honors ADR-150's architectural constraint
// (MetaHarness must remain a removable augmentation, never a required
// runtime dep) while still giving us "deep integration" through a single
// vetted bridge that every skill imports from.
//
// CONTRACT
//   - `runMetaharness(args, opts)` — invoke the `metaharness` binary
//   - `runHarness(args, opts)`     — invoke the sibling `harness` binary
//   - both return `{ stdout, stderr, exitCode, json|null, durationMs, degraded, reason? }`
//   - `--json` flag is appended automatically when `opts.json !== false`
//   - subprocess hard timeout (default 60s) — captured in opts.timeoutMs
//   - when the package cannot be resolved/installed, returns degraded result
//     with `degraded: true, reason: 'metaharness-not-available'` — never
//     throws (ADR-150 graceful-degradation rule #3). A subprocess killed by
//     the timeout reports `reason: 'metaharness-timeout'` instead (matches
//     the sibling _darwin/_redblue helpers).
//
// SECURITY + PERF (supersedes the iter-27 npx-with-@latest-dist-tag path)
// =========================================================================
// The pre-consolidation implementation shelled to `npx -y` with the @latest
// dist-tag. Two problems, both fixed here:
//   1. SECURITY (HIGH): @latest means a compromised upstream publish executes
//      arbitrary code on user machines on the very next skill invocation.
//      The version is now PINNED to METAHARNESS_PIN_VERSION (tilde range —
//      patch updates only) and only bumped deliberately, in lock-step with
//      optionalDependencies in @claude-flow/cli + ruflo package.json.
//   2. PERF: @latest forced an npm-registry metadata check on EVERY call.
//      Resolution is now (a) an already-installed local metaharness
//      satisfying the pin (walk-up node_modules — free), then (b) a ONE-TIME
//      `npm install --prefix ~/.ruflo/metaharness-cache-<pin>` versioned
//      cache (same proven pattern as _redblue.mjs / gepa.mjs), after which
//      every call is a plain `node <abs-path-to-cli>` spawn — zero network.
//
// BOTH BINARIES: the `metaharness` package ships two bins (`metaharness`
// and `harness`); their entry paths are read from the resolved package.json
// bin map rather than hardcoded, so upstream layout changes inside the
// pinned range cannot silently break us.

import { spawnSync, spawn } from 'node:child_process';
import { existsSync, readFileSync } from 'node:fs';
import { join } from 'node:path';
import {
  classifyDegraded,
  ensureCachedInstall,
  findLocalPackageDir,
  injectJson,
  makeDegradedEmitter,
  parseTrailingJson,
} from './_invoke.mjs';

const DEFAULT_TIMEOUT_MS = 60_000;

// Pinned semver range. Bump in lock-step with optionalDependencies in
// @claude-flow/cli/package.json + ruflo/package.json. NEVER @latest.
const METAHARNESS_PKG = 'metaharness';
const METAHARNESS_PIN_VERSION = '~0.3.0';

const REASON_NOT_AVAILABLE = 'metaharness-not-available';

/**
 * Resolve absolute paths for the two bins shipped by the metaharness
 * package. Memoized per process — the whole point is that after the first
 * resolution (or one-time cache install) every call is local-only.
 */
let RESOLVED = null;
function resolveMetaharnessBins() {
  if (RESOLVED) return RESOLVED;
  // (a) already-installed local copy satisfying the pin — free.
  const localDir = findLocalPackageDir(METAHARNESS_PKG, METAHARNESS_PIN_VERSION);
  if (localDir) {
    const bins = readBinMap(localDir);
    if (bins) return (RESOLVED = { ok: true, bins, source: 'local' });
  }
  // (b) one-time versioned cache install of the pinned range.
  const cached = ensureCachedInstall({ pkg: METAHARNESS_PKG, pinVersion: METAHARNESS_PIN_VERSION });
  if (!cached.ok) {
    return (RESOLVED = {
      ok: false,
      reason: REASON_NOT_AVAILABLE,
      stderr: cached.stderr ?? cached.error ?? '',
      stdout: cached.stdout ?? '',
    });
  }
  const bins = readBinMap(cached.pkgDir);
  if (!bins) {
    return (RESOLVED = {
      ok: false,
      reason: REASON_NOT_AVAILABLE,
      stderr: `metaharness package at ${cached.pkgDir} is missing the expected bin map (metaharness + harness)`,
      stdout: '',
    });
  }
  return (RESOLVED = { ok: true, bins, source: 'cache' });
}

/** Read both bin entry points from the package's bin map. */
function readBinMap(pkgDir) {
  try {
    const pj = JSON.parse(readFileSync(join(pkgDir, 'package.json'), 'utf-8'));
    const bin = pj.bin || {};
    if (!bin.metaharness || !bin.harness) return null;
    const metaharness = join(pkgDir, bin.metaharness);
    const harness = join(pkgDir, bin.harness);
    if (!existsSync(metaharness) || !existsSync(harness)) return null;
    return { metaharness, harness };
  } catch {
    return null;
  }
}

function degradedResult(resolved, start) {
  return {
    stdout: resolved.stdout ?? '',
    stderr: resolved.stderr ?? '',
    exitCode: 127,
    json: null,
    durationMs: Date.now() - start,
    degraded: true,
    reason: resolved.reason ?? REASON_NOT_AVAILABLE,
  };
}

/**
 * Async variant (iter 56) — used by oia-audit.mjs to parallelize its 5
 * subprocess calls, dropping worst-case wall-clock from 5×TIMEOUT to
 * 1×TIMEOUT. Identical return shape to the sync path.
 */
function execBinAsync(binName, args, opts = {}) {
  const start = Date.now();
  const resolved = resolveMetaharnessBins();
  if (!resolved.ok) return Promise.resolve(degradedResult(resolved, start));
  return new Promise((resolve) => {
    const timeoutMs = opts.timeoutMs ?? DEFAULT_TIMEOUT_MS;
    const wantJson = opts.json !== false;
    const argv = injectJson(args, wantJson);
    const p = spawn('node', [resolved.bins[binName], ...argv], {
      stdio: ['ignore', 'pipe', 'pipe'],
      cwd: opts.cwd,
      env: { ...process.env, ...(opts.env || {}) },
      shell: false,
    });
    let stdout = '', stderr = '';
    p.stdout?.on('data', (d) => { stdout += d.toString(); });
    p.stderr?.on('data', (d) => { stderr += d.toString(); });
    let timedOut = false;
    const timer = setTimeout(() => {
      timedOut = true;
      try { p.kill('SIGTERM'); } catch { /* ignore */ }
    }, timeoutMs);
    p.on('error', (e) => {
      clearTimeout(timer);
      resolve({
        stdout, stderr: stderr + String(e?.message ?? e),
        exitCode: 127, json: null, durationMs: Date.now() - start,
        degraded: true, reason: REASON_NOT_AVAILABLE,
      });
    });
    p.on('close', (code) => {
      clearTimeout(timer);
      const durationMs = Date.now() - start;
      const classified = classifyDegraded(stderr, timedOut ? null : code, 'metaharness');
      if (classified.degraded) {
        resolve({
          stdout, stderr,
          exitCode: code ?? 127, json: null, durationMs,
          degraded: true, reason: classified.reason,
        });
        return;
      }
      resolve({
        stdout, stderr,
        exitCode: code ?? 0,
        json: wantJson ? parseTrailingJson(stdout) : null,
        durationMs,
        degraded: false,
      });
    });
  });
}

/** Sync invocation of one of the two resolved bins via `node <abs-path>`. */
function execBin(binName, args, opts = {}) {
  const start = Date.now();
  const resolved = resolveMetaharnessBins();
  if (!resolved.ok) return degradedResult(resolved, start);
  const timeoutMs = opts.timeoutMs ?? DEFAULT_TIMEOUT_MS;
  const wantJson = opts.json !== false;
  const argv = injectJson(args, wantJson);
  const r = spawnSync('node', [resolved.bins[binName], ...argv], {
    stdio: ['ignore', 'pipe', 'pipe'],
    encoding: 'utf-8',
    timeout: timeoutMs,
    cwd: opts.cwd,  // iter 27 — let callers redirect $CWD (mint.mjs needs this)
    env: { ...process.env, ...(opts.env || {}) },
    shell: false,
  });
  const durationMs = Date.now() - start;
  const stdout = r.stdout || '';
  const stderr = r.stderr || '';
  const classified = classifyDegraded(stderr, r.status, 'metaharness');
  if (classified.degraded) {
    return {
      stdout, stderr,
      exitCode: r.status ?? 127,
      json: null,
      durationMs,
      degraded: true,
      reason: classified.reason,
    };
  }
  return {
    stdout, stderr,
    exitCode: r.status ?? 0,
    json: wantJson ? parseTrailingJson(stdout) : null,
    durationMs,
    degraded: false,
  };
}

export function runMetaharness(args, opts) {
  return execBin('metaharness', args, opts);
}

export function runHarness(args, opts) {
  // The `harness` binary ships inside the same `metaharness` package —
  // resolved from the package.json bin map above.
  return execBin('harness', args, opts);
}

export function runMetaharnessAsync(args, opts) {
  return execBinAsync('metaharness', args, opts);
}

export function runHarnessAsync(args, opts) {
  return execBinAsync('harness', args, opts);
}

/**
 * iter 63 — single source of truth for severity ranks across the
 * metaharness plugin family. Pre-iter-63, three scripts (oia-audit,
 * audit-trend, mcp-scan) maintained their own SEVERITY_RANK literal,
 * each missing different keys, each producing different NaN-compare
 * behavior on unknown severities. Iter 62 fixed oia-audit; iter 63
 * propagates the fix and consolidates.
 *
 * Mapping rationale:
 *   clean / info     → 0  (no harm)
 *   low              → 1
 *   medium / warn    → 2
 *   high / error     → 3
 *   critical         → 4  (explicit elevation above high)
 *
 * `rankSeverity(s)` is the safe accessor — returns 0 for any unknown
 * string instead of `undefined`, eliminating the NaN-compare hazard
 * (`undefined > 3` evaluates to false → unknown severities silently
 * ignored in reduce expressions).
 */
export const SEVERITY_RANK = Object.freeze({
  clean: 0, info: 0,
  low: 1,
  medium: 2, warn: 2,
  high: 3, error: 3,
  critical: 4,
});

export function rankSeverity(s) {
  if (s == null) return 0;
  return SEVERITY_RANK[String(s).toLowerCase()] ?? 0;
}

/**
 * iter 50 — parse `harness mcp-scan` text output into structured findings.
 *
 * Upstream `harness mcp-scan` emits plain text even with --json:
 *
 *     harness mcp-scan — <path>
 *
 *       [INFO] No MCP security issues found
 *              Policy is default-deny with safe capability grants and an audit log.
 *
 *     Result: INFO (1 finding, 0 high)
 *
 * Closes the iter-49-flagged gap where audit-trend.mjs reads
 * `json.findings` expecting an array, but mcp-scan's r.json was null.
 * Used by BOTH mcp-scan.mjs (the wrapper) and oia-audit.mjs (composite
 * audit) so the structured-findings invariant holds across the pipeline.
 */
export function parseMcpScanText(stdout) {
  const findings = [];
  const lines = (stdout || '').split('\n');
  let current = null;
  for (const line of lines) {
    const m = /^\s*\[([A-Z]+)\]\s+(.+?)\s*$/.exec(line);
    if (m) {
      if (current) findings.push(current);
      current = { severity: m[1].toLowerCase(), message: m[2] };
    } else if (current && /^\s{6,}\S/.test(line)) {
      const cont = line.trim();
      if (cont) current.message += ' ' + cont;
    } else if (current && line.trim() === '') {
      findings.push(current);
      current = null;
    }
  }
  if (current) findings.push(current);
  const resultMatch = /Result:\s+([A-Z]+)\s+\((\d+)\s+finding/i.exec(stdout);
  const summary = resultMatch ? {
    overallSeverity: resultMatch[1].toLowerCase(),
    totalCount: parseInt(resultMatch[2], 10),
  } : null;
  return { findings, summary };
}

// Convenience emitter for skill scripts — keep the boilerplate out of
// each skill so they focus on argument parsing + exit-code semantics.
// Exit 0 — ADR-150 architectural constraint says ruflo continues to
// function when MetaHarness is absent. Skills emit a structured
// degraded payload rather than failing.
export const emitDegradedJsonAndExit = makeDegradedEmitter(METAHARNESS_PKG, METAHARNESS_PIN_VERSION);

export const METAHARNESS_VERSION_PIN = `${METAHARNESS_PKG}@${METAHARNESS_PIN_VERSION}`;

/** Expose resolution for diagnostics/tests (which path served the bins). */
export function metaharnessResolution() {
  const r = resolveMetaharnessBins();
  return r.ok ? { ok: true, source: r.source, bins: r.bins } : { ok: false, reason: r.reason };
}

// _invoke.mjs — shared subprocess/plumbing layer for the metaharness plugin family.
//
// Extracted from the copy-pasted plumbing that had accreted across
// _harness.mjs / _darwin.mjs / _redblue.mjs / gepa.mjs (converged
// security/perf/arch review, 2026-07). The four invocation helpers are now
// thin adapters on top of this module; their exported function signatures
// are unchanged (~15 scripts import them).
//
// WHAT LIVES HERE (the genuinely-shared parts):
//   - DEGRADED_RX             one superset regex (incl. `npm ERR` — previously
//                             only _redblue had it) for "upstream unavailable"
//   - classifyDegraded()      timeout vs not-available distinction, per-package
//                             reason prefix
//   - injectJson()            append --json unless caller opted out / present
//   - parseTrailingJson()     LAST-{...}-block extraction (the _darwin variant;
//                             the old _harness FIRST-block variant was a live
//                             bug — a progress line containing `{...}` would
//                             shadow the final structured result)
//   - ensureCachedInstall()   one-time `npm install --prefix ~/.ruflo/<name>-cache-<pin>`
//                             of a PINNED range — generalizes _redblue.mjs /
//                             gepa.mjs; the versioned dir means pin bumps
//                             invalidate stale caches automatically
//   - findLocalPackageDir()   walk-up node_modules resolution so an already
//                             installed optionalDependency is used for free
//   - importOptionalLibrary() bare-import → cached-install fallback for
//                             library entries (gepa) — never throws on absence
//   - makeDegradedEmitter()   the ADR-150 rule-#3 exit-0 degraded payload
//
// WHAT DOES NOT LIVE HERE (the per-consumer parts):
//   - _redblue's node-direct isMain workaround rationale
//   - _darwin's async streaming (`onProgress`) for long evolve runs
//   - _harness's dual-binary (metaharness + harness) resolution
//
// TEST SEAMS (used by test-graceful-degradation.mjs so the ADR-150 drill
// stays meaningful on machines with a warm cache / local install):
//   - RUFLO_METAHARNESS_CACHE_BASE   overrides ~/.ruflo as the cache root
//   - RUFLO_METAHARNESS_SKIP_LOCAL=1 disables local node_modules resolution

import { spawnSync } from 'node:child_process';
import { existsSync, mkdirSync, readFileSync } from 'node:fs';
import { homedir } from 'node:os';
import { dirname, join } from 'node:path';
import { fileURLToPath, pathToFileURL } from 'node:url';

const INSTALL_TIMEOUT_MS = 180_000; // npm install can be slow on cold cache

// Superset of the three per-file regexes. `npm ERR` (from _redblue) is
// included for everyone: an npm-level failure during a cached install or an
// npx shim means "upstream unavailable", never a ruflo bug.
export const DEGRADED_RX = /could not determine executable|404|not installed|MODULE_NOT_FOUND|ENOTFOUND|getaddrinfo|ECONNREFUSED|ETIMEDOUT|npm ERR/i;

/**
 * Classify a finished subprocess as degraded or healthy.
 * `exitCode === null` means the harness killed it (timeout) — that is a
 * DIFFERENT operational signal from "package not installable", so the two
 * reasons stay distinct: `<prefix>-timeout` vs `<prefix>-not-available`.
 */
export function classifyDegraded(stderr, exitCode, reasonPrefix) {
  if (exitCode === null) return { degraded: true, reason: `${reasonPrefix}-timeout` };
  if (DEGRADED_RX.test(stderr || '')) return { degraded: true, reason: `${reasonPrefix}-not-available` };
  return { degraded: false };
}

/** Append --json unless the caller opted out or already passed it. */
export function injectJson(args, wantJson) {
  if (!wantJson || args.includes('--json')) return [...args];
  return [...args, '--json'];
}

/**
 * Parse the trailing JSON object from mixed stdout. CLIs in this family emit
 * human-readable progress first and a structured JSON object LAST — so grab
 * the last parseable {...} block, falling back to a greedy whole-span match
 * for nested objects the lazy regex fragments.
 */
export function parseTrailingJson(stdout) {
  const s = stdout || '';
  const matches = [...s.matchAll(/\{[\s\S]*?\}/g)];
  for (let i = matches.length - 1; i >= 0; i--) {
    try { return JSON.parse(matches[i][0]); } catch { /* try previous */ }
  }
  const greedy = /\{[\s\S]*\}/.exec(s);
  if (greedy) { try { return JSON.parse(greedy[0]); } catch { return null; } }
  return null;
}

/** Cache root — ~/.ruflo unless the test seam overrides it. */
export function cacheBaseDir() {
  return process.env.RUFLO_METAHARNESS_CACHE_BASE || join(homedir(), '.ruflo');
}

/** Minimal `~X.Y.Z` satisfaction check (no semver dep): same major.minor, patch >= Z. */
export function satisfiesTildeRange(version, pinVersion) {
  const pin = /^~(\d+)\.(\d+)\.(\d+)/.exec(String(pinVersion));
  const ver = /^(\d+)\.(\d+)\.(\d+)/.exec(String(version));
  if (!pin || !ver) return false;
  return ver[1] === pin[1] && ver[2] === pin[2] && parseInt(ver[3], 10) >= parseInt(pin[3], 10);
}

/**
 * Walk up node_modules from this plugin's directory AND from $CWD looking
 * for an already-installed copy of `pkg` (e.g. the optionalDependency the
 * user's ruflo install shipped with). Returns the package dir or null.
 * When `pinVersion` is given, only a copy satisfying the pin is accepted —
 * a stale major/minor in an ancestor node_modules is skipped, not used.
 */
export function findLocalPackageDir(pkg, pinVersion) {
  if (process.env.RUFLO_METAHARNESS_SKIP_LOCAL === '1') return null;
  const segments = pkg.split('/');
  const starts = [dirname(fileURLToPath(import.meta.url)), process.cwd()];
  const seen = new Set();
  for (const start of starts) {
    let dir = start;
    for (;;) {
      if (!seen.has(dir)) {
        seen.add(dir);
        const candidate = join(dir, 'node_modules', ...segments);
        const pj = join(candidate, 'package.json');
        if (existsSync(pj)) {
          if (!pinVersion) return candidate;
          try {
            const version = JSON.parse(readFileSync(pj, 'utf-8')).version;
            if (satisfiesTildeRange(version, pinVersion)) return candidate;
          } catch { /* unreadable — keep walking */ }
        }
      }
      const parent = dirname(dir);
      if (parent === dir) break;
      dir = parent;
    }
  }
  return null;
}

/**
 * One-time versioned cache install of a PINNED range. Generalizes
 * gepa.mjs:98-121 / _redblue.mjs:72-102. The cache dir is
 * `<base>/<shortname>-cache-<pin-digits>` (e.g. redblue-cache-0.1.4,
 * darwin-cache-0.8.0, metaharness-cache-0.3.0) so existing caches created
 * by the pre-consolidation helpers remain valid, and bumping the pin
 * invalidates stale installs automatically.
 *
 * @param {object} spec
 * @param {string} spec.pkg          npm package name (may be scoped)
 * @param {string} spec.pinVersion   tilde range, e.g. '~0.3.0'
 * @param {string} [spec.cliRelPath] path inside the package that must exist
 *                                   post-install (also returned as cliPath)
 * @param {number} [spec.timeoutMs]  install timeout (default 180s)
 * @returns {{ok:true, cacheDir:string, pkgDir:string, cliPath:string|null} |
 *           {ok:false, reason:string, stderr?:string, stdout?:string, error?:string}}
 */
export function ensureCachedInstall({ pkg, pinVersion, cliRelPath, timeoutMs = INSTALL_TIMEOUT_MS }) {
  const short = pkg.split('/').pop();
  const cacheDir = join(cacheBaseDir(), `${short}-cache-${pinVersion.replace(/[~^]/g, '')}`);
  const pkgDir = join(cacheDir, 'node_modules', ...pkg.split('/'));
  const cliPath = cliRelPath ? join(pkgDir, cliRelPath) : null;
  const probe = cliPath ?? join(pkgDir, 'package.json');
  if (existsSync(probe)) return { ok: true, cacheDir, pkgDir, cliPath };
  try {
    mkdirSync(cacheDir, { recursive: true });
  } catch (e) {
    return { ok: false, reason: 'cache-dir-create-failed', error: String(e) };
  }
  // `npm install --prefix` puts the package in a known location; this both
  // avoids npx's symlinked bin shim (the _redblue isMain upstream bug) and
  // removes the per-call registry check that `npx -y pkg@latest` forced.
  // shell:false; argv only.
  const r = spawnSync('npm', [
    'install',
    '--no-audit', '--no-fund', '--no-package-lock',
    '--prefix', cacheDir,
    `${pkg}@${pinVersion}`,
  ], {
    stdio: ['ignore', 'pipe', 'pipe'],
    encoding: 'utf-8',
    timeout: timeoutMs,
    shell: process.platform === 'win32',
  });
  if (r.status !== 0 || !existsSync(probe)) {
    return {
      ok: false,
      reason: 'install-failed',
      stderr: (r.stderr || '').slice(0, 600),
      stdout: (r.stdout || '').slice(0, 600),
    };
  }
  return { ok: true, cacheDir, pkgDir, cliPath };
}

/**
 * Import an optional LIBRARY entry (as opposed to spawning a CLI):
 *   1. bare `import(specifier)` — free when the optional dep is installed in
 *      an ancestor node_modules;
 *   2. versioned cache install + file-URL import of `entryRelPath`.
 * Returns the module namespace or null. Never throws on absence / stale
 * installs (ERR_PACKAGE_PATH_NOT_EXPORTED covers pre-subpath versions).
 */
export async function importOptionalLibrary({ specifier, pkg, pinVersion, entryRelPath }) {
  try {
    return await import(specifier);
  } catch (e) {
    const msg = String(e?.message ?? e);
    const recoverable = /Cannot find (module|package)|ERR_MODULE_NOT_FOUND|MODULE_NOT_FOUND|ERR_PACKAGE_PATH_NOT_EXPORTED|is not defined by "exports"/i;
    if (!recoverable.test(msg)) throw e;
  }
  const r = ensureCachedInstall({ pkg, pinVersion, cliRelPath: entryRelPath });
  if (!r.ok || !r.cliPath) return null;
  try {
    return await import(pathToFileURL(r.cliPath).href);
  } catch {
    return null;
  }
}

/**
 * Build the per-package `emit*DegradedJsonAndExit(reason)` helper. Emits the
 * structured degraded payload and exits 0 — ADR-150 architectural constraint
 * rule #3: ruflo continues to function when MetaHarness is absent.
 */
export function makeDegradedEmitter(pkg, pinVersion) {
  return function emitDegradedAndExit(reason) {
    const payload = {
      degraded: true,
      reason,
      hint: `Install with \`npm i -D ${pkg}@${pinVersion}\` (pinned range — this plugin never fetches @latest) or verify network access for the one-time cache install.`,
      generatedAt: new Date().toISOString(),
    };
    console.log(JSON.stringify(payload, null, 2));
    process.exit(0);
  };
}

// _redblue.mjs — invocation helper for `@metaharness/redblue`.
//
// Sibling of `_darwin.mjs` / `_harness.mjs`. Targets the `redblue` binary
// from the standalone `@metaharness/redblue@~0.1.4` package. Shared plumbing
// (degraded classification, versioned cache install, degraded emitter) lives
// in `_invoke.mjs`; what stays here is the genuinely-redblue part: the
// node-direct invocation rationale below.
//
// Subcommands surfaced (matches redblue 0.1.x):
//   - `redblue init   [--out redblue.yaml]`
//   - `redblue run    [--config redblue.yaml] [--tests N] [--patch] [--mock-judge] [--out report.json]`
//   - `redblue attack <prompt|tools|data|all> [--count N]`
//   - `redblue patch  [--config redblue.yaml] [--mock-judge]`
//   - `redblue report --in report.json`
//
// UPSTREAM BUG WORKAROUND
// -----------------------
// @metaharness/redblue@0.1.1's CLI bootstrap is:
//     const isMain = import.meta.url === `file://${process.argv[1]}`;
//     if (isMain) { dispatch(...) }
// When npx links `redblue` → `dist/cli/index.js`, process.argv[1] is the
// symlink path but import.meta.url is the resolved real path, so the
// check fails silently — the binary exits 0 with no output, no file,
// no error. Darwin's CLI doesn't suffer this (calls main() unconditionally).
//
// Workaround: install the package once into a ruflo-owned cache dir
// (~/.ruflo/redblue-cache-<pin>, via _invoke.ensureCachedInstall) and invoke
// `node <abs_path>/dist/cli/index.js` directly. argv[1] then equals the real
// path and isMain becomes true.
//
// Track upstream fix at: github.com/ruvnet/agent-harness-generator/issues
// (file separately — when fixed, we could go back to a bin-shim pattern,
// though the node-direct cached path is now the family-wide standard anyway).
//
// CONTRACT (matches runMetaharness/runDarwin):
//   - returns `{ stdout, stderr, exitCode, durationMs, degraded, reason? }`
//   - subprocess hard timeout (default 120s; --mock-judge runs are seconds)
//   - on install failure / MODULE_NOT_FOUND / network failure, returns
//     `degraded: true, reason: 'metaharness-redblue-not-available'`
//   - never throws — ADR-150 graceful-degradation rule #3
//
// SAFETY NOTE
//   redblue itself enforces hard safety boundaries in `src/config/safety.ts`
//   (no real creds, no live targets, no shell, no eval, no arbitrary network).
//   This wrapper does NOT relax those — it only forwards argv with shell:false.
//   `--mock-judge` is the $0 CI path; the real model judge gates on
//   $OPENROUTER_API_KEY which we never inject.

import { spawnSync } from 'node:child_process';
import { homedir } from 'node:os';
import { join } from 'node:path';
import {
  classifyDegraded,
  ensureCachedInstall,
  makeDegradedEmitter,
} from './_invoke.mjs';

const DEFAULT_TIMEOUT_MS = 120_000;

// Pinned semver range. Bump in lock-step with optionalDependencies in
// @claude-flow/cli/package.json + ruflo/package.json.
const REDBLUE_PKG = '@metaharness/redblue';
const REDBLUE_PIN_VERSION = '~0.1.4';
const REDBLUE_PIN = `${REDBLUE_PKG}@${REDBLUE_PIN_VERSION}`;

const REASON_PREFIX = 'metaharness-redblue';

// Cache dir is versioned by the pin so bumping REDBLUE_PIN_VERSION
// invalidates stale installs (handled inside ensureCachedInstall). The
// resolved layout matches the pre-consolidation helper so existing caches
// keep serving.
const CLI_REL_PATH = join('dist', 'cli', 'index.js');

/**
 * Sync invocation. `redblue` runs are bounded by `max_cost_usd` and
 * `max_runtime_minutes` from the config, so sync is fine for the CLI
 * wrapper. The default --mock-judge fixture path completes in seconds.
 */
export function runRedblue(args, opts = {}) {
  const start = Date.now();
  const timeoutMs = opts.timeoutMs ?? DEFAULT_TIMEOUT_MS;

  // 1. Ensure redblue is installed in our cache dir (one-time install).
  const install = ensureCachedInstall({
    pkg: REDBLUE_PKG,
    pinVersion: REDBLUE_PIN_VERSION,
    cliRelPath: CLI_REL_PATH,
  });
  if (!install.ok) {
    return {
      stdout: install.stdout ?? '',
      stderr: install.stderr ?? install.error ?? '',
      exitCode: 127,
      durationMs: Date.now() - start,
      degraded: true,
      reason: install.reason === 'install-failed'
        ? `${REASON_PREFIX}-not-available`
        : `${REASON_PREFIX}-${install.reason}`,
    };
  }

  // 2. Invoke `node <real-path-to-cli> <args>` so upstream's isMain check
  //    succeeds (argv[1] matches import.meta.url).
  const r = spawnSync('node', [install.cliPath, ...args], {
    stdio: ['ignore', 'pipe', 'pipe'],
    encoding: 'utf-8',
    timeout: timeoutMs,
    cwd: opts.cwd,
    env: { ...process.env, ...(opts.env || {}) },
    shell: process.platform === 'win32',
  });
  const durationMs = Date.now() - start;
  const stdout = r.stdout || '';
  const stderr = r.stderr || '';
  const classified = classifyDegraded(stderr, r.status, REASON_PREFIX);
  if (classified.degraded) {
    return {
      stdout, stderr,
      exitCode: r.status ?? 127,
      durationMs,
      degraded: true,
      reason: classified.reason,
    };
  }
  return {
    stdout, stderr,
    exitCode: r.status ?? 0,
    durationMs,
    degraded: false,
  };
}

/**
 * Match the existing `emit*DegradedJsonAndExit` shape used by sibling
 * scripts so MCP tool consumers see one contract. Exit 0 — ADR-150
 * architectural constraint #3.
 */
export const emitRedblueDegradedJsonAndExit = makeDegradedEmitter(REDBLUE_PKG, REDBLUE_PIN_VERSION);

export const REDBLUE_VERSION_PIN = REDBLUE_PIN;
export const REDBLUE_CACHE_DIR = join(
  homedir(), '.ruflo', `redblue-cache-${REDBLUE_PIN_VERSION.replace(/[~^]/g, '')}`,
);

// _similarity.mjs — ADR-152 production similarity module.
//
// Graduated from `_spike-similarity.mjs` (iter 35) after both invariants
// passed on the LEGAL/SUPPORT/DEVOPS fixtures. The spike file STAYS as
// the regression-suite anchor; this file is what production callers
// (`similarity.mjs` skill, `metaharness_similarity` MCP tool) import.
//
// ADR-150 ARCHITECTURAL CONSTRAINTS PRESERVED
//   Removable ✓  pure-TS — no `@metaharness/*` import path
//   Optional  ✓  no new dep on `@metaharness/*`
//   Graceful  ✓  malformed input → low-confidence output, never throws
//   CI-gate   ✓  standalone unit-importable; no `npx` needed
//
// CONTRACT (PUBLIC)
//   projectToVec(input)            → 9-dim numerical feature vector
//   cosine(a, b)                   → [0,1]
//   categoricalAgreement(a, b)     → [0,1] over 4 enum fields
//   jaccard(a, b)                  → [0,1] over agent_topology[]
//   similarity(a, b, opts?)        → { overall, components, perDimension? }
//
// WEIGHT DEFAULTS (from ADR-152 §Decision)
//   overall = 0.60·cosine + 0.25·categorical + 0.15·jaccard
//
// ADR-152 reserves a future per-org weight override; for §3.1 the defaults
// are global. The opts.weights hook is here so consumers can experiment
// without forking the module — it is NOT a stable public API.

const DEFAULT_WEIGHTS = Object.freeze({ cosine: 0.6, categorical: 0.25, jaccard: 0.15 });

const CATEGORICAL_FIELDS = Object.freeze(['repo_type', 'archetype', 'template', 'recommendedMode']);

// ─────────────────────────────────────────────────────────────────────
// 9-dim feature vector. The mapping mirrors ADR-152 §Decision Table 1.
// Missing fields default to 0 — that's the graceful-degradation path.
// ─────────────────────────────────────────────────────────────────────

export function projectToVec(input) {
  const s = input?.score ?? {};
  const g = input?.genome ?? {};
  return [
    (s.harnessFit ?? 0) / 100,
    (s.compileConfidence ?? 0) / 100,
    (s.taskCoverage ?? 0) / 100,
    (s.toolSafety ?? 0) / 100,
    (s.memoryUsefulness ?? 0) / 100,
    g.risk_score ?? 0,
    g.test_confidence ?? 0,
    g.publish_readiness ?? 0,
    Math.max(0, Math.min(1, Math.log10((s.estCostPerRunUsd ?? 0) + 0.001) / Math.log10(10))),
  ];
}

export function cosine(a, b) {
  if (!Array.isArray(a) || !Array.isArray(b) || a.length !== b.length) return 0;
  let dot = 0, na = 0, nb = 0;
  for (let i = 0; i < a.length; i++) {
    dot += a[i] * b[i];
    na += a[i] * a[i];
    nb += b[i] * b[i];
  }
  const denom = Math.sqrt(na) * Math.sqrt(nb);
  if (denom === 0) return 0;
  return Math.max(0, Math.min(1, dot / denom));
}

export function categoricalAgreement(a, b) {
  let matches = 0;
  for (const f of CATEGORICAL_FIELDS) {
    const av = a?.genome?.[f] ?? a?.score?.[f];
    const bv = b?.genome?.[f] ?? b?.score?.[f];
    if (av && bv && av === bv) matches++;
  }
  return matches / CATEGORICAL_FIELDS.length;
}

export function jaccard(a, b) {
  const A = new Set(a?.genome?.agent_topology ?? []);
  const B = new Set(b?.genome?.agent_topology ?? []);
  if (A.size === 0 && B.size === 0) return 1;
  const intersection = [...A].filter((x) => B.has(x)).length;
  const union = new Set([...A, ...B]).size;
  return union === 0 ? 0 : intersection / union;
}

// ─────────────────────────────────────────────────────────────────────
// Composite similarity with optional per-dimension breakdown.
// Returns the ADR-152 §"return shape": overall + components + per-dim.
// ─────────────────────────────────────────────────────────────────────

export function similarity(a, b, opts = {}) {
  const weights = { ...DEFAULT_WEIGHTS, ...(opts.weights ?? {}) };
  const va = projectToVec(a);
  const vb = projectToVec(b);
  const cos = cosine(va, vb);
  const cat = categoricalAgreement(a, b);
  const jac = jaccard(a, b);

  const overall = weights.cosine * cos + weights.categorical * cat + weights.jaccard * jac;

  const result = {
    overall: round4(overall),
    components: {
      cosine: round4(cos),
      categorical: round4(cat),
      jaccard: round4(jac),
    },
    weights,
  };

  if (opts.perDimension) {
    result.perDimension = perDimensionBreakdown(a, b, va, vb, weights);
  }
  return result;
}

function round4(x) {
  return Math.round(x * 10000) / 10000;
}

function perDimensionBreakdown(a, b, va, vb, weights) {
  // Per-dimension contribution = squared-error-normalized cosine slice + categorical/jaccard direct.
  // We surface raw a/b values + a contribution sign so callers can explain
  // why two harnesses scored as they did (used by Recommendation Engine
  // §3.2 confidence calc + Drift Detection §3.3 alert reason).
  const out = {};

  const numericKeys = [
    ['harnessFit', 'score', 100], ['compileConfidence', 'score', 100],
    ['taskCoverage', 'score', 100], ['toolSafety', 'score', 100],
    ['memoryUsefulness', 'score', 100],
    ['risk_score', 'genome', 1], ['test_confidence', 'genome', 1],
    ['publish_readiness', 'genome', 1],
    ['estCostPerRunUsd', 'score', 1],
  ];
  for (let i = 0; i < numericKeys.length; i++) {
    const [k, src] = numericKeys[i];
    const av = a?.[src]?.[k];
    const bv = b?.[src]?.[k];
    out[`numeric.${k}`] = {
      a: av ?? null, b: bv ?? null,
      contribution: round4(va[i] * vb[i] * weights.cosine / 9),
    };
  }
  for (const f of CATEGORICAL_FIELDS) {
    const av = a?.genome?.[f] ?? a?.score?.[f];
    const bv = b?.genome?.[f] ?? b?.score?.[f];
    out[`categorical.${f}`] = {
      a: av ?? null, b: bv ?? null,
      contribution: av && bv && av === bv ? round4(weights.categorical / 4) : 0,
    };
  }
  const A = new Set(a?.genome?.agent_topology ?? []);
  const B = new Set(b?.genome?.agent_topology ?? []);
  const overlap = [...A].filter((x) => B.has(x));
  const union = new Set([...A, ...B]);
  out['set.agent_topology'] = {
    a: [...A], b: [...B],
    contribution: union.size === 0 ? 0 : round4((overlap.length / union.size) * weights.jaccard),
  };
  return out;
}

#!/usr/bin/env node
// _spike-similarity.mjs — ADR-152 §"Smallest demonstrable spike" gate.
//
// This file is the implementation gate for ADR-152 (Genome Similarity Search).
// Per ADR-151's scope-only constraint, ADR-152 cannot graduate to "Accepted"
// until the two invariants below are proven by running this script.
//
// THE TWO INVARIANTS (from ADR-152 §"Smallest demonstrable spike")
//   1. similarity(X, X) === 1                        (self-match exact)
//   2. similarity(legal, devops) < similarity(legal, support)
//                                                    (vertical-affinity correct)
//
// USAGE
//   node scripts/_spike-similarity.mjs               (run + assert)
//   node scripts/_spike-similarity.mjs --format json (CI-consumable)
//
// EXIT CODES
//   0  both invariants hold
//   1  at least one invariant fails (ADR-152 cannot graduate)
//
// LIFECYCLE
// Once ADR-152 is Accepted, the full similarity implementation lands in
// `_similarity.mjs` (production module). This file (`_spike-similarity.mjs`)
// remains as the regression-suite anchor for the two invariants.

const ARGS = (() => {
  const a = { format: 'table' };
  for (let i = 2; i < process.argv.length; i++) {
    if (process.argv[i] === '--format') a.format = process.argv[++i];
  }
  return a;
})();

// ──────────────────────────────────────────────────────────────────────
// THE PROPOSED IMPLEMENTATION (ADR-152 §"Decision")
//
// Pure-TS. Takes two {genome, score} JSON shapes; emits {overall,
// components: {cosine, categorical, jaccard}}. The 9 numerical features +
// 4 categorical fields + 1 set field per ADR-152.
// ──────────────────────────────────────────────────────────────────────

function projectToVec(input) {
  const s = input.score || {};
  const g = input.genome || {};
  return [
    (s.harnessFit ?? 0) / 100,
    (s.compileConfidence ?? 0) / 100,
    (s.taskCoverage ?? 0) / 100,
    (s.toolSafety ?? 0) / 100,
    (s.memoryUsefulness ?? 0) / 100,
    g.risk_score ?? 0,
    g.test_confidence ?? 0,
    g.publish_readiness ?? 0,
    // estCostPerRunUsd: log10 transform, clamped to [0, 1]
    Math.max(0, Math.min(1, Math.log10((s.estCostPerRunUsd ?? 0) + 0.001) / Math.log10(10))),
  ];
}

function cosine(a, b) {
  let dot = 0, na = 0, nb = 0;
  for (let i = 0; i < a.length; i++) {
    dot += a[i] * b[i];
    na += a[i] * a[i];
    nb += b[i] * b[i];
  }
  const denom = Math.sqrt(na) * Math.sqrt(nb);
  if (denom === 0) return 0;
  // Map cosine from [-1, 1] to [0, 1] for nonnegative vectors it's [0, 1] already
  return Math.max(0, Math.min(1, dot / denom));
}

function categoricalAgreement(a, b) {
  const fields = ['repo_type', 'archetype', 'template', 'recommendedMode'];
  let matches = 0;
  for (const f of fields) {
    const av = a.genome?.[f] ?? a.score?.[f];
    const bv = b.genome?.[f] ?? b.score?.[f];
    if (av && bv && av === bv) matches++;
  }
  return matches / fields.length;
}

function jaccard(a, b) {
  const A = new Set(a.genome?.agent_topology ?? []);
  const B = new Set(b.genome?.agent_topology ?? []);
  if (A.size === 0 && B.size === 0) return 1;
  const intersection = [...A].filter((x) => B.has(x)).length;
  const union = new Set([...A, ...B]).size;
  return union === 0 ? 0 : intersection / union;
}

function similarity(a, b) {
  const cos = cosine(projectToVec(a), projectToVec(b));
  const cat = categoricalAgreement(a, b);
  const jac = jaccard(a, b);
  const overall = 0.6 * cos + 0.25 * cat + 0.15 * jac;
  return {
    overall: Math.round(overall * 10000) / 10000,
    components: {
      cosine: Math.round(cos * 10000) / 10000,
      categorical: Math.round(cat * 10000) / 10000,
      jaccard: Math.round(jac * 10000) / 10000,
    },
  };
}

// ──────────────────────────────────────────────────────────────────────
// THREE SYNTHETIC FIXTURES designed to exercise the invariants. These
// mirror the JSON shapes `harness genome` + `harness score` emit (verified
// against metaharness@0.1.14 via iter-26 test-with-openrouter.mjs).
// ──────────────────────────────────────────────────────────────────────

