  },
};

// ───────────────────────────────────────────────────────────────────
// Benchmark harness
// ───────────────────────────────────────────────────────────────────

function bench(label, a, b, iters) {
  // Warm-up
  for (let i = 0; i < 10_000; i++) similarity(a, b);

  const samples = new Float64Array(iters);
  for (let i = 0; i < iters; i++) {
