      console.log(`⚠ ALERT: mean per-call exceeded ${ARGS.maxMeanUs}μs ceiling:`);
      for (const reason of payload.gate.reasons) console.log(`    - ${reason}`);
    } else {
      console.log(`✓ all categories within --max-mean-us ${ARGS.maxMeanUs}μs ceiling`);
    }
  }
}

if (gate.triggered) process.exit(1);

#!/usr/bin/env node
// bench.mjs — wrapper around `metaharness-darwin bench <create|verify>`.
//
// Bench suites are JSON files describing a corpus of (input, expected-output)
// tasks. `evolve --bench <suite.json>` scores each variant against the
// corpus instead of (or in addition to) the project's test command, which
// lets you evolve a harness against a fixed evaluation set independent of
// the repo's natural tests. `bench create` scaffolds a suite from a repo;
// `bench verify` checks a suite parses and every task is well-formed.
//
// USAGE
//   node scripts/bench.mjs --op create --repo .              # scaffold suite.json from current dir
//   node scripts/bench.mjs --op create --repo . --out /tmp/foo.json
//   node scripts/bench.mjs --op verify --suite /tmp/foo.json
//
// EXIT CODES
//   0  ok (or degraded — Darwin not available)
//   1  --op verify and any task malformed
//   2  config error or upstream invocation failure

import { runDarwin, emitDarwinDegradedJsonAndExit } from './_darwin.mjs';
import { existsSync } from 'node:fs';
import { resolve } from 'node:path';

const ARGS = (() => {
  const a = { op: null, repo: '.', suite: null, out: null, format: 'json' };
  for (let i = 2; i < process.argv.length; i++) {
    const v = process.argv[i];
    if (v === '--op') a.op = process.argv[++i];
    else if (v === '--repo') a.repo = process.argv[++i];
    else if (v === '--suite') a.suite = process.argv[++i];
    else if (v === '--out') a.out = process.argv[++i];
    else if (v === '--format') a.format = process.argv[++i];
  }
  return a;
})();

function safetyChecks() {
  if (!['create', 'verify'].includes(ARGS.op)) {
    console.error('bench: --op must be create|verify');
    process.exit(2);
  }
  if (ARGS.op === 'create' && !existsSync(resolve(ARGS.repo))) {
    console.error(`bench: --repo path does not exist: ${ARGS.repo}`);
    process.exit(2);
  }
  if (ARGS.op === 'verify' && !ARGS.suite) {
    console.error('bench: --suite is required for verify');
    process.exit(2);
  }
  if (ARGS.op === 'verify' && !existsSync(resolve(ARGS.suite))) {
    console.error(`bench: --suite path does not exist: ${ARGS.suite}`);
    process.exit(2);
  }
}

function main() {
  safetyChecks();

  const cliArgs = ARGS.op === 'create'
    ? ['bench', 'create', resolve(ARGS.repo), ...(ARGS.out ? ['--out', resolve(ARGS.out)] : [])]
    : ['bench', 'verify', resolve(ARGS.suite)];

  const r = runDarwin(cliArgs, { timeoutMs: 60_000 });

  if (r.degraded) {
    emitDarwinDegradedJsonAndExit(r.reason);
    return;
  }

  if (r.exitCode !== 0 && r.exitCode !== 1) {
    const payload = {
      success: false,
      data: { exitCode: r.exitCode, stderrTail: r.stderr.slice(-400) },
      generatedAt: new Date().toISOString(),
    };
    console.log(JSON.stringify(payload, null, 2));
    process.exit(2);
  }

  const payload = {
    success: r.exitCode === 0,
    data: {
      op: ARGS.op,
      ...(r.json ?? { stdoutTail: r.stdout.slice(-2000) }),
      durationMs: r.durationMs,
    },
    generatedAt: new Date().toISOString(),
  };

  console.log(JSON.stringify(payload, null, 2));
  process.exit(r.exitCode);
}

main();

#!/usr/bin/env node
// drift-from-history.mjs — iter 53 — one-command drift detection.
//
// Composes the existing pipeline into the workflow users actually want:
// "did my repo drift since the last audit?" Implementation:
//
//   1. List audit records from `metaharness-audit` memory namespace
//   2. Pick the most recent one (or filter --since Nd to skip recent ones
//      and use an older baseline)
//   3. Run a fresh oia-audit against the current repo state
//   4. Diff via audit-trend → structural distance + severity rollup
//   5. Alert if structural similarity falls below --threshold
//
// Until this iter, doing this required the user to:
//   $ npx ruflo metaharness audit-list --format json
//   $ # ... pick a key by hand from the listing
//   $ npx ruflo metaharness oia-audit --format json > /tmp/curr.json
//   $ npx ruflo metaharness audit-trend --baseline-key X --current-file /tmp/curr.json
// Now it's:
//   $ npx ruflo metaharness drift-from-history --threshold 0.95
//
// USAGE
//   node scripts/drift-from-history.mjs                       # default: last record vs now
//   node scripts/drift-from-history.mjs --baseline-since 7d   # use an audit ≥ 7d old
//   node scripts/drift-from-history.mjs --threshold 0.95      # alert under 0.95 similarity
//   node scripts/drift-from-history.mjs --format json
//   node scripts/drift-from-history.mjs --dry-run             # don't persist current
//
// EXIT CODES
//   0  ok (no drift below --threshold)
//   1  drift below --threshold (alert fired)
//   2  config / input error (no history available, etc.)
//   3  upstream metaharness absent — degraded payload returned

import { spawnSync, spawn } from 'node:child_process';
// iter 78 — share the iter-63 SEVERITY_RANK for the new finding-alert gate
import { rankSeverity } from './_harness.mjs';
import { mkdtempSync, writeFileSync, rmSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join, dirname } from 'node:path';
import { fileURLToPath } from 'node:url';

const SCRIPTS_DIR = dirname(fileURLToPath(import.meta.url));
const NS = process.env.METAHARNESS_AUDIT_NAMESPACE || 'metaharness-audit';
const CLI_PKG = process.env.CLI_CORE === '1'
  ? '@claude-flow/cli-core@alpha'
  : '@claude-flow/cli@latest';

const ARGS = (() => {
  const a = {
    path: '.', baselineSince: null, baselineKey: null, baselineFile: null,
    threshold: 0.95, dryRun: false, format: 'table',
    // iter 78 — opt-in finding-severity alert gate. Default null (off)
    // preserves iter-53 behavior; set to a severity name to ALSO alert
    // when any introduced finding meets or exceeds that severity.
    alertOnNewSeverity: null,
  };
  for (let i = 2; i < process.argv.length; i++) {
    const v = process.argv[i];
    if (v === '--path') a.path = process.argv[++i];
    else if (v === '--baseline-since') a.baselineSince = process.argv[++i];
    // iter 66 — explicit baseline-key skips the ONNX-heavy audit-list
    // call entirely. Cron jobs that know the key avoid the ~25s warmup.
    else if (v === '--baseline-key') a.baselineKey = process.argv[++i];
    // iter 67 — baseline-file goes further: no memory call at all.
    // Useful for CI workflows that store last-run audit as an artifact
    // and download it for diff against fresh audit.
    else if (v === '--baseline-file') a.baselineFile = process.argv[++i];
    else if (v === '--threshold') a.threshold = Number(process.argv[++i]);
    else if (v === '--dry-run') a.dryRun = true;
    else if (v === '--format') a.format = process.argv[++i];
    // iter 78 — orthogonal alert: any new finding ≥ this severity triggers
    else if (v === '--alert-on-new-severity') a.alertOnNewSeverity = String(process.argv[++i]).toLowerCase();
  }
  return a;
})();

function emitAndExit(payload, code) {
  if (ARGS.format === 'json') {
    console.log(JSON.stringify(payload, null, 2));
  } else {
    console.log(`# drift-from-history\n`);
    if (payload.degraded) {
      console.log(`⊘ ${payload.reason}`);
    } else if (payload.error) {
      console.log(`✗ ${payload.error}`);
    } else {
      console.log(`Baseline:        ${payload.baseline?.key ?? payload.baseline?.startedAt}`);
      console.log(`Current:         ${payload.current?.startedAt ?? '(fresh)'}`);
      // iter 96 — surface the timing.path label so users see which
      // fast-path ran (or didn't) at a glance.
      if (payload.timing?.path) {
        const wallMs = payload.timing.parallelWallMs;
        console.log(`Path:            ${payload.timing.path} (wall ${wallMs}ms)`);
      }
      console.log('');
      const sd = payload.drift?.structuralDistance;
      if (sd && sd.verdict !== 'unavailable') {
        console.log(`Structural similarity: ${sd.overall} (${sd.verdict})`);
        console.log(`Distance:              ${sd.distance}`);
      }
      console.log('');
      if (payload.alert?.triggered) {
        console.log(`⚠ ALERT: ${payload.alert.reason}`);
      } else if (payload.alert) {
        console.log(`✓ ${payload.alert.reason}`);
      }
    }
  }
  process.exit(code);
}

function runScriptJson(script, args) {
  const r = spawnSync('node', [join(SCRIPTS_DIR, script), ...args, '--format', 'json'], {
    encoding: 'utf-8',
  });
  const m = /\{[\s\S]*\}/.exec(r.stdout || '');
  const json = m ? JSON.parse(m[0]) : null;
  // audit-list emits {records:[...]} — check that shape too
  const arrM = /\[[\s\S]*\]/.exec(r.stdout || '');
  return { json, exitCode: r.status ?? -1, stdout: r.stdout || '', stderr: r.stderr || '', arrMatch: arrM };
}

/**
 * iter 58 — async variant. Drift-from-history's audit-list (memory query)
 * and oia-audit (fresh subprocess chain) are mutually independent and
 * can race. This shaves ~2-5s off every drift check by overlapping the
 * subprocess wait time.
 */
function runScriptJsonAsync(script, args) {
  return new Promise((resolve) => {
    const p = spawn('node', [join(SCRIPTS_DIR, script), ...args, '--format', 'json'], {
      stdio: ['ignore', 'pipe', 'pipe'],
    });
    let stdout = '', stderr = '';
    p.stdout?.on('data', (d) => { stdout += d.toString(); });
    p.stderr?.on('data', (d) => { stderr += d.toString(); });
    p.on('close', (code) => {
      const m = /\{[\s\S]*\}/.exec(stdout);
      let json = null;
      if (m) { try { json = JSON.parse(m[0]); } catch { /* leave null */ } }
      resolve({ json, exitCode: code ?? -1, stdout, stderr });
    });
    p.on('error', () => resolve({ json: null, exitCode: 127, stdout, stderr: 'spawn-failed' }));
  });
}

async function main() {
  // iter 58 — parallelize audit-list + oia-audit. They're mutually
  // independent (audit-list queries memory, oia-audit runs fresh
  // metaharness subprocesses) so racing them shaves ~2-5s off every
  // drift check. The audit-trend step still serializes after because
  // it consumes both prior outputs.
  const listArgs = ['--limit', '50'];
  if (ARGS.baselineSince) listArgs.push('--since', ARGS.baselineSince);
  const auditArgs = ['--path', ARGS.path];
  if (ARGS.dryRun) auditArgs.push('--dry-run');

  // iter 65 — measure parallel batch wall-clock so a future iter that
  // accidentally serializes (await audit-list; await oia-audit) doesn't
  // silently regress. timing.parallelSpeedup is surfaced in payload.
  // iter 66 — when --baseline-key is provided, skip audit-list entirely
  // (it's ~25s of ONNX warmup for what would be one record lookup).
  // Run oia-audit alone in that case.
  const parallelStart = Date.now();
  const listStart = Date.now();
  const auditStart = Date.now();
  let listResult;
  let auditResult;
  let skippedAuditList = false;
  let usedBaselineFile = false;
  if (ARGS.baselineFile) {
    // iter 67 fast-fast path — baseline already on disk. Skip
    // audit-list AND skip memory roundtrip when running audit-trend.
    skippedAuditList = true;
    usedBaselineFile = true;
    listResult = {
      json: { records: [{ key: `file:${ARGS.baselineFile}`, startedAt: null }] },
      exitCode: 0, stdout: '', stderr: '', durationMs: 0,
    };
    auditResult = await runScriptJsonAsync('oia-audit.mjs', auditArgs);
    auditResult.durationMs = Date.now() - auditStart;
  } else if (ARGS.baselineKey) {
    skippedAuditList = true;
    // Synthesize a list result containing the user-provided key.
    // No memory call needed — drift-from-history's downstream code
    // only reads the `key` field from the picked record.
    listResult = {
      json: { records: [{ key: ARGS.baselineKey, startedAt: null }] },
      exitCode: 0,
      stdout: '',
      stderr: '',
      durationMs: 0,
    };
    auditResult = await runScriptJsonAsync('oia-audit.mjs', auditArgs);
    auditResult.durationMs = Date.now() - auditStart;
  } else {
    [listResult, auditResult] = await Promise.all([
      runScriptJsonAsync('audit-list.mjs', listArgs)
        .then((r) => ({ ...r, durationMs: Date.now() - listStart })),
      runScriptJsonAsync('oia-audit.mjs', auditArgs)
        .then((r) => ({ ...r, durationMs: Date.now() - auditStart })),
    ]);
  }
  const parallelWallMs = Date.now() - parallelStart;
  const parallelSumMs = (listResult.durationMs || 0) + (auditResult.durationMs || 0);

  if (listResult.exitCode !== 0) {
    emitAndExit({
      error: `audit-list failed (exit ${listResult.exitCode})`,
      stderrTail: listResult.stderr.slice(-200),
    }, 2);
  }
  const records = listResult.json?.records ?? listResult.json?.entries ?? [];
  if (records.length === 0) {
    // iter 57 + iter 58 — disambiguate "no history yet" (exit 2) from
    // "metaharness absent" (exit 3). Use the audit we already ran
    // (iter 58 fused the probe into the parallel batch) — no extra
    // subprocess needed.
    if (auditResult.json?.degraded === true) {
      emitAndExit({
        degraded: true,
        reason: auditResult.json.reason || 'metaharness-not-available',
        hint: 'Install metaharness to enable drift detection.',
      }, 3);
    }
    emitAndExit({
      error: 'no audit records found in namespace ' + NS,
      hint: 'Run `ruflo metaharness oia-audit` at least once to seed history.',
    }, 2);
  }
  // Pick the most recent record (records are typically newest-first; if not,
  // sort by startedAt). Each record's key is in the entry.
  const sorted = [...records].sort((a, b) =>
    String(b.startedAt ?? b.key ?? '').localeCompare(String(a.startedAt ?? a.key ?? '')));
  const baseline = sorted[0];
  if (!baseline?.key) {
    emitAndExit({
      error: 'audit record has no `key` field — cannot reference',
      sample: baseline,
    }, 2);
  }

  // Step 2: run fresh oia-audit (write to temp file so audit-trend can read it)
  const tmp = mkdtempSync(join(tmpdir(), 'drift-from-history-'));
  const currPath = join(tmp, 'current.json');
  try {
    // iter 58 — reuse auditResult from the parallel batch above instead
    // of re-running oia-audit. Saves the ~600ms-3s the second run took.
    if (!auditResult.json || auditResult.exitCode !== 0) {
      emitAndExit({
        error: `oia-audit failed (exit ${auditResult.exitCode})`,
        stderrTail: auditResult.stderr.slice(-200),
      }, 2);
    }
    if (auditResult.json.degraded === true) {
      emitAndExit({
        degraded: true,
        reason: auditResult.json.reason || 'metaharness-not-available',
      }, 3);
    }
    writeFileSync(currPath, JSON.stringify(auditResult.json));

    // Step 3: audit-trend
    // iter 67 — when --baseline-file was given, pass it through as
    // audit-trend's --baseline file input instead of --baseline-key.
    // Avoids the memory roundtrip on the trend leg too.
    const trendArgs = usedBaselineFile
      ? [
          '--baseline', ARGS.baselineFile,
          '--current', currPath,
          '--alert-on-distance-below', String(ARGS.threshold),
        ]
      : [
          '--baseline-key', baseline.key,
          '--current', currPath,
          '--alert-on-distance-below', String(ARGS.threshold),
        ];
    const trendResult = runScriptJson('audit-trend.mjs', trendArgs);
    if (!trendResult.json) {
      emitAndExit({
        error: `audit-trend produced no JSON (exit ${trendResult.exitCode})`,
        stderrTail: trendResult.stderr.slice(-200),
      }, 2);
    }
    const trend = trendResult.json;
    let alertTriggered = trendResult.exitCode === 1;
    const alertReasons = trend.alert?.reasons ? [...trend.alert.reasons] : [];

    // iter 78 — orthogonal finding-severity gate: any introduced
    // finding ≥ --alert-on-new-severity triggers regardless of
    // structural-distance threshold. Catches the "security regression
    // that didn't move the genome much" case.
    let elevatedFindings = [];
    if (ARGS.alertOnNewSeverity) {
      const threshold = rankSeverity(ARGS.alertOnNewSeverity);
      const introduced = trend?.delta?.findings?.introduced ?? [];
      elevatedFindings = introduced.filter((f) => rankSeverity(f.severity) >= threshold);
      if (elevatedFindings.length > 0) {
        alertTriggered = true;
        alertReasons.push(
          `${elevatedFindings.length} new finding(s) at or above ${ARGS.alertOnNewSeverity} severity`,
        );
      }
    }

    const payload = {
      adr: 'ADR-150 + ADR-152 §3.1',
      command: 'drift-from-history',
      // iter 65 — parallel batch metrics. parallelSpeedup>1 means
      // audit-list + oia-audit raced; ~1.0 means serial regression.
      timing: {
        parallelWallMs,
        parallelSumMs,
        parallelSpeedup: parallelSumMs > 0
          ? Math.round((parallelSumMs / Math.max(parallelWallMs, 1)) * 100) / 100
          : 0,
        // iter 66 — when true, audit-list was skipped via --baseline-key.
        // Fastpath drops wall-clock from ~26s to ~1s (avoids ONNX warmup).
        skippedAuditList,
        // iter 67 — when true, baseline came from a file instead of memory.
        // Skips audit-list AND the audit-trend memory roundtrip.
        usedBaselineFile,
        // iter 95 — derived path label for cleaner consumer code:
        //   'slow' — default (no fast-path arg); audit-list ran
        //   'key'  — --baseline-key skipped audit-list, baseline came from memory
        //   'file' — --baseline-file skipped audit-list AND memory roundtrip
        path: usedBaselineFile ? 'file' : (skippedAuditList ? 'key' : 'slow'),
      },
      baseline: {
        key: baseline.key,
        startedAt: baseline.startedAt ?? null,
      },
      current: {
        startedAt: auditResult.json.startedAt,
        composite: auditResult.json.composite,
      },
      drift: trend.delta,
      alert: {
        threshold: ARGS.threshold,
        // iter 78 — orthogonal gates surfaced: similarity threshold AND
        // new-finding-severity. Either can flip triggered=true.
        newSeverityThreshold: ARGS.alertOnNewSeverity,
        triggered: alertTriggered,
        reasons: alertReasons,
        // Keep .reason for backward-compat with consumers that read it as a string
        reason: alertReasons.length > 0
          ? alertReasons.join('; ')
          : (alertTriggered ? `similarity < ${ARGS.threshold}` : `similarity ≥ ${ARGS.threshold} — OK`),
        elevatedFindings,
      },
      generatedAt: new Date().toISOString(),
    };
    emitAndExit(payload, alertTriggered ? 1 : 0);
  } finally {
    try { rmSync(tmp, { recursive: true, force: true }); } catch { /* ignore */ }
  }
}

main().catch((e) => {
  console.error('drift-from-history crashed:', e.message || e);
  process.exit(2);
});

#!/usr/bin/env node
// evolve.mjs — wrapper around `metaharness-darwin evolve <repo>`.
//
// ADR-153: Darwin Mode is the WRITE layer that closes the loop ADR-150's
// READ layer (score / genome / mcp-scan / threat-model / oia-audit) opens.
// score+genome tell you where the harness IS; darwin evolve tells you which
// mutation makes it provably better, without retraining the foundation model.
//
// SAFETY (ADR-153 §"Safety model"):
//   - Variant generation + sandbox happen under <repo>/.metaharness/variants/,
//     never in the repo root. Upstream `inspectVariant()` rejects nested dirs,
//     symlinks, secret-shaped strings, shell-out / network / dynamic-eval
//     before any variant runs. Exit code 99 is reserved for "safety-disqualified".
//   - --confirm is REQUIRED. Without it the script prints a plan and exits 0
//     (mirrors mint.mjs convention). This is in addition to upstream's safety
//     layer — defense in depth at the ruflo boundary.
//   - Default --generations 3 --children 3 (small) — anything larger is opt-in.
//     Real evolutions are minutes-to-hours; ruflo's default sandbox config
//     errs toward "show me the mechanism works" over "find a winner today".
//
// USAGE
//   node scripts/evolve.mjs --repo .                                       # dry-run plan
//   node scripts/evolve.mjs --repo . --confirm                             # actually evolve
//   node scripts/evolve.mjs --repo . --confirm --generations 5 --children 3
//   node scripts/evolve.mjs --repo . --confirm --sandbox mock              # no real tests
//   node scripts/evolve.mjs --repo . --confirm --selection pareto
//   node scripts/evolve.mjs --repo . --confirm --diagnose                  # + GEPA failure diagnosis
//
// --diagnose (GEPA failure diagnosis — the natural-language-diagnosis trick
// from GEPA, scoped modestly): after the evolve run completes, the losing /
// failed variants' transcripts are run through darwin's gepa
// `analyzeTranscript` + `classifyFailure` ops and a `diagnosis` section
// (failure classes + counts + dominant class per variant) is appended to the
// emitted JSON report. UPSTREAM SHAPE NOTE (verified against darwin 0.8.0):
// `metaharness-darwin evolve --json` emits a TEXT leaderboard on stdout — no
// JSON, no transcripts. The per-variant run records live at
// `<repo>/.metaharness/runs/<id>.json` as sandbox exec traces
// ({taskId, exitCode, stdout, stderr}), which are NOT gepa {actionRaw, obs}
// transcripts. So the diagnosis layer (a) uses gepa-shaped transcripts when
// a run record embeds them (agent-sandbox / future upstream), (b) falls back
// to the champion's transcript, and (c) otherwise emits
// `diagnosis: {available: false, reason, traceSummary}` with a mechanical
// per-variant trace summary — it NEVER fails the run.
//
// EXIT CODES
//   0  evolved OK (or dry-run, or degraded — MetaHarness Darwin not available)
//   1  --alert-on-no-improvement and champion did not beat parent
//   2  config error or evolution failure
//   99 reserved — upstream "safety-disqualified" (propagated)

import { runDarwinAsync, emitDarwinDegradedJsonAndExit, importGepa } from './_darwin.mjs';
import { existsSync, readdirSync, readFileSync } from 'node:fs';
import { join, resolve } from 'node:path';

const ARGS = (() => {
  const a = {
    repo: '.',
    generations: 3,
    children: 3,
    concurrency: 2,
    seed: null,
    sandbox: 'real',
    selection: null,
    crossover: false,
    epistasis: false,
    curriculum: false,
    riskBudget: null,
    fdr: null,
    tie: null,
    bench: null,
    mutator: 'deterministic',
    ruvllmUrl: null,
    ruvllmModel: null,
    confirm: false,
    alertOnNoImprovement: false,
    diagnose: false,
    format: 'json',
    timeoutMs: null,  // computed below if unset
  };
  for (let i = 2; i < process.argv.length; i++) {
    const v = process.argv[i];
    if (v === '--repo') a.repo = process.argv[++i];
    else if (v === '--generations') a.generations = parseInt(process.argv[++i], 10);
    else if (v === '--children') a.children = parseInt(process.argv[++i], 10);
    else if (v === '--concurrency') a.concurrency = parseInt(process.argv[++i], 10);
    else if (v === '--seed') a.seed = parseInt(process.argv[++i], 10);
    else if (v === '--sandbox') a.sandbox = process.argv[++i];
    else if (v === '--selection') a.selection = process.argv[++i];
    else if (v === '--crossover') a.crossover = true;
    else if (v === '--epistasis') a.epistasis = true;
    else if (v === '--curriculum') a.curriculum = true;
    else if (v === '--risk-budget') a.riskBudget = parseInt(process.argv[++i], 10);
    else if (v === '--fdr') a.fdr = parseFloat(process.argv[++i]);
    else if (v === '--tie') a.tie = process.argv[++i];
    else if (v === '--bench') a.bench = process.argv[++i];
    else if (v === '--mutator') a.mutator = process.argv[++i];
    else if (v === '--ruvllm-url') a.ruvllmUrl = process.argv[++i];
    else if (v === '--ruvllm-model') a.ruvllmModel = process.argv[++i];
    else if (v === '--confirm') a.confirm = true;
    else if (v === '--alert-on-no-improvement') a.alertOnNoImprovement = true;
    else if (v === '--diagnose') a.diagnose = true;
    else if (v === '--format') a.format = process.argv[++i];
    else if (v === '--timeout-ms') a.timeoutMs = parseInt(process.argv[++i], 10);
  }
  return a;
})();

function safetyChecks() {
  const repoPath = resolve(ARGS.repo);
  if (!existsSync(repoPath)) {
    console.error(`evolve: repo path does not exist: ${repoPath}`);
    process.exit(2);
  }
  if (ARGS.generations < 1 || ARGS.generations > 50) {
    console.error('evolve: --generations must be 1..50 (ruflo cap; upstream supports more)');
    process.exit(2);
  }
  if (ARGS.children < 1 || ARGS.children > 20) {
    console.error('evolve: --children must be 1..20 (ruflo cap)');
    process.exit(2);
  }
  if (ARGS.concurrency < 1 || ARGS.concurrency > 8) {
    console.error('evolve: --concurrency must be 1..8 (ruflo cap)');
    process.exit(2);
  }
  if (!['real', 'mock', 'agent'].includes(ARGS.sandbox)) {
    console.error(`evolve: --sandbox must be real|mock|agent (got: ${ARGS.sandbox})`);
    process.exit(2);
  }
  if (ARGS.selection && !['quality-diversity', 'behavioral-diversity', 'niche-steering', 'clade', 'pareto'].includes(ARGS.selection)) {
    console.error(`evolve: --selection must be one of quality-diversity|behavioral-diversity|niche-steering|clade|pareto`);
    process.exit(2);
  }
  if (!['deterministic', 'ruvllm'].includes(ARGS.mutator)) {
    console.error(`evolve: --mutator must be deterministic|ruvllm`);
    process.exit(2);
  }
  return repoPath;
}

// ---------------------------------------------------------------------------
// --diagnose support (GEPA failure diagnosis)
// ---------------------------------------------------------------------------

/** True when `arr` looks like a gepa transcript: [{actionRaw?, obs?}, ...]. */
function looksLikeGepaTranscript(arr) {
  return Array.isArray(arr) && arr.length > 0 &&
    arr.every((e) => e && typeof e === 'object' && ('actionRaw' in e || 'obs' in e));
}

/**
 * Pull every gepa-shaped transcript out of one run record. Upstream darwin
 * 0.8.0 run records carry sandbox exec traces (NOT gepa transcripts), but a
 * record MAY embed `transcript` arrays (agent sandbox / future upstream) —
 * accept `record.transcript`, `record.traces[i].transcript`, or `traces`
 * itself when its entries are {actionRaw, obs}-shaped.
 */
function extractGepaTranscripts(record) {
  const out = [];
  if (looksLikeGepaTranscript(record?.transcript)) {
    out.push({ taskId: null, exitCode: null, entries: record.transcript });
  }
  const traces = Array.isArray(record?.traces) ? record.traces : [];
  if (looksLikeGepaTranscript(traces)) {
    out.push({ taskId: null, exitCode: null, entries: traces });
  } else {
    for (const t of traces) {
      if (looksLikeGepaTranscript(t?.transcript)) {
        out.push({ taskId: t.taskId ?? null, exitCode: t.exitCode ?? null, entries: t.transcript });
      }
    }
  }
  return out;
}

/** Mechanical per-variant summary of sandbox exec traces (the always-available fallback signal). */
function summarizeTraces(record) {
  const traces = Array.isArray(record?.traces) ? record.traces : [];
  return {
    tasks: traces.length,
    failed: traces.filter((t) => t?.exitCode !== 0).length,
    timedOut: traces.filter((t) => t?.timedOut === true).length,
    blockedActions: traces.reduce((n, t) => n + (Array.isArray(t?.blockedActions) ? t.blockedActions.length : 0), 0),
  };
}

/**
 * Build the `diagnosis` section for the emitted report. Never throws and
 * never affects the run's exit code — any internal failure degrades to
 * `{available: false, reason}`.
 */
async function buildDiagnosis(repoPath) {
  try {
    const metaDir = join(repoPath, '.metaharness');
    const runsDir = join(metaDir, 'runs');
    if (!existsSync(runsDir)) {
      return { available: false, reason: 'no-run-records: <repo>/.metaharness/runs does not exist' };
    }
    let winnerId = null;
    try {
      winnerId = JSON.parse(readFileSync(join(metaDir, 'reports', 'winner.json'), 'utf-8'))?.variant?.id ?? null;
    } catch { /* winner unknown — treat all variants as candidates */ }

    const records = [];
    for (const f of readdirSync(runsDir).filter((f) => f.endsWith('.json')).slice(0, 100)) {
      try {
        records.push({ id: f.replace(/\.json$/, ''), rec: JSON.parse(readFileSync(join(runsDir, f), 'utf-8')) });
      } catch { /* skip unreadable record */ }
    }
    if (records.length === 0) {
      return { available: false, reason: 'no-run-records: <repo>/.metaharness/runs contains no parseable records' };
    }

    // Losing/failed variants are the primary diagnosis targets; the champion
    // is the fallback when no loser exposes a transcript.
    const losers = records.filter((r) =>
      r.id !== winnerId &&
      (r.rec?.score?.promoted === false ||
       (Array.isArray(r.rec?.traces) && r.rec.traces.some((t) => t?.exitCode !== 0 || t?.timedOut))));
    const champion = records.filter((r) => r.id === winnerId);

    let scope = 'losing-variants';
    let pool = losers.map((r) => ({ ...r, transcripts: extractGepaTranscripts(r.rec) }))
      .filter((r) => r.transcripts.length > 0);
    if (pool.length === 0) {
      scope = 'champion-fallback';
      pool = champion.map((r) => ({ ...r, transcripts: extractGepaTranscripts(r.rec) }))
        .filter((r) => r.transcripts.length > 0);
    }

    if (pool.length === 0) {
      // Verified upstream shape (darwin 0.8.0): run records are sandbox exec
      // traces, not gepa transcripts. Emit the mechanical trace summary so
      // --diagnose still yields signal.
      const target = losers.length ? losers : records;
      return {
        available: false,
        reason: 'no-gepa-transcripts: run records contain sandbox exec traces ({taskId, exitCode, stdout, stderr}), not gepa {actionRaw, obs} transcripts',
        traceSummary: Object.fromEntries(target.map((r) => [r.id, summarizeTraces(r.rec)])),
      };
    }

    const gepa = await importGepa();
    if (!gepa || typeof gepa.analyzeTranscript !== 'function') {
      return { available: false, reason: 'metaharness-darwin-gepa-not-available' };
    }

    const classLabel = (n) => {
      const raw = gepa.FAILURE_CLASSES?.[n];
      return raw ? String(raw).split(' (')[0] : `class-${n}`;
    };

    const totals = {};
    const variants = [];
    for (const r of pool) {
      const classes = {};
      for (const t of r.transcripts) {
        const analysis = gepa.analyzeTranscript(t.entries);
        const cls = typeof gepa.classifyFailure === 'function'
          ? gepa.classifyFailure({ goldResolved: t.exitCode === 0, analysis })
          : -1;
        const label = classLabel(cls);
        classes[label] = (classes[label] || 0) + 1;
        totals[label] = (totals[label] || 0) + 1;
      }
      const dominantClass = Object.entries(classes).sort((a, b) => b[1] - a[1])[0]?.[0] ?? null;
      variants.push({ id: r.id, transcripts: r.transcripts.length, failureClasses: classes, dominantClass });
    }

    return { available: true, scope, variants, totals };
  } catch (e) {
    return { available: false, reason: `diagnosis-failed: ${e?.message ?? e}` };
  }
}

// Compute a sensible timeout from the search shape if caller didn't specify.
// Rough budget: each variant ~= 30s (sandbox test command + safety inspect),
// total ~= generations × children × per-variant / concurrency.
function defaultTimeoutMs() {
  const perVariantMs = ARGS.sandbox === 'mock' ? 2_000 : 60_000;
  const variants = ARGS.generations * ARGS.children;
  const parallelism = Math.min(ARGS.concurrency, variants);
  const wall = Math.ceil(variants / parallelism) * perVariantMs;
  // Add 30s overhead for npm install + initial profile + final report.
  return Math.max(60_000, wall + 30_000);
}

async function main() {
  const repoPath = safetyChecks();

  const plan = {
    binary: 'metaharness-darwin evolve',
    repo: repoPath,
    generations: ARGS.generations,
    children: ARGS.children,
    concurrency: ARGS.concurrency,
    sandbox: ARGS.sandbox,
    selection: ARGS.selection,
    crossover: ARGS.crossover,
    epistasis: ARGS.epistasis,
    curriculum: ARGS.curriculum,
    mutator: ARGS.mutator,
    diagnose: ARGS.diagnose,
    estVariants: ARGS.generations * ARGS.children,
    timeoutMs: ARGS.timeoutMs ?? defaultTimeoutMs(),
    output: `${repoPath}/.metaharness/{archive.json, lineage.json, variants/, runs/, reports/winner.json}`,
  };

  if (!ARGS.confirm) {
    const payload = {
      success: true,
      data: { plan, dryRun: true, message: 'Pass --confirm to run the evolution.' },
      generatedAt: new Date().toISOString(),
    };
    console.log(JSON.stringify(payload, null, 2));
    process.exit(0);
  }

  const cliArgs = ['evolve', repoPath,
    '--generations', String(ARGS.generations),
    '--children', String(ARGS.children),
    '--concurrency', String(ARGS.concurrency),
    '--sandbox', ARGS.sandbox,
    '--mutator', ARGS.mutator,
  ];
  if (ARGS.seed != null) cliArgs.push('--seed', String(ARGS.seed));
  if (ARGS.selection) cliArgs.push('--selection', ARGS.selection);
  if (ARGS.crossover) cliArgs.push('--crossover');
  if (ARGS.epistasis) cliArgs.push('--epistasis');
  if (ARGS.curriculum) cliArgs.push('--curriculum');
  if (ARGS.riskBudget != null) cliArgs.push('--risk-budget', String(ARGS.riskBudget));
  if (ARGS.fdr != null) cliArgs.push('--fdr', String(ARGS.fdr));
  if (ARGS.tie) cliArgs.push('--tie', ARGS.tie);
  if (ARGS.bench) cliArgs.push('--bench', ARGS.bench);
  if (ARGS.ruvllmUrl) cliArgs.push('--ruvllm-url', ARGS.ruvllmUrl);
  if (ARGS.ruvllmModel) cliArgs.push('--ruvllm-model', ARGS.ruvllmModel);

  // Forward progress lines to stderr so the user sees per-generation activity
  // (subprocess-of-an-MCP-tool case: this still surfaces in the agent log).
  const r = await runDarwinAsync(cliArgs, {
    timeoutMs: plan.timeoutMs,
    onProgress: (line) => { if (line.trim()) process.stderr.write(`[evolve] ${line}\n`); },
  });

  if (r.degraded) {
    emitDarwinDegradedJsonAndExit(r.reason);
    return;
  }

  // Upstream exit code 99 = safety-disqualified — propagate verbatim so
  // CI gates can distinguish "evolution failed" from "evolution surfaced
  // a safety-tripping mutation". This is a designed-in tripwire, not an
  // error the ruflo layer should remap.
  if (r.exitCode === 99) {
    const payload = {
      success: false,
      data: { safetyDisqualified: true, hint: 'A variant tripped the safety inspection layer. See <repo>/.metaharness/runs/ for which surface and pattern.' },
      stderrTail: r.stderr.slice(-400),
      durationMs: r.durationMs,
      generatedAt: new Date().toISOString(),
    };
    console.log(JSON.stringify(payload, null, 2));
    process.exit(99);
  }

  if (r.exitCode !== 0) {
    const payload = {
      success: false,
      data: { exitCode: r.exitCode, stderrTail: r.stderr.slice(-400) },
      generatedAt: new Date().toISOString(),
    };
    console.log(JSON.stringify(payload, null, 2));
    process.exit(2);
  }

  const champion = r.json || {};
  const noImprovement = champion.parentScore != null && champion.championScore != null &&
                        champion.championScore <= champion.parentScore;

  const payload = {
    success: true,
    data: {
      ...champion,
      plan,
      durationMs: r.durationMs,
      improved: !noImprovement,
    },
    generatedAt: new Date().toISOString(),
  };

  // GEPA failure diagnosis — opt-in, additive, never fails the run.
  if (ARGS.diagnose) {
    payload.data.diagnosis = await buildDiagnosis(repoPath);
  }

  console.log(JSON.stringify(payload, null, 2));
  if (ARGS.alertOnNoImprovement && noImprovement) process.exit(1);
  process.exit(0);
}

main().catch((e) => {
  console.error(`evolve: unexpected failure: ${e?.message ?? e}`);
  process.exit(2);
});

#!/usr/bin/env node
// genome.mjs — wrapper around `metaharness genome <path>`.
//
// Returns the 7-section readiness report: repo_type / agent_topology /
// risk_score / mcp_surface / test_confidence / publish_readiness +
// verdict (ready | needs-work | blocked). Reads-only.
//
// USAGE
//   node scripts/genome.mjs
//   node scripts/genome.mjs --path <dir> --alert-on-risk-above 0.5 --format json
//
// EXIT CODES
//   0  OK
//   1  --alert-on-risk-above threshold breached
//   2  config error or genome failure

import { runMetaharness, emitDegradedJsonAndExit } from './_harness.mjs';

const ARGS = (() => {
  const a = { path: '.', format: 'json', alertRiskAbove: null };
  for (let i = 2; i < process.argv.length; i++) {
    const v = process.argv[i];
    if (v === '--path') a.path = process.argv[++i];
    else if (v === '--alert-on-risk-above') a.alertRiskAbove = parseFloat(process.argv[++i]);
    else if (v === '--format') a.format = process.argv[++i];
  }
  return a;
})();

function main() {
  const r = runMetaharness(['genome', ARGS.path]);
  if (r.degraded) { emitDegradedJsonAndExit(r.reason); return; }
  if (r.exitCode !== 0 || !r.json) {
    console.error(`genome: metaharness exited ${r.exitCode}`);
    if (r.stderr) console.error(r.stderr.slice(0, 400));
    process.exit(2);
  }
  // iter 112 — generatedAt for consistency with other --format json outputs
  const payload = { ...r.json, path: ARGS.path, durationMs: r.durationMs,
    generatedAt: new Date().toISOString() };

  if (ARGS.alertRiskAbove !== null) {
    if (!isFinite(ARGS.alertRiskAbove)) {
      console.error(`genome: --alert-on-risk-above must be a finite number`);
      process.exit(2);
    }
    payload.alert = {
      threshold: ARGS.alertRiskAbove,
      triggered: typeof payload.risk_score === 'number' && payload.risk_score > ARGS.alertRiskAbove,
      reason: typeof payload.risk_score === 'number' && payload.risk_score > ARGS.alertRiskAbove
        ? `risk_score ${payload.risk_score} > ${ARGS.alertRiskAbove}`
        : `risk_score ${payload.risk_score ?? 'unknown'} ≤ ${ARGS.alertRiskAbove} — OK`,
    };
  }

  if (ARGS.format === 'json') {
    console.log(JSON.stringify(payload, null, 2));
  } else {
    console.log(`# harness-genome — ${ARGS.path}`);
    console.log('');
    console.log(`| Section | Value |`);
    console.log(`|---|---|`);
    console.log(`| repo_type | ${payload.repo_type ?? '—'} |`);
    console.log(`| agent_topology | ${(payload.agent_topology || []).join(', ') || '—'} |`);
    console.log(`| risk_score | ${payload.risk_score ?? '—'} |`);
    console.log(`| mcp_surface | ${payload.mcp_surface ?? '—'} |`);
    console.log(`| test_confidence | ${payload.test_confidence ?? '—'} |`);
    console.log(`| publish_readiness | ${payload.publish_readiness ?? '—'} |`);
    console.log(`| **duration** | ${payload.durationMs}ms |`);
    console.log('');
    if (payload.alert) {
      console.log(payload.alert.triggered ? `⚠ **ALERT**: ${payload.alert.reason}` : `✓ ${payload.alert.reason}`);
      console.log('');
    }
  }

  if (payload.alert?.triggered) process.exit(1);
}

main();

#!/usr/bin/env node
// gepa.mjs — surfaces the `@metaharness/darwin/gepa` LIBRARY exports.
//
// Unlike every other script in this plugin, gepa has no CLI equivalent —
// GEPA (darwin 0.8.0's genetic-evolution prompt-adaptation engine) ships as
// a library entry (`import { ... } from '@metaharness/darwin/gepa'`). This
// script wraps the subprocess-safe subset:
//
//   genome    load + validate a genome (default: the shipped cand-6 — the
//             first holdout-confirmed cheap-tier policy promotion)
//   validate  validateGenome(json) → structural errors[]
//   render    buildSystemFromGenome(genome) → the system prompt a genome
//             compiles to (inspect what a policy actually says)
//   analyze   analyzeTranscript(entries) → failure-class breakdown
//
// NOT SURFACED: `gepaOptimize` — it takes an in-process `evaluate(candidate)`
// callback ("bring your own evaluator") which cannot cross a subprocess
// boundary. Optimization runs belong either in library consumers
// (import '@metaharness/darwin/gepa' directly) or behind the darwin CLI's
// `evolve` verb (scripts/evolve.mjs), which pairs GEPA with its sandbox
// evaluators.
//
// MODULE RESOLUTION (ADR-150 graceful degradation)
// ================================================
// Delegated to _invoke.importOptionalLibrary (family-wide consolidation):
// 1. Try bare `import('@metaharness/darwin/gepa')` — free when the optional
//    dep is installed in an ancestor node_modules.
// 2. Fall back to a ruflo-owned versioned cache install
//    (~/.ruflo/darwin-cache-<pin>) — the versioned dir means pin bumps
//    invalidate stale caches automatically.
// 3. Both fail → `{degraded: true}` exit 0. Never throws.
//
// EXIT CODES
//   0  op completed (or degraded)
//   1  --alert-on-invalid and validate found errors
//   2  config error (bad op / missing file)

import { readFileSync, existsSync } from 'node:fs';
import { importGepa, DARWIN_VERSION_PIN } from './_darwin.mjs';

// Pin lives in _darwin.mjs (DARWIN_VERSION_PIN) — single source of truth.
const DARWIN_PIN_VERSION = DARWIN_VERSION_PIN.split('@').pop();

const ARGS = (() => {
  const a = {
    op: null,
    path: null,        // genome JSON path (genome/validate/render); default cand-6
    transcript: null,  // transcript JSON path (analyze)
    ext: undefined,    // render — target file extension hint
    glob: undefined,   // render — target glob hint
    alertOnInvalid: false,
    format: 'json',
  };
  for (let i = 2; i < process.argv.length; i++) {
    const v = process.argv[i];
    if (v === '--op') a.op = process.argv[++i];
    else if (v === '--path') a.path = process.argv[++i];
    else if (v === '--transcript') a.transcript = process.argv[++i];
    else if (v === '--ext') a.ext = process.argv[++i];
    else if (v === '--glob') a.glob = process.argv[++i];
    else if (v === '--alert-on-invalid') a.alertOnInvalid = true;
    else if (v === '--format') a.format = process.argv[++i];
  }
  return a;
})();

function emitDegradedAndExit(reason) {
  console.log(JSON.stringify({
    degraded: true,
    reason,
    hint: 'Install with `npm i -D @metaharness/darwin@' + DARWIN_PIN_VERSION
      + '` or verify network access — the gepa entry ships inside the darwin package.',
    generatedAt: new Date().toISOString(),
  }, null, 2));
  process.exit(0);  // ADR-150 — ruflo stays operational without MetaHarness
}

function readJsonFile(path, label) {
  if (!path || !existsSync(path)) {
    console.error(`gepa: ${label} file not found: ${path}`);
    process.exit(2);
  }
  try {
    return JSON.parse(readFileSync(path, 'utf8'));
  } catch (e) {
    console.error(`gepa: ${label} is not valid JSON: ${e?.message ?? e}`);
    process.exit(2);
  }
}

function loadGenomeOrExit(gepa) {
  if (ARGS.path) {
    if (!existsSync(ARGS.path)) {
      console.error(`gepa: --path genome file not found: ${ARGS.path}`);
      process.exit(2);
    }
    // upstream signature: loadGenome(readFileSync, path) — fs injected.
    return { genome: gepa.loadGenome(readFileSync, ARGS.path), source: ARGS.path };
  }
  return { genome: gepa.loadCand6Genome(), source: gepa.CAND6_GENOME_PATH };
}

async function main() {
  const OPS = ['genome', 'validate', 'render', 'analyze'];
  if (!OPS.includes(ARGS.op)) {
    console.error(`gepa: --op must be one of ${OPS.join('|')}`);
    process.exit(2);
  }

  const gepa = await importGepa();
  if (!gepa) emitDegradedAndExit('metaharness-darwin-not-available');

  const start = Date.now();
  let out;

  if (ARGS.op === 'genome') {
    const { genome, source } = loadGenomeOrExit(gepa);
    const errors = gepa.validateGenome(genome);
    out = { op: 'genome', source, valid: errors.length === 0, errors, genome };
  } else if (ARGS.op === 'validate') {
    // validate takes raw JSON (not loadGenome) so structurally-broken files
    // reach validateGenome instead of throwing in the loader.
    const raw = ARGS.path
      ? readJsonFile(ARGS.path, '--path genome')
      : gepa.loadCand6Genome();
    const errors = gepa.validateGenome(raw);
    out = { op: 'validate', source: ARGS.path ?? gepa.CAND6_GENOME_PATH, valid: errors.length === 0, errors };
  } else if (ARGS.op === 'render') {
    const { genome, source } = loadGenomeOrExit(gepa);
    const system = gepa.buildSystemFromGenome(genome, ARGS.ext, ARGS.glob);
    out = { op: 'render', source, chars: system.length, system };
  } else {
    // analyze
    const entries = readJsonFile(ARGS.transcript, '--transcript');
    if (!Array.isArray(entries)) {
      console.error('gepa: --transcript must be a JSON array of transcript entries');
      process.exit(2);
    }
    const analysis = gepa.analyzeTranscript(entries);
    out = { op: 'analyze', source: ARGS.transcript, entries: entries.length, analysis };
  }

  out.durationMs = Date.now() - start;
  console.log(JSON.stringify(out, null, 2));

  if (ARGS.alertOnInvalid && out.valid === false) process.exit(1);
  process.exit(0);
}

main().catch((e) => {
  console.error(`gepa: ${e?.message ?? e}`);
  process.exit(2);
});

#!/usr/bin/env node
// learn.mjs — wrapper around `metaharness learn` (upstream ADR-235, metaharness@0.3.0).
//
// GEPA learning run: optimizes a harness genome against a SWE-bench-style
// slice manifest. $0 DRY-RUN BY DEFAULT — upstream only spends (model calls,
// Docker sandboxes) when --run is passed, and we forward that flag verbatim
// so the spend opt-in stays explicit at every layer.
//
// CHECKOUT PRECONDITION (upstream design, not a bug)
// ==================================================
// The learning harness (GEPA + SWE-bench + Docker) is too heavy to ship in
// the npm package, so `metaharness learn` requires a local clone of the
// metaharness repo, located via $METAHARNESS_REPO or by running inside the
// clone. When the checkout is absent we emit a structured
// `{status: "checkout-required"}` payload and exit 0 — the script ran as
// designed and told the agent what to do next. This is distinct from
// `degraded: true` (npm package absent). The managed-service path (gateway-
// side learn jobs, no checkout) is upstream's ADR-235 follow-up.
//
// USAGE
//   node scripts/learn.mjs --host claude-code --model haiku --slice slices/lite.json
//   node scripts/learn.mjs --repo ~/src/metaharness --host codex --model gpt-5-mini --slice s.json --run
//
// EXIT CODES
//   0  learn completed (or dry-run report, or degraded, or checkout-required)
//   1  --alert-on-fail and the learn run reported failure
//   2  config error (bad arg)

import { existsSync } from 'node:fs';
import { runMetaharnessAsync, emitDegradedJsonAndExit } from './_harness.mjs';

const ARGS = (() => {
  const a = {
    host: null,
    model: null,
    slice: null,
    repo: null,
    run: false,
    alertOnFail: false,
    format: 'json',
    timeoutMs: null,
  };
  for (let i = 2; i < process.argv.length; i++) {
    const v = process.argv[i];
    if (v === '--host') a.host = process.argv[++i];
    else if (v === '--model') a.model = process.argv[++i];
    else if (v === '--slice') a.slice = process.argv[++i];
    else if (v === '--repo') a.repo = process.argv[++i];
    else if (v === '--run') a.run = true;
    else if (v === '--alert-on-fail') a.alertOnFail = true;
    else if (v === '--format') a.format = process.argv[++i];
    else if (v === '--timeout-ms') a.timeoutMs = parseInt(process.argv[++i], 10);
  }
  return a;
})();

const CHECKOUT_RX = /requires a metaharness repo checkout/i;

function defaultTimeoutMs() {
  // Dry-run resolves the slice manifest + prices the run without spending —
  // bounded by repo scan, not model calls. Real runs (--run) are dominated
  // by model calls × slice size; callers should pass --timeout-ms matched
  // to their slice. 10 min is a floor for small slices, not a budget.
  return ARGS.run ? 600_000 : 120_000;
}

async function main() {
  if (ARGS.repo && !existsSync(ARGS.repo)) {
    console.error(`learn: --repo path does not exist: ${ARGS.repo}`);
    process.exit(2);
  }

  const cliArgs = ['learn'];
  if (ARGS.host) cliArgs.push('--host', ARGS.host);
  if (ARGS.model) cliArgs.push('--model', ARGS.model);
  if (ARGS.slice) cliArgs.push('--slice', ARGS.slice);
  if (ARGS.run) cliArgs.push('--run');

  const r = await runMetaharnessAsync(cliArgs, {
    // learn emits a human-readable report; --json support is not guaranteed
    // across 0.3.x, so we don't inject it and parse leniently instead.
    json: false,
    timeoutMs: ARGS.timeoutMs ?? defaultTimeoutMs(),
    env: ARGS.repo ? { METAHARNESS_REPO: ARGS.repo } : {},
  });

  if (r.degraded) emitDegradedJsonAndExit(r.reason);

  const combined = `${r.stdout}\n${r.stderr}`;
  if (CHECKOUT_RX.test(combined)) {
    console.log(JSON.stringify({
      status: 'checkout-required',
      hint: 'git clone https://github.com/ruvnet/metaharness.git, then re-run with '
        + '--repo /path/to/metaharness (or set METAHARNESS_REPO). The learning '
        + 'harness (GEPA + SWE-bench + Docker) is not shipped in the npm package.',
      dryRun: !ARGS.run,
      durationMs: r.durationMs,
    }, null, 2));
    process.exit(0);
  }

  // Lenient JSON extraction — grab the last {...} block if one exists.
  let json = null;
  const matches = [...r.stdout.matchAll(/\{[\s\S]*?\}/g)];
  for (let i = matches.length - 1; i >= 0; i--) {
    try { json = JSON.parse(matches[i][0]); break; } catch { /* try previous */ }
  }

  const out = {
    status: r.exitCode === 0 ? 'ok' : 'failed',
    dryRun: !ARGS.run,
    exitCode: r.exitCode,
    report: json,
    // When upstream emits no JSON, the raw report is still the deliverable.
    rawReport: json ? undefined : r.stdout.slice(0, 20_000),
    durationMs: r.durationMs,
  };
  console.log(JSON.stringify(out, null, 2));

  if (ARGS.alertOnFail && r.exitCode !== 0) process.exit(1);
  process.exit(0);
}

main().catch((e) => {
  console.error(`learn: ${e?.message ?? e}`);
  process.exit(2);
});

#!/usr/bin/env node
// mcp-scan.mjs — wrapper around `harness mcp-scan <path>`.
//
// Static security scan of the harness's declared MCP surface. Reads
// .mcp/servers.json + .harness/claims.json. Pure-read, no dispatch.
//
// USAGE
//   node scripts/mcp-scan.mjs                           # current dir
//   node scripts/mcp-scan.mjs --path <dir>
//   node scripts/mcp-scan.mjs --fail-on high            # exit 1 if any HIGH finding (default)
//   node scripts/mcp-scan.mjs --fail-on medium          # also fail on MEDIUM
//   node scripts/mcp-scan.mjs --format json
//
// EXIT CODES
//   0  no findings at or above --fail-on (or degraded)
//   1  at least one finding ≥ --fail-on severity
//   2  config error or scan failure

// iter 50 — parseMcpScanText extracted to _harness.mjs so oia-audit
// can use the same parser without duplicating logic.
// iter 63 — SEVERITY_RANK also moves to _harness.mjs (single source of
// truth; previously this file had a literal that diverged from oia-audit's).
import { runHarness, emitDegradedJsonAndExit, parseMcpScanText, SEVERITY_RANK, rankSeverity } from './_harness.mjs';

const ARGS = (() => {
  const a = { path: '.', format: 'json', failOn: 'high' };
  for (let i = 2; i < process.argv.length; i++) {
    const v = process.argv[i];
    if (v === '--path') a.path = process.argv[++i];
    else if (v === '--fail-on') a.failOn = String(process.argv[++i] || 'high').toLowerCase();
    else if (v === '--format') a.format = process.argv[++i];
  }
  return a;
})();

function main() {
  if (!SEVERITY_RANK[ARGS.failOn]) {
    console.error(`mcp-scan: --fail-on must be one of low|medium|high; got ${ARGS.failOn}`);
    process.exit(2);
  }
  const r = runHarness(['mcp-scan', ARGS.path]);
  if (r.degraded) { emitDegradedJsonAndExit(r.reason); return; }
  if (r.exitCode !== 0 && r.exitCode !== 1) {
    // exit 1 from harness can be "findings present"; only treat other
    // non-zero as a real failure.
    console.error(`mcp-scan: harness exited ${r.exitCode}`);
    if (r.stderr) console.error(r.stderr.slice(0, 400));
    process.exit(2);
  }
  // The JSON output shape from `harness mcp-scan` historically didn't
  // include structured findings — it emits text even with --json. Parse
  // the text into findings (iter 50) so audit-trend's introduced/cleared
  // diff actually works. If a future upstream version DOES emit
  // findings[], the parsed-text findings are overridden.
  const parsed = parseMcpScanText(r.stdout);
  // iter 124 — normalize finding shape so consumers see a stable contract.
  // Upstream metaharness@0.1.x JSON path emits {id, severity, title, detail};
  // our parseMcpScanText emits {severity, message}. Project both into a
  // unified {severity, message, title?, detail?} so audit-trend's fingerprint
  // diff and test-mcp-tools' assertions don't care which path produced them.
  const rawFindings = Array.isArray(r.json?.findings) ? r.json.findings : parsed.findings;
  const findings = rawFindings.map((f) => ({
    ...f,
    message: typeof f.message === 'string' && f.message
      ? f.message
      : (f.title || f.detail || ''),
  }));
  const payload = {
    ...(r.json ?? {}),
    findings,
    summary: r.json?.summary ?? parsed.summary,
    rawStdout: r.stdout.slice(0, 400),
  };
  const threshold = SEVERITY_RANK[ARGS.failOn];
  // iter 63 — rankSeverity() safe lookup. Pre-iter-63 `undefined >= 3`
  // was false → unknown-severity findings (e.g., warn / error) were
  // silently excluded from the offending set, weakening --fail-on alerts.
  const offending = findings.filter((f) => rankSeverity(f.severity) >= threshold);

  const alert = {
    threshold: ARGS.failOn,
    triggered: offending.length > 0,
    offendingCount: offending.length,
    reason: offending.length > 0
      ? `${offending.length} finding(s) at or above ${ARGS.failOn} severity`
      : `no findings at or above ${ARGS.failOn} severity — OK`,
  };

  if (ARGS.format === 'json') {
    // iter 112 — generatedAt for consistency with other --format json outputs
    console.log(JSON.stringify({
      ...payload, durationMs: r.durationMs, alert,
      generatedAt: new Date().toISOString(),
    }, null, 2));
  } else {
    console.log(`# harness mcp-scan — ${ARGS.path}`);
    console.log('');
    console.log(`Total findings: ${findings.length}`);
    console.log(`| Severity | ID | Server | Tool | Message |`);
    console.log(`|---|---|---|---|---|`);
    for (const f of findings.slice(0, 50)) {
      console.log(`| ${f.severity} | ${f.id ?? '—'} | ${f.server ?? '—'} | ${f.tool ?? '—'} | ${f.message ?? ''} |`);
    }
    console.log('');
    console.log(alert.triggered ? `⚠ **ALERT**: ${alert.reason}` : `✓ ${alert.reason}`);
  }

  if (alert.triggered) process.exit(1);
}

main();

#!/usr/bin/env node
// mint.mjs — wrapper around `metaharness new <name> --template <id> --host <id>`.
//
// SAFETY (ADR-150 architectural constraint + "executing actions with care"):
//   - Target directory MUST be explicitly specified via --target. Defaults to
//     a temp dir under /tmp/ruflo-mint-<timestamp>/ if not given — never the
//     project root (ruflo behavioral rule "never save to root folder").
//   - --confirm flag required. Without it the script prints a dry-run plan
//     and exits 0 without writing files. This honors the "destructive-action
//     confirmation" pattern in ruflo's CLAUDE.md.
//
// USAGE
//   node scripts/mint.mjs --name my-harness --template vertical:coding --host claude-code
//     # → prints dry-run plan, exits 0
//   node scripts/mint.mjs --name my-harness --template vertical:coding --host claude-code --target /tmp/foo --confirm
//     # → actually scaffolds

import { runMetaharness, emitDegradedJsonAndExit } from './_harness.mjs';
import { existsSync, mkdirSync } from 'node:fs';
import { resolve, dirname, basename } from 'node:path';
import { tmpdir } from 'node:os';

const ARGS = (() => {
  const a = { name: null, template: null, host: 'claude-code', target: null, confirm: false, format: 'json' };
  for (let i = 2; i < process.argv.length; i++) {
    const v = process.argv[i];
    if (v === '--name') a.name = process.argv[++i];
    else if (v === '--template') a.template = process.argv[++i];
    else if (v === '--host') a.host = process.argv[++i];
    else if (v === '--target') a.target = process.argv[++i];
    else if (v === '--confirm') a.confirm = true;
    else if (v === '--format') a.format = process.argv[++i];
  }
  return a;
})();

function safetyChecks() {
  if (!ARGS.name) {
    console.error('mint: --name is required');
    process.exit(2);
  }
  if (!ARGS.template) {
    console.error('mint: --template is required (e.g. vertical:coding, minimal)');
    process.exit(2);
  }
  if (!ARGS.target) {
    ARGS.target = resolve(tmpdir(), `ruflo-mint-${Date.now()}-${ARGS.name}`);
  }
  const targetAbs = resolve(ARGS.target);
  const repoRoot = resolve(process.cwd());
  if (targetAbs === repoRoot) {
    console.error(`mint: refusing to write to project root (${repoRoot}). Specify a different --target.`);
    process.exit(2);
  }
  if (targetAbs.startsWith(repoRoot + '/')) {
    console.error(`mint: refusing to write inside the calling repo root. Use a --target outside ${repoRoot}.`);
    process.exit(2);
  }
}

function main() {
  safetyChecks();
  // ADR-150 architectural-constraint #3 (graceful degradation): even the
  // dry-run path must report degraded:true when metaharness is unreachable
  // — otherwise users with no network / proxy block see a happy-looking
  // plan and only hit the failure on --confirm. The no-metaharness-smoke
  // CI gate asserts every script emits a `"degraded"` field in this case.
  const probe = runMetaharness(['--version'], { json: false, timeoutMs: 15_000 });
  if (probe.degraded) { emitDegradedJsonAndExit(probe.reason); return; }
  const plan = {
    action: 'metaharness new',
    name: ARGS.name,
    template: ARGS.template,
    host: ARGS.host,
    target: ARGS.target,
    confirm: ARGS.confirm,
    willWrite: ARGS.confirm,
  };
  if (!ARGS.confirm) {
    if (ARGS.format === 'json') console.log(JSON.stringify({ ...plan, dryRun: true }, null, 2));
    else {
      console.log(`# harness-mint (dry-run)`);
      console.log('');
      for (const [k, v] of Object.entries(plan)) console.log(`- ${k}: ${v}`);
      console.log('');
      console.log('Re-run with `--confirm` to actually scaffold.');
    }
    process.exit(0);
  }
  if (existsSync(ARGS.target)) {
    console.error(`mint: target ${ARGS.target} already exists`);
    process.exit(2);
  }
  // ITER 27 FIX (forward-compatible) — at the time of writing,
  // metaharness@0.1.12 silently ignored the --target flag and wrote
  // to $CWD/<name> instead. Upstream issue #9
  // (ruvnet/agent-harness-generator) was filed + fixed in 0.1.13
  // within ~20 min — but this workaround is intentionally
  // forward-compatible: setting `cwd: dirname(target)` + passing
  // `basename(target)` as <name> produces the same correct landing
  // path on BOTH broken (0.1.12) and fixed (0.1.13+) upstream
  // versions. Keeping it as belt-and-braces against any future
  // regression. See `iter 29` for the verification log.
  const parentDir = dirname(ARGS.target);
  const cliName = basename(ARGS.target);
  mkdirSync(parentDir, { recursive: true });
  const r = runMetaharness(
    ['new', cliName, '--template', ARGS.template, '--host', ARGS.host],
    { json: false, cwd: parentDir, timeoutMs: 180_000 },
  );
  if (r.degraded) { emitDegradedJsonAndExit(r.reason); return; }
  if (r.exitCode !== 0) {
    console.error(`mint: metaharness exited ${r.exitCode}`);
    if (r.stderr) console.error(r.stderr.slice(0, 400));
    process.exit(2);
  }
  const result = { ...plan, exitCode: r.exitCode, durationMs: r.durationMs, ok: true };
  if (ARGS.format === 'json') console.log(JSON.stringify(result, null, 2));
  else {
    console.log(`# harness-mint — done`);
    console.log('');
    for (const [k, v] of Object.entries(result)) console.log(`- ${k}: ${v}`);
  }
}

main();

#!/usr/bin/env node
// oia-audit.mjs — composite Phase-2 worker (ADR-150).
//
// Bundles three MetaHarness static-analysis surfaces into one timestamped
// audit record:
//   - harness oia-manifest   (Open Infrastructure Architecture L1-L9 alignment)
//   - harness threat-model   (categorized MCP-surface threat report)
//   - harness mcp-scan       (per-server/tool policy + permissions + deps)
//
// The combined record is stored in the `metaharness-audit` memory
// namespace, keyed by ISO timestamp. Designed to be invoked on a cron
// schedule (e.g. weekly) so audit drift is visible over time.
//
// USAGE
//   node scripts/oia-audit.mjs                      # run + store
//   node scripts/oia-audit.mjs --path <dir>         # audit specific dir
//   node scripts/oia-audit.mjs --dry-run            # don't write to memory
//   node scripts/oia-audit.mjs --alert-on-worst high
//                                                  # exit 1 if threat-model worst >= high
//   node scripts/oia-audit.mjs --format json
//
// EXIT CODES
//   0  audit OK (or degraded)
//   1  --alert-on-worst threshold exceeded
//   2  config error or audit failure

import { spawnSync } from 'node:child_process';
// iter 63 — SEVERITY_RANK + rankSeverity consolidated to _harness.mjs
// (was local in iter 62; now shared with audit-trend + mcp-scan).
import { runHarness, runMetaharness, runHarnessAsync, runMetaharnessAsync, emitDegradedJsonAndExit, parseMcpScanText, SEVERITY_RANK, rankSeverity } from './_harness.mjs';

// iter 63 — SEVERITY_RANK + rankSeverity moved to _harness.mjs (single
// source of truth). The local copy from iter 62 is gone; the imports
// at the top of this file provide the same names.
const NS = process.env.OIA_AUDIT_NAMESPACE || 'metaharness-audit';
const CLI_PKG = process.env.CLI_CORE === '1'
  ? '@claude-flow/cli-core@alpha'
  : '@claude-flow/cli@latest';

const ARGS = (() => {
  const a = { path: '.', format: 'json', dryRun: false, alertWorst: null };
  for (let i = 2; i < process.argv.length; i++) {
    const v = process.argv[i];
    if (v === '--path') a.path = process.argv[++i];
    else if (v === '--dry-run') a.dryRun = true;
    else if (v === '--alert-on-worst') a.alertWorst = String(process.argv[++i] || '').toLowerCase();
    else if (v === '--format') a.format = process.argv[++i];
  }
  return a;
})();

// iter 47 — the `harness` and `metaharness` CLIs both have `score` /
// `genome` subcommands but with DIFFERENT output schemas. For the
// fingerprint to be consumable by _similarity.mjs (which expects the
// metaharness CLI shape: harnessFit/compileConfidence/agent_topology),
// we need to dispatch to runMetaharness for score+genome, not runHarness.
// iter 56 — annotated runOne result is identical for sync/async paths.
function annotateOne(r, label) {
  let json = r.json;
  if (label === 'mcp-scan' && !json && !r.degraded && r.stdout) {
    const parsed = parseMcpScanText(r.stdout);
    json = { findings: parsed.findings, summary: parsed.summary, rawStdout: r.stdout.slice(0, 400) };
  }
  return {
    label,
    exitCode: r.exitCode,
    degraded: r.degraded,
    reason: r.degraded ? r.reason : null,
    json,
    durationMs: r.durationMs,
    stderrTail: r.degraded ? (r.stderr || '').slice(-200) : null,
  };
}

function runOne(args, label, engine = 'harness') {
  const r = engine === 'metaharness' ? runMetaharness(args) : runHarness(args);
  return annotateOne(r, label);
}

// iter 56 — parallel variant. The composite audit's 5 subprocess calls
// are mutually independent (each scans the same path read-only), so
// they can run concurrently. Worst-case wall-clock drops from
// 5×DEFAULT_TIMEOUT_MS (sequential) to 1×DEFAULT_TIMEOUT_MS (parallel)
// — the iter-55-flagged gap (oia-audit timeout under unreachable
// registry) is closed by this.
async function runAllParallel(path) {
  const tasks = [
    runHarnessAsync(['oia-manifest', path]).then((r) => ['oiaManifest', annotateOne(r, 'oia-manifest')]),
    runHarnessAsync(['threat-model', path]).then((r) => ['threatModel', annotateOne(r, 'threat-model')]),
    runHarnessAsync(['mcp-scan', path]).then((r) => ['mcpScan', annotateOne(r, 'mcp-scan')]),
    runMetaharnessAsync(['score', path]).then((r) => ['score', annotateOne(r, 'score')]),
    runMetaharnessAsync(['genome', path]).then((r) => ['genome', annotateOne(r, 'genome')]),
  ];
  const results = await Promise.all(tasks);
  return Object.fromEntries(results);
}

function persist(payload) {
  const key = `audit-${new Date().toISOString().replace(/[:.]/g, '-')}`;
  const r = spawnSync('npx', [
    CLI_PKG, 'memory', 'store',
    '--namespace', NS,
    '--key', key,
    '--value', JSON.stringify(payload),
  ], { stdio: ['ignore', 'pipe', 'pipe'], encoding: 'utf-8', shell: process.platform === 'win32' });
  return {
    ok: r.status === 0,
    namespace: NS,
    key,
    error: r.status === 0 ? null : (r.stderr || '').slice(0, 200),
  };
}

async function main() {
  if (ARGS.alertWorst !== null && !SEVERITY_RANK.hasOwnProperty(ARGS.alertWorst)) {
    console.error(`oia-audit: --alert-on-worst must be one of clean|low|medium|high; got ${ARGS.alertWorst}`);
    process.exit(2);
  }

  const startedAt = new Date().toISOString();
  const wallStart = Date.now();
  // iter 56 — run the 5 sub-audits in parallel (was sequential pre-iter-56).
  // Worst-case wall-clock improves from 5×TIMEOUT to 1×TIMEOUT in the
  // unreachable-registry case; the happy path improves from sum-of-durations
  // to max-of-durations (typically ~2-4× faster).
  const all = await runAllParallel(ARGS.path);
  const wallMs = Date.now() - wallStart;
  const { oiaManifest: oia, threatModel: tm, mcpScan: mcp, score, genome } = all;

  // If all FIVE say "metaharness not available", surface the degraded
  // payload exactly once and exit 0 (architectural constraint #3).
  if (oia.degraded && tm.degraded && mcp.degraded && score.degraded && genome.degraded) {
    emitDegradedJsonAndExit('metaharness-not-available');
    return;
  }

  // Aggregate the worst-severity signal across mcp-scan + threat-model.
  // iter 62 — safe lookup using `?? 0` so unknown severities don't
  // silently bump composite via NaN-comparison (was: `acc | undefined`
  // → reduce never updated). Now any [WARN]/[CRITICAL]/[ERROR] finding
  // correctly elevates composite worst.
  const tmWorst = String(tm.json?.worst || 'clean').toLowerCase();
  const mcpFindings = Array.isArray(mcp.json?.findings) ? mcp.json.findings : [];
  // iter 63 — rankSeverity() from _harness.mjs handles unknown-severity
  // safely (returns 0 instead of undefined) so the reduce never sees NaN.
  const mcpWorst = mcpFindings.reduce((acc, f) => {
    const s = String(f.severity || 'low').toLowerCase();
    return rankSeverity(s) > rankSeverity(acc) ? s : acc;
  }, 'clean');
  const compositeWorst = rankSeverity(tmWorst) > rankSeverity(mcpWorst) ? tmWorst : mcpWorst;

  let alertTriggered = false;
  let alertReason = null;
  if (ARGS.alertWorst !== null) {
    const threshold = rankSeverity(ARGS.alertWorst);
    const compositeRank = rankSeverity(compositeWorst);
    if (compositeRank >= threshold && threshold > 0) {
      alertTriggered = true;
      alertReason = `composite worst=${compositeWorst} ≥ ${ARGS.alertWorst}`;
    }
  }

  // iter 59 — surface parallelization metrics. wallMs is the actual
  // time the 5 subprocess race took (max of components); the sum of
  // component.durationMs is what a SERIAL implementation would have
  // taken. A future smoke gate compares them to catch silent
  // serialization regression.
  const sumComponentMs = Object.values(all).reduce(
    (a, c) => a + (c?.durationMs ?? 0), 0);
  const payload = {
    path: ARGS.path,
    startedAt,
    finishedAt: new Date().toISOString(),
    timing: {
      wallMs,
      sumComponentMs,
      parallelSpeedup: sumComponentMs > 0
        ? Math.round((sumComponentMs / Math.max(wallMs, 1)) * 100) / 100 : 0,
    },
    composite: { worst: compositeWorst, threatModelWorst: tmWorst, mcpScanWorst: mcpWorst },
    components: { oiaManifest: oia, threatModel: tm, mcpScan: mcp, score, genome },
    // iter 38 — denormalized harness fingerprint for cheap similarity().
    // Mirrors the shape `_similarity.mjs::similarity()` expects so
    // audit-trend can call it without reshuffling components.
    fingerprint: {
      score: score?.json && !score.degraded ? score.json : null,
      genome: genome?.json && !genome.degraded ? genome.json : null,
    },
    alert: ARGS.alertWorst !== null ? {
      threshold: ARGS.alertWorst,
      triggered: alertTriggered,
      reason: alertReason || `composite worst=${compositeWorst} < ${ARGS.alertWorst} — OK`,
    } : null,
    persisted: null,
  };

  if (!ARGS.dryRun) {
    payload.persisted = persist(payload);
  }

  if (ARGS.format === 'json') {
    console.log(JSON.stringify(payload, null, 2));
  } else {
    console.log(`# oia-audit — ${ARGS.path}`);
    console.log('');
    console.log(`| Component | Exit | Degraded | Duration |`);
    console.log(`|---|---:|:---:|---:|`);
    console.log(`| oia-manifest | ${oia.exitCode} | ${oia.degraded ? '⚠' : '✓'} | ${oia.durationMs}ms |`);
    console.log(`| threat-model | ${tm.exitCode} | ${tm.degraded ? '⚠' : '✓'} | ${tm.durationMs}ms |`);
    console.log(`| mcp-scan | ${mcp.exitCode} | ${mcp.degraded ? '⚠' : '✓'} | ${mcp.durationMs}ms |`);
    console.log('');
    console.log(`Composite worst severity: **${compositeWorst}** (tm=${tmWorst}, mcp=${mcpWorst})`);
    if (payload.persisted) {
      console.log(`Persisted: ${payload.persisted.ok ? `${payload.persisted.namespace}:${payload.persisted.key}` : `FAILED: ${payload.persisted.error}`}`);
    }
    if (payload.alert) {
      console.log('');
      console.log(payload.alert.triggered ? `⚠ **ALERT**: ${payload.alert.reason}` : `✓ ${payload.alert.reason}`);
    }
  }

  if (alertTriggered) process.exit(1);
}

main().catch((e) => {
  console.error('oia-audit crashed:', e?.message ?? e);
  process.exit(2);
});

#!/usr/bin/env node
// redblue.mjs — wrapper around `@metaharness/redblue` for LLM red/blue testing.
//
// ADR-150 sibling-package integration: `@metaharness/redblue` runs an
// adversarial red-team → judge → blue-team patch loop against an LLM
// target you own. Upstream README: packages/redblue#readme on
// github.com/ruvnet/agent-harness-generator.
//
// SAFETY (enforced by upstream `src/config/safety.ts`, NOT this wrapper):
//   - no real credentials (`allow_real_credentials:true` = load-time error)
//   - no live external targets (validateTarget() rejects non-loopback)
//   - no shell, no arbitrary network, no eval
//   - sensitive outputs redacted before storage
//   - `max_cost_usd` / `max_runtime_minutes` / `max_tests` cap every run
//
// USAGE
//   node scripts/redblue.mjs init                         # write redblue.yaml
//   node scripts/redblue.mjs run --mock-judge --tests 10  # $0 marker-fixture path
//   node scripts/redblue.mjs run --tests 50 --patch       # real judge (needs OPENROUTER_API_KEY)
//   node scripts/redblue.mjs attack prompt --count 5      # preview attacks
//   node scripts/redblue.mjs patch --mock-judge           # baseline → patch → retest delta
//   node scripts/redblue.mjs report --in report.json      # render summary
//
// EXIT CODES
//   0  ran OK (or degraded — redblue not available)
//   1  --alert-on-fail and overall verdict was FAIL (after patch retest)
//   2  config / argv error
//
// REPORT FORMAT
//   `run` / `patch` write a JSON report to --out (default: ./redblue-report.json).
//   We re-emit it on stdout when --format json so MCP tools can parse it
//   without round-tripping through disk. Markdown rendering is delegated
//   to `redblue report` upstream.

import { runRedblue, emitRedblueDegradedJsonAndExit } from './_redblue.mjs';
import { existsSync, readFileSync, mkdtempSync, unlinkSync } from 'node:fs';
import { join, resolve } from 'node:path';
import { tmpdir } from 'node:os';

const VALID_SUBCOMMANDS = new Set(['init', 'run', 'patch', 'attack', 'report']);
const VALID_ATTACK_FAMILIES = new Set(['prompt', 'tools', 'data', 'all']);

const ARGS = (() => {
  const a = {
    sub: null,
    // shared
    config: null,
    out: null,
    inPath: null,
    format: 'json',
    // run/patch
    tests: null,
    patch: false,
    mockJudge: false,
    alertOnFail: false,
    // attack
    family: null,
    count: null,
    // budget overrides (forwarded only when set)
    maxCostUsd: null,
    maxRuntimeMinutes: null,
    timeoutMs: null,
  };
  const argv = process.argv.slice(2);
  if (argv.length === 0) return a;
  a.sub = argv[0];
  for (let i = 1; i < argv.length; i++) {
    const v = argv[i];
    if (v === '--config') a.config = argv[++i];
    else if (v === '--out') a.out = argv[++i];
    else if (v === '--in') a.inPath = argv[++i];
    else if (v === '--format') a.format = argv[++i];
    else if (v === '--tests') a.tests = parseInt(argv[++i], 10);
    else if (v === '--patch') a.patch = true;
    else if (v === '--mock-judge') a.mockJudge = true;
    else if (v === '--alert-on-fail') a.alertOnFail = true;
    else if (v === '--count') a.count = parseInt(argv[++i], 10);
    else if (v === '--max-cost-usd') a.maxCostUsd = parseFloat(argv[++i]);
    else if (v === '--max-runtime-minutes') a.maxRuntimeMinutes = parseFloat(argv[++i]);
    else if (v === '--timeout-ms') a.timeoutMs = parseInt(argv[++i], 10);
    else if (v === '--help' || v === '-h') a.sub = 'help';
    else if (!v.startsWith('-') && a.sub === 'attack' && !a.family) a.family = v;
    // any other unknown flag — pass through to upstream redblue
    else if (v.startsWith('--')) {
      // forward unknown flags verbatim so we don't bottleneck new redblue features
      a._passthrough = a._passthrough || [];
      a._passthrough.push(v);
      // peek for next-token value (only consume if it's not another flag)
      const next = argv[i + 1];
      if (next !== undefined && !next.startsWith('-')) {
        a._passthrough.push(next);
        i++;
      }
    }
  }
  return a;
})();

function printHelp() {
  console.log('npx ruflo metaharness redblue <subcommand> [options]');
  console.log('');
  console.log('Subcommands:');
  console.log('  init                       Write a sample redblue.yaml config');
  console.log('  run                        Run red-team → judge → (optional --patch → retest) → report');
  console.log('  patch                      Baseline → blue-team patch → retest delta');
  console.log('  attack <prompt|tools|data|all>   Preview generated attack test cases (no target call)');
  console.log('  report                     Render an existing report.json as markdown');
  console.log('');
  console.log('Common options:');
  console.log('  --config <path>            Config YAML (default: redblue.yaml in cwd)');
  console.log('  --out <path>               Output path for run/patch (default: ./redblue-report.json)');
  console.log('  --in <path>                Input report path (for `report` subcommand)');
  console.log('  --tests N                  How many test cases (run/patch)');
  console.log('  --patch                    After baseline run, apply blue-team patches and retest');
  console.log('  --mock-judge               $0 TEST-ONLY marker fixture — for CI / offline');
  console.log('  --alert-on-fail            Exit 1 when overall post-patch verdict is FAIL');
  console.log('  --format json|markdown     Output format (default: json)');
  console.log('  --max-cost-usd N           Override config max_cost_usd');
  console.log('  --max-runtime-minutes N    Override config max_runtime_minutes');
  console.log('  --timeout-ms N             Subprocess hard timeout (default: 120000)');
  console.log('');
  console.log('Examples:');
  console.log('  node scripts/redblue.mjs init');
  console.log('  node scripts/redblue.mjs run --mock-judge --tests 10');
  console.log('  node scripts/redblue.mjs run --tests 50 --patch  # needs OPENROUTER_API_KEY');
  console.log('  node scripts/redblue.mjs attack prompt --count 3');
  console.log('');
  console.log('SAFETY: upstream redblue enforces no-creds, no-live-targets, no-shell,');
  console.log('no-eval at load time (src/config/safety.ts). This wrapper does not relax');
  console.log('those — it only forwards argv with shell:false.');
}

function buildUpstreamArgs() {
  switch (ARGS.sub) {
    case 'init': {
      const out = ARGS.out ?? null;
      return ['init', ...(out ? ['--out', out] : [])];
    }
    case 'run': {
      const a = ['run'];
      if (ARGS.config) a.push('--config', ARGS.config);
      if (ARGS.tests !== null && Number.isFinite(ARGS.tests)) a.push('--tests', String(ARGS.tests));
      if (ARGS.patch) a.push('--patch');
      if (ARGS.mockJudge) a.push('--mock-judge');
      if (ARGS.out) a.push('--out', ARGS.out);
      return a;
    }
    case 'patch': {
      const a = ['patch'];
      if (ARGS.config) a.push('--config', ARGS.config);
      if (ARGS.mockJudge) a.push('--mock-judge');
      if (ARGS.out) a.push('--out', ARGS.out);
      return a;
    }
    case 'attack': {
      if (!ARGS.family || !VALID_ATTACK_FAMILIES.has(ARGS.family)) {
        console.error(`redblue: --attack family must be one of ${[...VALID_ATTACK_FAMILIES].join('|')} (got: ${ARGS.family ?? 'none'})`);
        process.exit(2);
      }
      const a = ['attack', ARGS.family];
      if (ARGS.count !== null && Number.isFinite(ARGS.count)) a.push('--count', String(ARGS.count));
      return a;
    }
    case 'report': {
      if (!ARGS.inPath) {
        console.error('redblue: report requires --in <path>');
        process.exit(2);
      }
      return ['report', '--in', ARGS.inPath];
    }
    default:
      console.error(`redblue: unknown subcommand "${ARGS.sub}". Valid: ${[...VALID_SUBCOMMANDS].join(', ')}`);
      process.exit(2);
  }
}

function main() {
  if (!ARGS.sub || ARGS.sub === 'help' || ARGS.sub === '--help' || ARGS.sub === '-h') {
    printHelp();
    process.exit(0);
  }
  if (!VALID_SUBCOMMANDS.has(ARGS.sub)) {
    console.error(`redblue: unknown subcommand "${ARGS.sub}". Valid: ${[...VALID_SUBCOMMANDS].join(', ')}`);
    process.exit(2);
  }

  // For `run` and `patch` we want the report JSON in our hands even when
  // the caller didn't pass --out (so MCP tools can read it back from stdout).
  let synthOut = null;
  if ((ARGS.sub === 'run' || ARGS.sub === 'patch') && !ARGS.out) {
    const dir = mkdtempSync(join(tmpdir(), 'ruflo-redblue-'));
    synthOut = join(dir, 'report.json');
    ARGS.out = synthOut;
  }

  const upstreamArgs = buildUpstreamArgs();
  if (ARGS._passthrough?.length) upstreamArgs.push(...ARGS._passthrough);

  const r = runRedblue(upstreamArgs, { timeoutMs: ARGS.timeoutMs ?? undefined });

  if (r.degraded) {
    if (synthOut && existsSync(synthOut)) {
      try { unlinkSync(synthOut); } catch { /* ignore */ }
    }
    emitRedblueDegradedJsonAndExit(r.reason);
    return;
  }

  // Pass through stderr (progress) when format=markdown so users see it live
  if (ARGS.format === 'markdown' && r.stderr) {
    process.stderr.write(r.stderr);
  }

  // For run/patch: read the report we asked redblue to write.
  let payload = null;
  if (ARGS.sub === 'run' || ARGS.sub === 'patch') {
    const reportPath = resolve(ARGS.out);
    if (existsSync(reportPath)) {
      try {
        payload = JSON.parse(readFileSync(reportPath, 'utf-8'));
      } catch (e) {
        console.error(`redblue: failed to parse report at ${reportPath}: ${e instanceof Error ? e.message : String(e)}`);
        if (synthOut) { try { unlinkSync(synthOut); } catch { /* ignore */ } }
        process.exit(2);
      }
    }
  }

  // Decorate every payload with our own metadata + the safety boundary
  // reminder so consumers always see "this was capability-contained".
  const enriched = payload && typeof payload === 'object' ? {
    ...payload,
    _ruflo: {
      subcommand: ARGS.sub,
      mockJudge: ARGS.mockJudge,
      durationMs: r.durationMs,
      safetyBoundary: 'enforced-by-upstream-redblue (no creds, no live targets, no shell, no eval)',
    },
  } : payload;

  // Determine overall verdict for --alert-on-fail (post-patch run only).
  // redblue reports include a `verdict` or `gate` field; we treat absence
  // as "no data → no alert" rather than erroring.
  let alertTriggered = false;
  if (ARGS.alertOnFail && enriched && typeof enriched === 'object') {
    const v = (enriched.verdict || enriched.gate || enriched.status || '').toString().toUpperCase();
    if (v.includes('FAIL')) alertTriggered = true;
  }

  if (ARGS.format === 'json') {
    if (enriched !== null) {
      console.log(JSON.stringify(enriched, null, 2));
    } else {
      // init / attack / report subcommands — forward upstream stdout verbatim
      // (it's already markdown/yaml). Wrap in a tiny JSON envelope.
      console.log(JSON.stringify({
        subcommand: ARGS.sub,
        ok: r.exitCode === 0,
        durationMs: r.durationMs,
        stdout: r.stdout,
        _ruflo: { safetyBoundary: 'enforced-by-upstream-redblue' },
      }, null, 2));
    }
  } else {
    // markdown / passthrough
    if (r.stdout) process.stdout.write(r.stdout);
    if (enriched && typeof enriched === 'object') {
      console.log('');
      console.log('---');
      console.log('## redblue report (parsed)');
      console.log('```json');
      console.log(JSON.stringify(enriched, null, 2));
      console.log('```');
    }
  }

  // Clean up synthetic temp file
  if (synthOut && existsSync(synthOut)) {
    try { unlinkSync(synthOut); } catch { /* ignore */ }
  }

  if (alertTriggered) process.exit(1);
  if (r.exitCode !== 0) process.exit(r.exitCode);
}

main();

#!/usr/bin/env node
// router-parallel-analyze.mjs — ADR-150 Phase 2 SelfEvolvingRouter
// promotion gate.
//
// Reads paired routing decisions (Thompson bandit pick + SelfEvolvingRouter
// pick, both with measured outcomes) from a JSONL trajectory file and
// computes the THREE PROMOTION CRITERIA from ADR-150 review-round-1:
//
//   (a) qualityScore improvement > 2%           (relative)
//   (b) usdPerDecision increase < 1%             (relative)
//   (c) p95 routing-decision latency increase < 5%  (relative)
//
// ALL THREE must hold for promotion. AND, not OR — the OR form let
// quality gains mask cost regressions, exactly the failure mode ADR-149's
// Pareto framing was built to prevent.
//
// INPUT FORMAT (.swarm/router-parallel.jsonl, one JSON record per line):
//   {
//     "ts": "<iso>",
//     "task": { ... },
//     "bandit":  { "pick": "<modelId>", "predictedQuality": 0.84, "predictedCostUsd": 0.003 },
//     "ser":     { "pick": "<modelId>", "predictedQuality": 0.87, "predictedCostUsd": 0.004 },
//     "outcome": { "actualModel": "<modelId>", "actualQuality": 0.91, "actualUsd": 0.0035, "actualLatencyMs": 1240 }
//   }
//
// USAGE
//   node scripts/router-parallel-analyze.mjs --input .swarm/router-parallel.jsonl
//   node scripts/router-parallel-analyze.mjs --input <file> --format json
//   node scripts/router-parallel-analyze.mjs --input <file> --strict   # exit 1 if NOT promotable
//
// EXIT CODES
//   0  analysis complete; in --strict mode → all three criteria passed
//   1  --strict requested AND at least one criterion failed (NOT promotable)
//   2  config error or input file missing/malformed

import { readFileSync, existsSync } from 'node:fs';

const ARGS = (() => {
  const a = { input: '.swarm/router-parallel.jsonl', format: 'table', strict: false };
  for (let i = 2; i < process.argv.length; i++) {
    const v = process.argv[i];
    if (v === '--input') a.input = process.argv[++i];
    else if (v === '--format') a.format = process.argv[++i];
    else if (v === '--strict') a.strict = true;
  }
  return a;
})();

function median(sorted) {
  if (sorted.length === 0) return 0;
  const n = sorted.length;
  return n % 2 === 0 ? (sorted[n / 2 - 1] + sorted[n / 2]) / 2 : sorted[(n - 1) / 2];
}

function pctile(sorted, q) {
  if (sorted.length === 0) return 0;
  const idx = Math.floor(q * (sorted.length - 1));
  return sorted[idx];
}

function mean(arr) {
  if (arr.length === 0) return 0;
  return arr.reduce((s, x) => s + x, 0) / arr.length;
}

function main() {
  if (!existsSync(ARGS.input)) {
    if (ARGS.format === 'json') {
      console.log(JSON.stringify({
        ok: true,
        sufficient: false,
        reason: 'input-file-not-found',
        input: ARGS.input,
        hint: 'Enable parallel logging (CLAUDE_FLOW_ROUTER_PARALLEL_LOG=1) and run a workload first.',
      }, null, 2));
    } else {
      console.log(`# router-parallel-analyze`);
      console.log('');
      console.log(`_Input file not found: ${ARGS.input}_`);
      console.log('');
      console.log('Enable parallel logging by setting `CLAUDE_FLOW_ROUTER_PARALLEL_LOG=1`');
      console.log('and running a real workload, then re-run this analyzer.');
    }
    process.exit(ARGS.strict ? 1 : 0);
  }

  let rows = [];
  try {
    rows = readFileSync(ARGS.input, 'utf-8')
      .split('\n')
      .filter((l) => l.trim())
      .map((l) => JSON.parse(l));
  } catch (e) {
    console.error(`router-parallel-analyze: cannot parse ${ARGS.input}: ${e.message}`);
    process.exit(2);
  }

  // Filter to records with both predictions + outcome present.
  const usable = rows.filter((r) => r.bandit && r.ser && r.outcome);

  if (usable.length < 30) {
    const payload = {
      ok: true,
      sufficient: false,
      reason: `n=${usable.length} < 30 (insufficient sample for AND-gate evaluation)`,
      hint: 'Continue collecting parallel-routing data; statistical significance needs ≥30 paired decisions per arm.',
      sampleSize: usable.length,
      generatedAt: new Date().toISOString(),
    };
    if (ARGS.format === 'json') console.log(JSON.stringify(payload, null, 2));
    else {
      console.log(`# router-parallel-analyze`);
      console.log('');
      console.log(`Sample size: **${usable.length}** paired decisions`);
      console.log('');
      console.log(`_Insufficient — need ≥30 for the 3-criteria AND-gate._`);
    }
    process.exit(ARGS.strict ? 1 : 0);
  }

  // For each record, attribute the outcome to BOTH arms when they
  // agreed on the model pick; when they disagreed, the actual outcome
  // belongs only to the bandit (which was the executing arm). The SER
  // arm gets its PREDICTED metrics for the counterfactual.
  const banditOutcomes = usable.map((r) => ({
    qualityActual: r.outcome.actualQuality,
    usdActual: r.outcome.actualUsd,
    latencyActual: r.outcome.actualLatencyMs,
  }));

  // SER counterfactual: use ser.predictedQuality / predictedCostUsd
  // when picks disagreed; use actual when they agreed. Latency: when
  // they agreed, both saw the same actual latency; when they
  // disagreed, the SER pick's latency is unknown — fall back to the
  // mean of agreed-decision latencies for that model.
  const agreedLatencyByModel = {};
  for (const r of usable) {
    if (r.bandit.pick === r.ser.pick) {
      const m = r.outcome.actualModel || r.bandit.pick;
      (agreedLatencyByModel[m] = agreedLatencyByModel[m] || []).push(r.outcome.actualLatencyMs);
    }
  }
  const modelMeanLatency = {};
  for (const [m, arr] of Object.entries(agreedLatencyByModel)) {
    modelMeanLatency[m] = mean(arr);
  }

  const serOutcomes = usable.map((r) => {
    const agreed = r.bandit.pick === r.ser.pick;
    return {
      qualityActual: agreed ? r.outcome.actualQuality : r.ser.predictedQuality,
      usdActual: agreed ? r.outcome.actualUsd : r.ser.predictedCostUsd,
      latencyActual: agreed
        ? r.outcome.actualLatencyMs
        : (modelMeanLatency[r.ser.pick] ?? r.outcome.actualLatencyMs),
    };
  });

  // Compute the three criteria.
  const banditQuality = mean(banditOutcomes.map((o) => o.qualityActual));
  const serQuality    = mean(serOutcomes.map((o) => o.qualityActual));
  const qualityImprovementPct =
    banditQuality > 0 ? ((serQuality - banditQuality) / banditQuality) * 100 : 0;

  const banditUsd = mean(banditOutcomes.map((o) => o.usdActual));
  const serUsd    = mean(serOutcomes.map((o) => o.usdActual));
  const usdIncreasePct = banditUsd > 0 ? ((serUsd - banditUsd) / banditUsd) * 100 : 0;

  const banditLatencyP95 = pctile(banditOutcomes.map((o) => o.latencyActual).sort((a, b) => a - b), 0.95);
  const serLatencyP95    = pctile(serOutcomes.map((o) => o.latencyActual).sort((a, b) => a - b), 0.95);
  const latencyIncreasePct =
    banditLatencyP95 > 0 ? ((serLatencyP95 - banditLatencyP95) / banditLatencyP95) * 100 : 0;

  const passes = {
    quality: qualityImprovementPct > 2,
    cost: usdIncreasePct < 1,
    latency: latencyIncreasePct < 5,
  };
  const allPass = passes.quality && passes.cost && passes.latency;

  // Disagreement rate (informational; not part of the gate).
  const disagreements = usable.filter((r) => r.bandit.pick !== r.ser.pick).length;
  const disagreementPct = (disagreements / usable.length) * 100;

  const payload = {
    ok: true,
    sufficient: true,
    sampleSize: usable.length,
    disagreement: {
      count: disagreements,
      pct: Math.round(disagreementPct * 100) / 100,
    },
    bandit: {
      meanQuality: Math.round(banditQuality * 10000) / 10000,
      meanUsd: Math.round(banditUsd * 1e6) / 1e6,
      p95LatencyMs: Math.round(banditLatencyP95),
    },
    ser: {
      meanQuality: Math.round(serQuality * 10000) / 10000,
      meanUsd: Math.round(serUsd * 1e6) / 1e6,
      p95LatencyMs: Math.round(serLatencyP95),
    },
    criteria: {
      qualityImprovementPct: Math.round(qualityImprovementPct * 100) / 100,
      qualityThresholdPct: 2,
      qualityPasses: passes.quality,
      usdIncreasePct: Math.round(usdIncreasePct * 100) / 100,
      usdThresholdPct: 1,
      costPasses: passes.cost,
      latencyIncreasePct: Math.round(latencyIncreasePct * 100) / 100,
      latencyThresholdPct: 5,
      latencyPasses: passes.latency,
    },
    verdict: {
      promotable: allPass,
      reason: allPass
        ? 'All three criteria met (quality > 2% AND cost < 1% AND latency < 5%)'
        : `Blocked by: ${[
            !passes.quality && `quality only +${(qualityImprovementPct).toFixed(2)}% (need >2%)`,
            !passes.cost && `cost +${(usdIncreasePct).toFixed(2)}% (need <1%)`,
            !passes.latency && `latency +${(latencyIncreasePct).toFixed(2)}% (need <5%)`,
          ].filter(Boolean).join(', ')}`,
    },
    generatedAt: new Date().toISOString(),
  };

  if (ARGS.format === 'json') {
    console.log(JSON.stringify(payload, null, 2));
  } else {
    console.log('# router-parallel-analyze (ADR-150 SelfEvolvingRouter promotion gate)');
    console.log('');
    console.log(`Sample size: **${payload.sampleSize}** paired decisions`);
    console.log(`Disagreement rate: ${payload.disagreement.pct}% (${payload.disagreement.count} / ${payload.sampleSize})`);
    console.log('');
    console.log(`| Metric | Bandit | SER | Delta | Threshold | Passes |`);
    console.log(`|---|---:|---:|---:|---:|:---:|`);
    console.log(`| Mean quality | ${payload.bandit.meanQuality} | ${payload.ser.meanQuality} | ${payload.criteria.qualityImprovementPct >= 0 ? '+' : ''}${payload.criteria.qualityImprovementPct}% | >+2% | ${passes.quality ? '✓' : '⚠'} |`);
    console.log(`| Mean $/decision | $${payload.bandit.meanUsd.toFixed(6)} | $${payload.ser.meanUsd.toFixed(6)} | ${payload.criteria.usdIncreasePct >= 0 ? '+' : ''}${payload.criteria.usdIncreasePct}% | <+1% | ${passes.cost ? '✓' : '⚠'} |`);
    console.log(`| p95 latency | ${payload.bandit.p95LatencyMs}ms | ${payload.ser.p95LatencyMs}ms | ${payload.criteria.latencyIncreasePct >= 0 ? '+' : ''}${payload.criteria.latencyIncreasePct}% | <+5% | ${passes.latency ? '✓' : '⚠'} |`);
    console.log('');
    console.log(`**Verdict**: ${allPass ? '✓ PROMOTABLE' : '⚠ NOT promotable'}`);
    console.log('');
    console.log(`_${payload.verdict.reason}_`);
  }

  if (ARGS.strict && !allPass) process.exit(1);
  process.exit(0);
}

main();

#!/usr/bin/env node
// score.mjs — `cost-style` wrapper around `metaharness score <path>`.
//
// Returns the 5-dimension scorecard (harnessFit / compileConfidence /
// taskCoverage / toolSafety / memoryUsefulness) + estCostPerRunUsd +
// scaffoldReady boolean. Reads-only; no side effects.
//
// USAGE
//   node scripts/score.mjs                          # current dir
//   node scripts/score.mjs --path <dir>             # specific dir
//   node scripts/score.mjs --alert-on-fit-below 70  # exit 1 if harnessFit < 70
//   node scripts/score.mjs --format json
//
// EXIT CODES
//   0  scored OK (or degraded — MetaHarness not available)
//   1  --alert-on-fit-below threshold breached
//   2  config error or scoring failure

import { runMetaharness, emitDegradedJsonAndExit } from './_harness.mjs';

const ARGS = (() => {
  const a = { path: '.', format: 'json', alertFitBelow: null };
  for (let i = 2; i < process.argv.length; i++) {
    const v = process.argv[i];
    if (v === '--path') a.path = process.argv[++i];
    else if (v === '--alert-on-fit-below') a.alertFitBelow = parseFloat(process.argv[++i]);
    else if (v === '--format') a.format = process.argv[++i];
  }
  return a;
})();

function main() {
  const r = runMetaharness(['score', ARGS.path]);
  if (r.degraded) {
    emitDegradedJsonAndExit(r.reason);
    return;
  }
  if (r.exitCode !== 0 || !r.json) {
    console.error(`score: metaharness exited ${r.exitCode}`);
    if (r.stderr) console.error(r.stderr.slice(0, 400));
    process.exit(2);
  }
  const payload = { ...r.json, durationMs: r.durationMs };

  if (ARGS.alertFitBelow !== null) {
    if (!isFinite(ARGS.alertFitBelow)) {
      console.error(`score: --alert-on-fit-below must be a finite number`);
      process.exit(2);
    }
    payload.alert = {
      threshold: ARGS.alertFitBelow,
      triggered: typeof payload.harnessFit === 'number' && payload.harnessFit < ARGS.alertFitBelow,
      reason: typeof payload.harnessFit === 'number' && payload.harnessFit < ARGS.alertFitBelow
        ? `harnessFit ${payload.harnessFit} < ${ARGS.alertFitBelow}`
        : `harnessFit ${payload.harnessFit ?? 'unknown'} ≥ ${ARGS.alertFitBelow} — OK`,
    };
  }

  if (ARGS.format === 'json') {
    console.log(JSON.stringify(payload, null, 2));
  } else {
    console.log(`# harness-score — ${payload.repo || ARGS.path}`);
    console.log('');
    console.log(`| Dimension | Value |`);
    console.log(`|---|---:|`);
    console.log(`| harnessFit | ${payload.harnessFit ?? '—'} |`);
    console.log(`| compileConfidence | ${payload.compileConfidence ?? '—'} |`);
    console.log(`| taskCoverage | ${payload.taskCoverage ?? '—'} |`);
    console.log(`| toolSafety | ${payload.toolSafety ?? '—'} |`);
    console.log(`| memoryUsefulness | ${payload.memoryUsefulness ?? '—'} |`);
    console.log(`| estCostPerRunUsd | $${payload.estCostPerRunUsd ?? '—'} |`);
    console.log(`| recommendedMode | ${payload.recommendedMode ?? '—'} |`);
    console.log(`| archetype | ${payload.archetype ?? '—'} |`);
    console.log(`| template | ${payload.template ?? '—'} |`);
    console.log(`| scaffoldReady | ${payload.scaffoldReady ?? '—'} |`);
    console.log(`| hardConstraints | ${payload.hardConstraints ?? '—'} |`);
    console.log(`| **duration** | ${payload.durationMs}ms |`);
    console.log('');
    if (payload.alert) {
      if (payload.alert.triggered) {
        console.log(`⚠ **ALERT**: ${payload.alert.reason}`);
      } else {
        console.log(`✓ ${payload.alert.reason}`);
      }
      console.log('');
    }
  }

  if (payload.alert?.triggered) process.exit(1);
}

main();

#!/usr/bin/env node
// security-bench.mjs — wrapper around `metaharness-darwin security bench`.
//
// "Darwin Shield" — upstream's own ADR-155 — evolves a champion harness
// on a 10-vuln/9-decoy corpus and measures it against four baselines
// (B0 static-only, B1 LLM single-pass, B2 fixed agent, B3 Darwin champion).
// The CHAMPION reaches TPR=1, FPR=0; the eight acceptance gates verify
// reproducibility, statistical significance, and unsafe-output=0.
//
// CONNECTION TO RUFLO ADR-155
// ===========================
// ruflo's ADR-155 (#2417) proposes a nightly self-learning security harness
// with three learning loops (per-dimension confidence weighting, severity
// calibration, auto-fix bid). The upstream Darwin Shield is the closest
// reference implementation — same shape, different scope (evolves a
// security-detection harness vs evaluates findings; both grade by realized
// TPR/FPR vs ground-truth corpus). Running `security bench` periodically
// gives us the empirical baseline that ruflo's Phase 2 loop A needs before
// training: if Darwin Shield converges on a known-good corpus, the loop A
// gradient signal is sound; if it doesn't, the corpus / sandbox is the
// gap, not the learning algorithm.
//
// USAGE
//   node scripts/security-bench.mjs                              # default population=2 cycles=1
//   node scripts/security-bench.mjs --population 4 --cycles 3    # deeper run
//   node scripts/security-bench.mjs --population 4 --cycles 3 --alert-on-fail
//
// EXIT CODES
//   0  bench passed all gates (or degraded — Darwin not available)
//   1  --alert-on-fail and any acceptance gate failed
//   2  config error or bench infrastructure failure

import { runDarwinAsync, emitDarwinDegradedJsonAndExit } from './_darwin.mjs';

const ARGS = (() => {
  const a = {
    population: 2,
    cycles: 1,
    seed: null,
    alertOnFail: false,
    format: 'json',
    timeoutMs: null,
  };
  for (let i = 2; i < process.argv.length; i++) {
    const v = process.argv[i];
    if (v === '--population') a.population = parseInt(process.argv[++i], 10);
    else if (v === '--cycles') a.cycles = parseInt(process.argv[++i], 10);
    else if (v === '--seed') a.seed = parseInt(process.argv[++i], 10);
    else if (v === '--alert-on-fail') a.alertOnFail = true;
    else if (v === '--format') a.format = process.argv[++i];
    else if (v === '--timeout-ms') a.timeoutMs = parseInt(process.argv[++i], 10);
  }
  return a;
})();

function safetyChecks() {
  if (ARGS.population < 1 || ARGS.population > 20) {
    console.error('security-bench: --population must be 1..20 (ruflo cap)');
    process.exit(2);
  }
  if (ARGS.cycles < 1 || ARGS.cycles > 100) {
    console.error('security-bench: --cycles must be 1..100 (ruflo cap)');
    process.exit(2);
  }
}

function defaultTimeoutMs() {
  // Bench corpus has 10 vulns + 9 decoys = 19 evaluations per cycle.
  // Each evaluation runs the candidate detector + scores patches.
  // Rough budget: ~3s per evaluation × population × cycles + 30s overhead.
  return Math.max(60_000, 3_000 * 19 * ARGS.population * ARGS.cycles + 30_000);
}

// Parse the markdown report that `security bench` emits. The header
// "Overall: ✅ PASS" or "❌ FAIL" is the rolled-up gate. We also extract
// each acceptance gate's pass/fail line.
function parseSecurityBenchMarkdown(stdout) {
  const overallMatch = /\*\*Overall:\s*([✅❌])\s*(PASS|FAIL)\*\*/i.exec(stdout);
  const overall = overallMatch ? { ok: overallMatch[2].toUpperCase() === 'PASS', icon: overallMatch[1] } : null;

  const gates = [];
  // Match lines like: "- ✅ **TPR improvement ≥ 25% vs fixed harness** — +150%"
  const gateRx = /^-\s+([✅❌])\s+\*\*(.+?)\*\*\s*[—-]\s*(.+)$/gm;
  let m;
  while ((m = gateRx.exec(stdout)) !== null) {
    gates.push({
      ok: m[1] === '✅',
      criterion: m[2].trim(),
      measured: m[3].trim(),
    });
  }

  // Extract the baselines-vs-champion table — useful for diff over time.
  const baselines = [];
  const tableRx = /^\|\s*B[0-3]\s+([^|]+?)\s*\|\s*([\d.]+)\s*\|\s*([\d.]+)\s*\|\s*([\d.]+)\s*\|\s*([\d.]+)\s*\|\s*([\d.]+)\s*\|\s*(\d+)\s*\|\s*(.+?)\s*\|/gm;
  while ((m = tableRx.exec(stdout)) !== null) {
    baselines.push({
      harness: m[1].trim(),
      fitness: parseFloat(m[2]),
      tpr: parseFloat(m[3]),
      fpr: parseFloat(m[4]),
      patchPass: parseFloat(m[5]),
      repro: parseFloat(m[6]),
      unsafe: parseInt(m[7], 10),
      cost: m[8].trim(),
    });
  }

  return { overall, gates, baselines };
}

async function main() {
  safetyChecks();

  const cliArgs = ['security', 'bench',
    '--population', String(ARGS.population),
    '--cycles', String(ARGS.cycles),
  ];
  if (ARGS.seed != null) cliArgs.push('--seed', String(ARGS.seed));

  const r = await runDarwinAsync(cliArgs, {
    timeoutMs: ARGS.timeoutMs ?? defaultTimeoutMs(),
    json: false, // bench output is markdown, not JSON
    onProgress: (line) => { if (line.trim()) process.stderr.write(`[security-bench] ${line}\n`); },
  });

  if (r.degraded) {
    emitDarwinDegradedJsonAndExit(r.reason);
    return;
  }

  if (r.exitCode !== 0 && r.exitCode !== 1) {
    // Exit 1 may be the bench's own "gates failed" signal; treat as data.
    // Anything else is infrastructure failure.
    const payload = {
      success: false,
      data: { exitCode: r.exitCode, stderrTail: r.stderr.slice(-400) },
      generatedAt: new Date().toISOString(),
    };
    console.log(JSON.stringify(payload, null, 2));
    process.exit(2);
  }

  const parsed = parseSecurityBenchMarkdown(r.stdout);
  const gatesPassed = parsed.gates.filter((g) => g.ok).length;
  const gatesFailed = parsed.gates.length - gatesPassed;

  const payload = {
    success: true,
    data: {
      overall: parsed.overall,
      gates: {
        total: parsed.gates.length,
        passed: gatesPassed,
        failed: gatesFailed,
        details: parsed.gates,
      },
      baselines: parsed.baselines,
      rawMarkdown: r.stdout,
      shape: { population: ARGS.population, cycles: ARGS.cycles, seed: ARGS.seed },
      durationMs: r.durationMs,
    },
    generatedAt: new Date().toISOString(),
  };

  console.log(JSON.stringify(payload, null, 2));
  if (ARGS.alertOnFail && parsed.overall && !parsed.overall.ok) process.exit(1);
  process.exit(0);
}

main().catch((e) => {
  console.error(`security-bench: unexpected failure: ${e?.message ?? e}`);
  process.exit(2);
});

#!/usr/bin/env node
// similarity.mjs — ADR-152 §3.1 CLI skill.
//
// Computes weighted similarity between two harness fingerprints (genome
// + score JSON). Production-grade companion to _spike-similarity.mjs.
//
// USAGE
//   node scripts/similarity.mjs --a a.json --b b.json
//   node scripts/similarity.mjs --a-key harness-X --b-key harness-Y         # memory lookup
//   node scripts/similarity.mjs --a a.json --b b.json --per-dimension       # breakdown
//   node scripts/similarity.mjs --a a.json --b b.json --format json
//   node scripts/similarity.mjs --a a.json --b b.json --alert-below 0.5     # exit 1 if low
//
// EXIT CODES
//   0  ok  (or overall ≥ alert-below threshold)
//   1  --alert-below AND overall < threshold
//   2  config / input error (missing args, file not found, malformed JSON)
//
// ADR-150 ARCHITECTURAL CONSTRAINTS PRESERVED
//   - Pure-TS function (`_similarity.mjs`), no `@metaharness/*` import
//   - No new dep; uses node:fs + node:child_process only for memory lookup
//   - Graceful degradation: missing keys / malformed JSON → exit 2 with
//     a structured `{ degraded: true, reason: ... }` payload on stdout
//   - CI-gate ready: smoke step 17y locks this contract

import { readFileSync, existsSync } from 'node:fs';
import { spawnSync } from 'node:child_process';
import { similarity } from './_similarity.mjs';

const NS = process.env.HARNESS_SIMILARITY_NAMESPACE || 'metaharness-audit';
const CLI_PKG = process.env.CLI_CORE === '1'
  ? '@claude-flow/cli-core@alpha'
  : '@claude-flow/cli@latest';

const ARGS = (() => {
  const a = {
    aFile: null, bFile: null,
    aKey: null, bKey: null,
    perDimension: false,
    format: 'table',
    alertBelow: null,
  };
  for (let i = 2; i < process.argv.length; i++) {
    const v = process.argv[i];
    if (v === '--a') a.aFile = process.argv[++i];
    else if (v === '--b') a.bFile = process.argv[++i];
    else if (v === '--a-key') a.aKey = process.argv[++i];
    else if (v === '--b-key') a.bKey = process.argv[++i];
    else if (v === '--per-dimension') a.perDimension = true;
    else if (v === '--format') a.format = process.argv[++i];
    else if (v === '--alert-below') a.alertBelow = Number(process.argv[++i]);
  }
  return a;
})();

function emitDegradedAndExit(reason, code = 2) {
  const payload = {
    degraded: true,
    reason,
    adr: 'ADR-152',
    skill: 'harness-similarity',
    generatedAt: new Date().toISOString(),
  };
  console.log(JSON.stringify(payload, null, 2));
  process.exit(code);
}

function memRetrieve(key) {
  const r = spawnSync('npx', [
    CLI_PKG, 'memory', 'retrieve',
    '--namespace', NS, '--key', key,
  ], { stdio: ['ignore', 'pipe', 'pipe'], encoding: 'utf-8', shell: process.platform === 'win32' });
  if (r.status !== 0) return null;
  const m = /\{[\s\S]*\}/.exec(r.stdout || '');
  if (!m) return null;
  try { return JSON.parse(m[0]); } catch { return null; }
}

function loadHarness(label, filePath, memKey) {
  if (filePath) {
    if (!existsSync(filePath)) emitDegradedAndExit(`${label}: file not found: ${filePath}`);
    try { return JSON.parse(readFileSync(filePath, 'utf-8')); }
    catch (e) { emitDegradedAndExit(`${label}: invalid JSON: ${e.message}`); }
  }
  if (memKey) {
    const rec = memRetrieve(memKey);
    if (!rec) emitDegradedAndExit(`${label}: key not found in namespace ${NS}: ${memKey}`);
    return rec;
  }
  emitDegradedAndExit(`${label}: --${label} or --${label}-key required`);
  return null; // unreachable; emitDegradedAndExit exits
}

function main() {
  if (!ARGS.aFile && !ARGS.aKey) emitDegradedAndExit('--a <file> or --a-key <memkey> required');
  if (!ARGS.bFile && !ARGS.bKey) emitDegradedAndExit('--b <file> or --b-key <memkey> required');

  const a = loadHarness('a', ARGS.aFile, ARGS.aKey);
  const b = loadHarness('b', ARGS.bFile, ARGS.bKey);

  const result = similarity(a, b, { perDimension: ARGS.perDimension });

  const payload = {
    adr: 'ADR-152',
    skill: 'harness-similarity',
    inputs: {
      a: ARGS.aFile ?? `mem:${ARGS.aKey}`,
      b: ARGS.bFile ?? `mem:${ARGS.bKey}`,
    },
    ...result,
    alert: ARGS.alertBelow != null ? {
      threshold: ARGS.alertBelow,
      triggered: result.overall < ARGS.alertBelow,
      reason: result.overall < ARGS.alertBelow
        ? `overall ${result.overall} < threshold ${ARGS.alertBelow}`
        : `overall ${result.overall} ≥ threshold ${ARGS.alertBelow}`,
    } : null,
    generatedAt: new Date().toISOString(),
  };

  if (ARGS.format === 'json') {
    console.log(JSON.stringify(payload, null, 2));
  } else {
    console.log(`# harness similarity (ADR-152)\n`);
    console.log(`Inputs:`);
    console.log(`  a: ${payload.inputs.a}`);
    console.log(`  b: ${payload.inputs.b}`);
    console.log('');
    console.log(`| Component   | Score  | Weight | Contribution |`);
    console.log(`|-------------|-------:|-------:|-------------:|`);
    const { weights, components } = payload;
    console.log(`| cosine      | ${components.cosine.toFixed(4)} | ${weights.cosine}    | ${(components.cosine * weights.cosine).toFixed(4)} |`);
    console.log(`| categorical | ${components.categorical.toFixed(4)} | ${weights.categorical}   | ${(components.categorical * weights.categorical).toFixed(4)} |`);
    console.log(`| jaccard     | ${components.jaccard.toFixed(4)} | ${weights.jaccard}   | ${(components.jaccard * weights.jaccard).toFixed(4)} |`);
    console.log('');
    console.log(`**Overall:** ${payload.overall.toFixed(4)}`);
    if (payload.alert) {
      console.log('');
      console.log(payload.alert.triggered ? `⚠ ALERT: ${payload.alert.reason}` : `✓ ${payload.alert.reason}`);
    }
    if (ARGS.perDimension && payload.perDimension) {
      console.log('');
      console.log('## Per-dimension breakdown');
      console.log('');
      console.log('| Dimension | a | b | contribution |');
      console.log('|---|---|---|---:|');
      for (const [k, v] of Object.entries(payload.perDimension)) {
        const av = Array.isArray(v.a) ? `[${v.a.join(',')}]` : String(v.a ?? '-');
        const bv = Array.isArray(v.b) ? `[${v.b.join(',')}]` : String(v.b ?? '-');
        console.log(`| ${k} | ${av} | ${bv} | ${Number(v.contribution).toFixed(4)} |`);
      }
    }
  }

  if (payload.alert?.triggered) process.exit(1);
}

main();

#!/usr/bin/env node
// test-graceful-degradation.mjs — runtime drill for ADR-150 architectural
// constraint rule #3 (graceful degradation).
//
// CI runs this via .github/workflows/no-metaharness-smoke.yml; this
// script lets developers reproduce the same drill locally for fast
// iteration (no GitHub Actions roundtrip).
//
// STRATEGY
// Point `npm_config_registry` at an unresolvable host, then invoke every
// metaharness-CLI-dependent skill. Each MUST:
//   (a) exit 0 — never propagate a failure code from a missing optional dep
//   (b) emit JSON containing `"degraded": true` somewhere in its output
//
// The 8 covered skills (all rely on `npx metaharness` / `npx -p
// metaharness harness`):
//   score / genome / mcp-scan / threat-model / oia-audit /
//   audit-list / audit-trend / mint
//
// (audit-list + audit-trend talk to `npx @claude-flow/cli memory ...`
//  rather than metaharness — they're tested separately for the
//  "no records in namespace" graceful path.)
//
// USAGE
//   node scripts/test-graceful-degradation.mjs                 # default
//   node scripts/test-graceful-degradation.mjs --keep-fixtures # for debugging
//
// EXIT CODES
//   0  all skills gracefully degraded
//   1  at least one skill failed the contract (exit != 0 or no degraded:true)
//   2  setup error

import { spawnSync } from 'node:child_process';
import { mkdtempSync, rmSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const SCRIPTS_DIR = dirname(fileURLToPath(import.meta.url));

// Since the versioned-cache consolidation (_invoke.mjs), a warm
// ~/.ruflo/<pkg>-cache-<pin> or a locally installed metaharness would satisfy
// resolution WITHOUT touching the (unreachable) registry — making this drill
// vacuous on developer machines. Point the cache base at an empty temp dir
// and disable local walk-up resolution so the install path (and therefore
// the degraded contract) is actually exercised.
const EMPTY_CACHE_BASE = mkdtempSync(join(tmpdir(), 'ruflo-degradation-drill-'));

const ARGS = (() => {
  const a = { keep: false };
  for (let i = 2; i < process.argv.length; i++) {
    if (process.argv[i] === '--keep-fixtures') a.keep = true;
  }
  return a;
})();

const UNREACHABLE_REGISTRY = 'https://no-such-registry-9c8c43.example.invalid/';

let passed = 0, failed = 0;
const failures = [];

function assert(cond, label) {
  console.log(`  ${cond ? '✓' : '✗'} ${label}`);
  if (cond) passed++;
  else { failures.push(label); failed++; }
}

function runWithUnreachableRegistry(scriptName, extraArgs) {
  const r = spawnSync('node', [join(SCRIPTS_DIR, scriptName), ...extraArgs], {
    env: {
      ...process.env,
      npm_config_registry: UNREACHABLE_REGISTRY,
      NPM_CONFIG_REGISTRY: UNREACHABLE_REGISTRY,
      RUFLO_METAHARNESS_CACHE_BASE: EMPTY_CACHE_BASE,
      RUFLO_METAHARNESS_SKIP_LOCAL: '1',
    },
    stdio: ['ignore', 'pipe', 'pipe'],
    encoding: 'utf-8',
    // 180s per subprocess — long enough for npx's DNS-retry + 60s
    // subprocess timeout inside _harness.mjs to elapse. Smaller
    // timeouts here truncate the subprocess BEFORE it reaches its
    // own degraded-payload emit, which made earlier iterations of
    // this drill report false negatives (exit 1 from harness kill,
    // not from the script).
    timeout: 180_000,
  });
  return {
    // r.status is null when the subprocess was killed by our timeout.
    // Distinguish that case explicitly so callers can see "drill
    // harness killed it" vs "script exited non-zero".
    exitCode: r.status,
    stdout: r.stdout || '',
    stderr: r.stderr || '',
    killedByTimeout: r.status === null,
  };
}

function main() {
  console.log('# test-graceful-degradation\n');
  console.log(`Registry: ${UNREACHABLE_REGISTRY}`);
  console.log('Each skill must exit 0 AND emit "degraded": true in JSON.\n');

  // The 5 skills that directly invoke metaharness/harness binaries.
  // (audit-list / audit-trend talk to claude-flow's memory layer, not
  // metaharness; they have their own empty-namespace graceful paths
  // tested separately. mint requires a --name argv to even start.)
  // iter 55 — extending this list discovered 3 latent gaps:
  //   - oia-audit can exceed 180s in the unreachable-registry case
  //     (composes 5 subprocesses, each retries DNS)
  //   - mint's degraded payload doesn't currently include the
  //     literal "degraded": true marker
  //   - drift-from-history exits 2 (config error: no history) rather
  //     than 3 (test-cannot-run) when there are no audit records yet
  // These are real bugs filed for follow-up; the workflow-level drill
  // (`.github/workflows/no-metaharness-smoke.yml`) covers them in a
  // fresh CI environment where DNS failure is faster, but they're
  // unreliable to assert locally. Keeping the local drill at the 5
  // skills it reliably tests until the underlying graceful-degradation
  // contracts are tightened.
  const skills = [
    { name: 'score',        args: ['--format', 'json'] },
    { name: 'genome',       args: ['--format', 'json'] },
    { name: 'mcp-scan',     args: ['--format', 'json'] },
    { name: 'threat-model', args: ['--format', 'json'] },
    { name: 'oia-audit',    args: ['--dry-run', '--format', 'json'] },
    // ADR-153 — darwin scripts (separate optional dep @metaharness/darwin).
    // evolve.mjs without --confirm short-circuits to a dry-run plan BEFORE
    // any subprocess call, so it's not exercising the degraded path. Pass
    // --confirm with --sandbox mock + minimal shape so we hit the subprocess
    // path quickly and verify the {degraded: true} emit on registry-unreachable.
    { name: 'evolve',       args: ['--repo', '.', '--confirm', '--sandbox', 'mock', '--generations', '1', '--children', '1', '--concurrency', '1', '--timeout-ms', '60000'] },
    { name: 'security-bench', args: ['--population', '1', '--cycles', '1', '--timeout-ms', '60000'] },
    { name: 'bench',          args: ['--op', 'verify', '--suite', '/dev/null'] },
  ];

  for (const s of skills) {
    console.log(`-- ${s.name} --`);
    const r = runWithUnreachableRegistry(`${s.name}.mjs`, s.args);
    if (process.env.DEBUG || r.killedByTimeout || r.exitCode !== 0) {
      // Surface the failure context: drill timeouts and unexpected exits
      // are both worth seeing, otherwise debugging is blind.
      console.log(`  stdout (last 400): ${r.stdout.slice(-400)}`);
      console.log(`  stderr (last 300): ${r.stderr.slice(-300)}`);
      if (r.killedByTimeout) console.log(`  (killed by drill 180s timeout)`);
    }
    const acceptable = s.acceptableExits ?? [0];
    assert(acceptable.includes(r.exitCode) || (acceptable.length === 1 && r.exitCode === 0),
      `${s.name} exit code in {${acceptable.join(',')}} (got ${r.killedByTimeout ? 'timeout' : r.exitCode})`);
    assert(/"degraded"\s*:\s*true/.test(r.stdout), `${s.name} emits "degraded": true`);
  }

  if (!ARGS.keep) {
    try { rmSync(EMPTY_CACHE_BASE, { recursive: true, force: true }); } catch { /* best-effort */ }
  }

  console.log(`\n${passed} passed, ${failed} failed`);
  if (failed > 0) {
    console.log('\nFailures:');
    for (const f of failures) console.log(`  - ${f}`);
    process.exit(1);
  }
  console.log('\n✓ All skills satisfy ADR-150 rule #3 (graceful degradation).');
}

main();

#!/usr/bin/env node
// test-mcp-tools.mjs — runtime test for the iter-20/21 MCP tool registry.
//
// tsc proves the metaharness-tools.ts module COMPILES; structural smoke
// proves the source DECLARES the right tool names. Neither proves the
// HANDLERS actually run without throwing. This test imports the compiled
// module and invokes every tool's handler with minimal inputs.
//
// CONTRACT EACH TOOL MUST SATISFY
//   - handler is callable as `await tool.handler({ ... })`
//   - returns an object with keys: success, data, degraded, exitCode
//   - never throws (even with bad/missing optional dep — graceful)
//   - handler honors the 120s subprocess timeout (no hang)
//
// USAGE
//   node scripts/test-mcp-tools.mjs                          # default
//   node scripts/test-mcp-tools.mjs --format json
//
// EXIT CODES
//   0  all tools satisfy the contract
//   1  at least one tool failed
//   2  setup error (compiled dist not present)

import { existsSync } from 'node:fs';
import { dirname, join, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';

const SCRIPTS_DIR = dirname(fileURLToPath(import.meta.url));
const ARGS = (() => {
  const a = { format: 'table' };
  for (let i = 2; i < process.argv.length; i++) {
    if (process.argv[i] === '--format') a.format = process.argv[++i];
  }
  return a;
})();

let passed = 0, failed = 0;
const failures = [];

function assert(cond, label) {
  if (cond) { console.log(`  ✓ ${label}`); passed++; }
  else { console.log(`  ✗ ${label}`); failures.push(label); failed++; }
}

async function main() {
  // Locate the compiled dist of metaharness-tools.
  const distPath = resolve(SCRIPTS_DIR, '..', '..', '..',
    'v3', '@claude-flow', 'cli', 'dist', 'src', 'mcp-tools', 'metaharness-tools.js');

  if (!existsSync(distPath)) {
    console.log(`# test-mcp-tools — SKIPPED`);
    console.log('');
    console.log(`Compiled dist not present: ${distPath}`);
    console.log(`Build the CLI first:`);
    console.log(`  cd v3/@claude-flow/cli && npm run build`);
    console.log('');
    console.log(`Exit 0 — this script is meaningfully runnable only post-build.`);
    process.exit(0);
  }

  let mod;
  try {
    mod = await import(distPath);
  } catch (e) {
    console.error(`test-mcp-tools: failed to import ${distPath}: ${e.message}`);
    process.exit(2);
  }

  const tools = mod.metaharnessTools;
  console.log(`# test-mcp-tools — runtime contract\n`);

  // ──────────────────────────────────────────────────────────────────
  // PHASE 1 — module exports the right shape
  // ──────────────────────────────────────────────────────────────────
  console.log('Phase 1 — module shape');
  assert(Array.isArray(tools), 'metaharnessTools is an array');
  assert(tools.length === 15, `15 tools registered (got ${tools.length})`);

  const expectedNames = new Set([
    'metaharness_score',
    'metaharness_genome',
    'metaharness_mcp_scan',
    'metaharness_threat_model',
    'metaharness_oia_audit',
    'metaharness_audit_list',
    'metaharness_audit_trend',
    // iter 36 — ADR-152 §3.1 production
    'metaharness_similarity',
    // iter 54 — one-command drift detection (composes audit-list + oia-audit + audit-trend)
    'metaharness_drift_from_history',
    // ADR-153 — bench suites + evolve driver + security-focused bench
    'metaharness_bench',
    'metaharness_evolve',
    'metaharness_security_bench',
    // @metaharness/redblue@~0.1.4 — adversarial red/blue LLM testing
    'metaharness_redblue',
    // metaharness@0.3.0 — upstream ADR-235 GEPA learning run
    'metaharness_learn',
    // @metaharness/darwin@0.8.0 — GEPA library surface (genome ops)
    'metaharness_gepa',
  ]);
  const actualNames = new Set(tools.map((t) => t.name));
  for (const name of expectedNames) {
    assert(actualNames.has(name), `${name} registered`);
  }

  // ──────────────────────────────────────────────────────────────────
  // PHASE 2 — every tool has the required MCP shape
  // ──────────────────────────────────────────────────────────────────
  console.log('\nPhase 2 — per-tool shape');
  for (const tool of tools) {
    const ok = typeof tool.name === 'string'
      && typeof tool.description === 'string'
      && typeof tool.category === 'string'
      && typeof tool.handler === 'function'
      && typeof tool.inputSchema === 'object';
    assert(ok, `${tool.name} has {name, description, category, handler, inputSchema}`);
    assert(tool.category === 'metaharness', `${tool.name} category === 'metaharness'`);
  }

  // ──────────────────────────────────────────────────────────────────
  // PHASE 3 — handlers callable + return contract shape
  //
  // We invoke each handler with minimal valid input. The handlers may
  // succeed (if metaharness is installed) or report degraded (if not).
  // EITHER way, they must return { success, data, degraded, exitCode }
  // without throwing.
  // ──────────────────────────────────────────────────────────────────
  console.log('\nPhase 3 — handler invocations (allow up to 30s each)');
  for (const tool of tools) {
    // Construct minimal valid input per tool.
    let input = {};
    if (tool.name === 'metaharness_audit_trend') {
      // Requires baselineKey + currentKey — use fake keys that won't
      // resolve so we exercise the not-found path.
      input = { baselineKey: 'audit-fake-base', currentKey: 'audit-fake-curr' };
    }
    if (tool.name === 'metaharness_similarity') {
      // Needs --a/--b OR --a-key/--b-key. Use fake mem keys to exercise
      // the graceful not-found path (matches audit_trend convention).
      input = { aKey: 'harness-fake-a', bKey: 'harness-fake-b' };
    }
    if (tool.name === 'metaharness_drift_from_history') {
      // iter 54 — composes 3 subprocesses, needs more time than the default.
      input = { dryRun: true, threshold: 0.5 };
    }
    if (tool.name === 'metaharness_oia_audit') {
      // iter 128 — composite audit runs 5 sub-audits (oia-manifest +
      // threat-model + mcp-scan + score + genome) in parallel. Each
      // shells out via npx. --dry-run skips memory persistence so the
      // test doesn't pollute namespaces.
      input = { dryRun: true };
    }
    if (tool.name === 'metaharness_redblue') {
      // `attack` preview is the fastest path that exercises the upstream
      // binary without needing OPENROUTER_API_KEY or running any model
      // calls. Count=1 keeps cold-cache npx fetch the dominant cost.
      input = { subcommand: 'attack', family: 'prompt', count: 1 };
    }
    if (tool.name === 'metaharness_learn') {
      // No repo checkout in CI → structured {status:"checkout-required"}
      // exit-0 path. $0: without run=true upstream never spends anyway.
      input = {};
    }
    if (tool.name === 'metaharness_gepa') {
      // op is required; `genome` loads + validates the SHIPPED cand-6
      // genome — pure-local library call once darwin is cached.
      input = { op: 'genome' };
    }

    // iter 124 → 130 — timeouts have crept up as CI cold-cache npx
    // warmup costs got measured. Final budgets:
    //   default          : 60s
    //   chain-tools      : 180s  (drift_from_history + oia_audit + audit_list)
    // iter 131 — bumped chain-tool budget 90s → 180s. audit_list still
    // timed out at 90s in CI; locally it runs in ~4s, but CI's
    // `npx @claude-flow/cli@latest memory list` invocation pays both
    // the npx fetch AND a full CLI startup (which loads agentic-flow +
    // ONNX). 180s gives 30x headroom over the local cost.
    const isChainTool = tool.name === 'metaharness_drift_from_history'
      || tool.name === 'metaharness_oia_audit'
      || tool.name === 'metaharness_audit_list'
      // redblue: `attack prompt --count 1` is preview-only (no model
      // calls) but the cold-cache `npx -y @metaharness/redblue@~0.1.4`
      // fetch can take 30-60s. 180s gives 3x headroom.
      || tool.name === 'metaharness_redblue'
      // learn: cold-cache `npx -y metaharness@latest` fetch dominates.
      // gepa: one-time `npm install --prefix ~/.ruflo/darwin-cache-*`
      // fallback install can take 30-60s on cold cache.
      || tool.name === 'metaharness_learn'
      || tool.name === 'metaharness_gepa';
    const timeoutMs = isChainTool ? 180_000 : 60_000;
    const handlerPromise = tool.handler(input);
    const timeoutPromise = new Promise((_, reject) =>
      setTimeout(() => reject(new Error(`${timeoutMs / 1000}s handler timeout`)), timeoutMs));

    let result;
    let threw = false;
    try {
      result = await Promise.race([handlerPromise, timeoutPromise]);
    } catch (e) {
      threw = true;
      console.log(`    [${tool.name}] handler threw: ${e.message.slice(0, 80)}`);
    }

    assert(!threw, `${tool.name} handler did not throw`);
    if (!threw && result) {
      assert(typeof result === 'object', `${tool.name} returns object`);
      assert('success' in result, `${tool.name} result has 'success'`);
      assert('data' in result, `${tool.name} result has 'data'`);
      assert('degraded' in result, `${tool.name} result has 'degraded'`);
      assert('exitCode' in result, `${tool.name} result has 'exitCode'`);
    }
  }

  // ──────────────────────────────────────────────────────────────────
  // PHASE 4 — POSITIVE-CASE data-shape validation (iter 43)
  //
  // Iter 37 verified the {success, data, degraded, exitCode} envelope.
  // It did NOT verify that data.X contains the right keys when success
  // is genuinely true — leaving room for iter 42-style bugs where a
  // handler returns valid-looking degraded JSON while silently
  // misrouting input. This phase invokes each handler with VALID
  // inputs and asserts the expected output shape.
  //
  // Tools that depend on `npx metaharness` (score/genome/mcp-scan/
  // threat-model/oia-audit/audit-list/audit-trend) are SKIPPED in this
  // phase when the optional dep isn't installed — they're covered by
  // the no-metaharness-smoke workflow's drill. The similarity tool
  // has no @metaharness/* dep, so its positive case ALWAYS runs.
  // ──────────────────────────────────────────────────────────────────
  console.log('\nPhase 4 — positive-case data shape (iter 43)');

  const { writeFileSync, mkdtempSync } = await import('node:fs');
  const { tmpdir } = await import('node:os');
  const { join: pjoin } = await import('node:path');
  const tmp = mkdtempSync(pjoin(tmpdir(), 'mcp-positive-'));

  // metaharness_similarity — full positive case (no @metaharness/* needed)
  const simTool = tools.find((t) => t.name === 'metaharness_similarity');
  if (simTool) {
    const aPath = pjoin(tmp, 'a.json');
    const bPath = pjoin(tmp, 'b.json');
    writeFileSync(aPath, JSON.stringify({
      score: { harnessFit: 78, compileConfidence: 92, taskCoverage: 65, toolSafety: 88, memoryUsefulness: 70, estCostPerRunUsd: 0.04, recommendedMode: 'CLI + MCP', archetype: 'compliance-harness', template: 'vertical:legal' },
      genome: { repo_type: 'node_mcp_ci', agent_topology: ['x','y','z','w'], risk_score: 0.45, test_confidence: 0.7, publish_readiness: 0.6 },
    }));
    writeFileSync(bPath, JSON.stringify({
      score: { harnessFit: 75, compileConfidence: 90, taskCoverage: 70, toolSafety: 90, memoryUsefulness: 72, estCostPerRunUsd: 0.05, recommendedMode: 'CLI + MCP', archetype: 'compliance-harness', template: 'vertical:support' },
      genome: { repo_type: 'node_mcp_ci', agent_topology: ['x','y','z','q','r'], risk_score: 0.40, test_confidence: 0.75, publish_readiness: 0.65 },
    }));
    const r = await simTool.handler({ aFile: aPath, bFile: bPath });
    assert(r.degraded === false, 'similarity positive case: degraded === false');
    assert(r.success === true, 'similarity positive case: success === true');
    assert(r.exitCode === 0, 'similarity positive case: exitCode === 0');
    const d = r.data ?? {};
    assert(typeof d.overall === 'number', 'similarity data has numeric `overall`');
    assert(typeof d.components === 'object' && d.components !== null,
      'similarity data has `components` object');
    assert(typeof d.components?.cosine === 'number',
      'similarity components.cosine numeric');
    assert(typeof d.components?.categorical === 'number',
      'similarity components.categorical numeric');
    assert(typeof d.components?.jaccard === 'number',
      'similarity components.jaccard numeric');
    assert(typeof d.weights === 'object' && d.weights !== null,
      'similarity data has `weights` object');
    assert(d.adr === 'ADR-152', 'similarity data tagged adr=ADR-152');
    // Regression anchor — same fixtures as iter-35 spike with non-matching topologies
    assert(d.overall > 0 && d.overall < 1,
      `similarity overall in (0, 1) — got ${d.overall}`);

    // Per-dimension variant
    const rPD = await simTool.handler({ aFile: aPath, bFile: bPath, perDimension: true });
    assert(typeof rPD.data?.perDimension === 'object',
      'similarity perDimension=true populates breakdown');

    // Alert-below variant exercises non-zero exit
    const rAlert = await simTool.handler({ aFile: aPath, bFile: bPath, alertBelow: 0.99 });
    assert(rAlert.data?.alert?.triggered === true,
      'similarity alertBelow=0.99 triggers alert');
    assert(rAlert.exitCode === 1, 'similarity alertBelow=0.99 → exitCode 1');
    // iter 44 — success semantic anchor (was true under the pre-iter-44
    // `!degraded` rule; now false because exitCode !== 0 dominates).
    assert(rAlert.success === false,
      'similarity alertBelow=0.99 → success === false (iter 44 fix)');
  }

  // metaharness_mcp_scan — positive case post iter-50 parser landing.
  // Until iter 50, mcp_scan's data field was an alert-only object with
  // no structured findings. After iter 50, findings[] is always present
  // (parsed from upstream text) and summary{overallSeverity, totalCount}
  // accompanies it.
  const scanTool = tools.find((t) => t.name === 'metaharness_mcp_scan');
  if (scanTool) {
    // Run against ruflo itself — guaranteed to produce at least the
    // INFO finding the iter-50 parser test verified manually.
    const r = await scanTool.handler({ path: '.', failOn: 'high' });
    // Either succeeds with structured findings, or gracefully degrades
    // if metaharness isn't installed in this environment.
    if (!r.degraded) {
      assert(r.success === true, 'mcp_scan positive: success === true');
      assert(r.exitCode === 0, 'mcp_scan positive: exitCode === 0');
      assert(Array.isArray(r.data?.findings),
        'mcp_scan positive: data.findings is an array (iter 50 fix)');
      // Cwd-dependent: when scanning a dir without .mcp/servers.json the
      // upstream emits no findings. Only verify shape contract when array
      // is populated — the array-presence assertion above is the
      // load-bearing one for iter 50.
      if (r.data?.findings.length > 0) {
        const first = r.data.findings[0];
        assert(typeof first?.severity === 'string',
          'mcp_scan positive: first finding has string severity');
        assert(typeof first?.message === 'string',
          'mcp_scan positive: first finding has string message');
      }
      // summary may be null if the upstream produced no Result: line —
      // verify the field's presence (null OR object) but only deep-check
      // when populated.
      if (r.data?.summary) {
        assert(typeof r.data.summary.totalCount === 'number',
          'mcp_scan positive: data.summary.totalCount is numeric (when summary present)');
      }
    } else {
      console.log(`    ⊘ mcp_scan: metaharness absent — graceful skip`);
    }
  }

  // metaharness_audit_trend — positive case via file inputs
  const trendTool = tools.find((t) => t.name === 'metaharness_audit_trend');
  if (trendTool) {
    const basePath = pjoin(tmp, 'base.json');
    const currPath = pjoin(tmp, 'curr.json');
    const fingerprint = {
      score: { harnessFit: 80, recommendedMode: 'CLI + MCP', archetype: 'typescript-sdk-harness', template: 'vertical:coding' },
      genome: { repo_type: 'node_mcp_ci', agent_topology: ['a','b','c'], risk_score: 0.3, test_confidence: 0.85, publish_readiness: 0.9 },
    };
    writeFileSync(basePath, JSON.stringify({
      startedAt: '2026-06-15T00:00:00Z',
      composite: { worst: 'clean' },
      components: { oiaManifest: {}, threatModel: {}, mcpScan: { json: { findings: [] } } },
      fingerprint,
    }));
    writeFileSync(currPath, JSON.stringify({
      startedAt: '2026-06-16T00:00:00Z',
      composite: { worst: 'clean' },
      components: { oiaManifest: {}, threatModel: {}, mcpScan: { json: { findings: [] } } },
      fingerprint,
    }));
    // audit_trend tool only supports keys, not files at the MCP layer.
    // Document its actual wrapper semantics so future-us doesn't get
    // surprised:
    //   - bad keys → script exits 2 with stderr (no JSON payload)
    //   - runScript() can't parse a {degraded:true} marker, so it
    //     returns degraded:false / success:true / exitCode:2
    // This is a real wrapper bug (success should not be true when
    // exit!=0 AND no JSON came back), tracked separately. Asserting
    // current behavior here protects against silent semantic shifts.
    // iter 46 — file-input path. audit_trend now accepts baselineFile/currentFile.
    const rFiles = await trendTool.handler({ baselineFile: basePath, currentFile: currPath });
    assert(rFiles.success === true,
      'audit_trend file-input path: success === true (iter 46)');
    assert(rFiles.exitCode === 0, 'audit_trend file-input path: exitCode === 0');
    assert(typeof rFiles.data?.delta === 'object',
      'audit_trend file-input path: data.delta object present');
    assert(rFiles.data?.delta?.structuralDistance?.verdict === 'near-identical',
      `audit_trend file-input path: identical fingerprints → near-identical (got ${rFiles.data?.delta?.structuralDistance?.verdict})`);

    // iter 54 — metaharness_drift_from_history positive case
    const driftTool = tools.find((t) => t.name === 'metaharness_drift_from_history');
    if (driftTool) {
      // iter 71 — verify iter-66/67 fast-path flags are now MCP-callable
      // Synthesize a baseline file on disk; pass via the new baselineFile input.
      const baselinePath = pjoin(tmp, 'drift-baseline.json');
      writeFileSync(baselinePath, JSON.stringify({
        startedAt: '2026-06-16T00:00:00Z',
        composite: { worst: 'clean' },
        components: { oiaManifest: {}, threatModel: {}, mcpScan: { json: { findings: [] } } },
        fingerprint: {
          score: { harnessFit: 82, recommendedMode: 'CLI + MCP', archetype: 'typescript-sdk-harness', template: 'vertical:coding' },
          genome: { repo_type: 'node_mcp_ci', agent_topology: ['m', 't'], risk_score: 0.3 },
        },
      }));
      const rFastFast = await driftTool.handler({
        path: '.', dryRun: true, threshold: 0.5, baselineFile: baselinePath,
      });
      if (!rFastFast.degraded) {
        assert(rFastFast.data?.timing?.usedBaselineFile === true,
          'drift_from_history MCP-layer: baselineFile fastpath fires (iter 71)');
        assert(rFastFast.data?.timing?.skippedAuditList === true,
          'drift_from_history MCP-layer: skippedAuditList=true via baselineFile (iter 71)');
      }

      // iter 85 — verify iter-78's alertOnNewSeverity MCP input plumbs
      // through. baselineFile has no findings; current ruflo audit has
      // 1 INFO finding. With alertOnNewSeverity='info' the gate fires
      // and surfaces in the response.
      const baselineNoFindings = pjoin(tmp, 'drift-baseline-no-findings.json');
      writeFileSync(baselineNoFindings, JSON.stringify({
        startedAt: '2026-06-16T00:00:00Z',
        composite: { worst: 'clean' },
        components: { oiaManifest: {}, threatModel: {}, mcpScan: { json: { findings: [] } } },
        fingerprint: {
          score: { harnessFit: 82, recommendedMode: 'CLI + MCP', archetype: 'typescript-sdk-harness', template: 'vertical:coding' },
          genome: { repo_type: 'node_mcp_ci', agent_topology: ['m', 't'], risk_score: 0.3 },
        },
      }));
      const rSevAlert = await driftTool.handler({
        path: '.', dryRun: true, threshold: 0.5,
        baselineFile: baselineNoFindings,
        alertOnNewSeverity: 'info',
      });
      if (!rSevAlert.degraded) {
        assert(rSevAlert.data?.alert?.newSeverityThreshold === 'info',
          'drift_from_history MCP-layer: alertOnNewSeverity echoed in payload (iter 85)');
        // Triggered AND exit code reflects (only if the audit actually had findings)
        if (rSevAlert.data?.alert?.triggered === true) {
          assert(rSevAlert.exitCode === 1,
            `drift_from_history MCP-layer: alertOnNewSeverity exitCode=1 when triggered (got ${rSevAlert.exitCode})`);
          assert(rSevAlert.success === false,
            'drift_from_history MCP-layer: success===false when alert fires (iter 44 fix)');
        }
      }

      const r54 = await driftTool.handler({ path: '.', dryRun: true, threshold: 0.5 });
      if (!r54.degraded) {
        assert(typeof r54.data === 'object' && r54.data !== null,
          'drift_from_history positive: data is an object');
        // Either it produced the structured drift report OR the no-history error
        const isOk = r54.data?.command === 'drift-from-history';
        const isNoHistory = typeof r54.data?.error === 'string' && r54.data.error.includes('no audit records');
        assert(isOk || isNoHistory,
          `drift_from_history positive: structured report OR no-history error (got ${JSON.stringify(r54.data).slice(0,80)})`);
        if (isOk) {
          assert(typeof r54.data.baseline?.key === 'string',
            'drift_from_history: baseline.key is a string');
          assert(typeof r54.data.alert?.threshold === 'number',
            'drift_from_history: alert.threshold echoed numerically');
        }
      } else {
        console.log(`    ⊘ drift_from_history: degraded (metaharness or memory absent)`);
      }
    }

    const r = await trendTool.handler({ baselineKey: 'missing-X', currentKey: 'missing-Y' });
    assert(r.exitCode === 2,
      'audit_trend bad-keys path exits 2 (script-level guard fires)');
    assert(r.data === null || r.data === undefined,
      'audit_trend bad-keys path: data null (no JSON emitted on stderr exit)');
    // iter 44 — success semantic anchor. Pre-iter-44 wrapper returned
    // success:true for this case (because no degraded marker). Now
    // returns false because exitCode !== 0.
    assert(r.success === false,
      'audit_trend bad-keys path: success === false (iter 44 fix)');
  }

  // Cleanup
  try { (await import('node:fs')).rmSync(tmp, { recursive: true, force: true }); } catch { /* ignore */ }

  console.log(`\n${passed} passed, ${failed} failed`);
  if (failed > 0) {
    console.log('\nFailures:');
    for (const f of failures) console.log(`  - ${f}`);
    process.exit(1);
  }
  console.log('\n✓ All 15 MCP tools satisfy the runtime contract.');
}

main().catch((e) => {
  console.error('test-mcp-tools crashed:', e.message || e);
  process.exit(2);
});

#!/usr/bin/env node
// test-parallel-pipeline — end-to-end integration test for ADR-150's
// SelfEvolvingRouter parallel-logging pipeline.
//
// Composition under test:
//   recordPair() / recordPairOutcome() [iter 11 — TS module]
//     → .swarm/router-parallel.jsonl  [JSONL trajectory]
//       → router-parallel-analyze.mjs [iter 10 — analyzer]
//         → 3-criteria AND-gate verdict [ADR-150 review-round-1]
//
// This script bypasses model-router.ts dispatch and calls the recorder
// directly, so it tests the recorder + analyzer composition WITHOUT
// requiring a built CLI dist. Iter-12 dispatch wiring is covered by
// the smoke step 17f source-grep.
//
// USAGE
//   node scripts/test-parallel-pipeline.mjs                # default
//   TEST_PIPELINE_KEEP_FIXTURE=1 node scripts/test-parallel-pipeline.mjs
//                                                          # leave temp files for debugging
//
// EXIT CODES
//   0  all assertions passed
//   1  at least one assertion failed
//   2  setup error (e.g. tsc dist not buildable, recorder module missing)

import { spawnSync } from 'node:child_process';
import { mkdtempSync, rmSync, mkdirSync, existsSync, readFileSync, writeFileSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join, dirname } from 'node:path';
import { fileURLToPath } from 'node:url';

const SCRIPTS_DIR = dirname(fileURLToPath(import.meta.url));

let passed = 0, failed = 0;
const failures = [];

function assert(cond, label) {
  if (cond) {
    console.log(`  ✓ ${label}`);
    passed++;
  } else {
    console.log(`  ✗ ${label}`);
    failures.push(label);
    failed++;
  }
}

async function main() {
  const fixture = mkdtempSync(join(tmpdir(), 'router-parallel-e2e-'));
  const jsonlPath = join(fixture, 'router-parallel.jsonl');
  console.log(`# router-parallel pipeline e2e (fixture: ${fixture})\n`);

  // ──────────────────────────────────────────────────────────────────
  // PHASE 1 — Synthesize a realistic JSONL trajectory by hand.
  //
  // We can't easily import the TS recorder without a build step, so we
  // emit the same JSONL shape the recorder produces. This isolates the
  // analyzer pipeline test from compile state.
  // ──────────────────────────────────────────────────────────────────
  console.log('Phase 1 — synthesize trajectory');

  const rows = [];
  // 40 paired decisions: SER beats bandit on quality (+5%) at +0.5% cost
  // and +1% latency — should pass the 3-criteria AND-gate.
  for (let i = 0; i < 40; i++) {
    const q_actual = 0.78 + Math.random() * 0.04;
    const u_actual = 0.005 + Math.random() * 0.001;
    const l_actual = 1500 + Math.random() * 200;
    const disagree = i % 2 === 0;
    rows.push({
      v: 1, type: 'pair',
      ts: new Date(Date.now() - (40 - i) * 1000).toISOString(),
      task_hash: `task-${i.toString(16).padStart(8, '0')}`,
      bandit: {
        pick: 'sonnet',
        predictedQuality: q_actual - 0.02,
        predictedCostUsd: u_actual,
        backend: 'thompson-bandit',
      },
      ser: {
        pick: disagree ? 'opus' : 'sonnet',
        predictedQuality: disagree ? q_actual + 0.10 : q_actual + 0.01,
        predictedCostUsd: disagree ? u_actual * 1.005 : u_actual,
        backend: disagree ? 'metaharness-router-hybrid' : 'bandit-only',
      },
      outcome: {
        actualModel: 'sonnet',
        actualQuality: q_actual,
        actualUsd: u_actual,
        actualLatencyMs: Math.round(l_actual),
      },
    });
  }

  writeFileSync(jsonlPath, rows.map((r) => JSON.stringify(r)).join('\n') + '\n');
  assert(existsSync(jsonlPath), 'fixture JSONL written');
  assert(rows.length === 40, '40 pair rows synthesized');

  // ──────────────────────────────────────────────────────────────────
  // PHASE 2 — Verify recorder TS module compiles and exports the API.
  // ──────────────────────────────────────────────────────────────────
  console.log('\nPhase 2 — verify recorder TS module exports');

  const recorderTs = join(SCRIPTS_DIR, '..', '..', '..', 'v3', '@claude-flow', 'cli', 'src', 'ruvector', 'router-parallel-recorder.ts');
  const recorderSrc = readFileSync(recorderTs, 'utf-8');

  assert(/export function recordPair\b/.test(recorderSrc), 'recordPair exported');
  assert(/export function recordPairOutcome\b/.test(recorderSrc), 'recordPairOutcome exported');
  assert(/export function parallelRecorderStatus\b/.test(recorderSrc), 'parallelRecorderStatus exported');
  assert(/CLAUDE_FLOW_ROUTER_PARALLEL_LOG/.test(recorderSrc), 'env-gated by CLAUDE_FLOW_ROUTER_PARALLEL_LOG');
  // ADR-150 rule #3 — never throw
  assert(/never throws|never (throw|block)/i.test(recorderSrc), 'no-throw doc invariant present');
  // Try/catch around fs operations
  assert(/try \{[\s\S]*?appendFileSync[\s\S]*?\} catch/.test(recorderSrc), 'appendFileSync wrapped in try/catch');

  // ──────────────────────────────────────────────────────────────────
  // PHASE 3 — Run the analyzer against the synthesized JSONL.
  // ──────────────────────────────────────────────────────────────────
  console.log('\nPhase 3 — run analyzer against fixture');

  const analyzer = join(SCRIPTS_DIR, 'router-parallel-analyze.mjs');
  const r = spawnSync('node', [analyzer, '--input', jsonlPath, '--format', 'json'], {
    encoding: 'utf-8',
    timeout: 30_000,
  });
  assert(r.status === 0, `analyzer exit 0 (got ${r.status})`);

  let payload;
  try {
    payload = JSON.parse(r.stdout);
  } catch (e) {
    console.error('  stdout:', r.stdout.slice(0, 400));
    console.error('  stderr:', r.stderr.slice(0, 400));
    assert(false, `analyzer output parseable as JSON (${e.message})`);
    process.exit(2);
  }

  assert(payload.ok === true, 'payload.ok === true');
  assert(payload.sufficient === true, 'payload.sufficient === true (n>=30)');
  assert(payload.sampleSize === 40, `sampleSize === 40 (got ${payload.sampleSize})`);
  assert(typeof payload.disagreement?.pct === 'number', 'disagreement.pct numeric');

  // The 3 criteria must each be computed.
  assert(typeof payload.criteria?.qualityImprovementPct === 'number', 'criteria.qualityImprovementPct present');
  assert(typeof payload.criteria?.usdIncreasePct === 'number', 'criteria.usdIncreasePct present');
  assert(typeof payload.criteria?.latencyIncreasePct === 'number', 'criteria.latencyIncreasePct present');

  // Thresholds match ADR-150 review-round-1 exactly.
  assert(payload.criteria?.qualityThresholdPct === 2, 'quality threshold = 2%');
  assert(payload.criteria?.usdThresholdPct === 1, 'cost threshold = 1%');
  assert(payload.criteria?.latencyThresholdPct === 5, 'latency threshold = 5%');

  // For the promotable fixture, all three criteria should pass.
  assert(payload.criteria?.qualityPasses === true, 'quality > 2% passes');
  assert(payload.criteria?.costPasses === true, 'cost < 1% passes');
  assert(payload.criteria?.latencyPasses === true, 'latency < 5% passes');
  assert(payload.verdict?.promotable === true, 'verdict.promotable === true');

  // ──────────────────────────────────────────────────────────────────
  // PHASE 4 — Strict mode behavior.
  // ──────────────────────────────────────────────────────────────────
  console.log('\nPhase 4 — verify --strict semantics');

  const strictOk = spawnSync('node', [analyzer, '--input', jsonlPath, '--strict'], { encoding: 'utf-8', timeout: 30_000 });
  assert(strictOk.status === 0, '--strict on promotable fixture exits 0');

  // Synthesize a non-promotable fixture (quality gain only +1%, below 2% threshold).
  const badPath = join(fixture, 'non-promotable.jsonl');
  const badRows = [];
  for (let i = 0; i < 40; i++) {
    const q = 0.80;
    badRows.push({
      v: 1, type: 'pair',
      ts: new Date().toISOString(),
      task_hash: `bad-${i.toString(16).padStart(8, '0')}`,
      bandit: { pick: 'sonnet', predictedQuality: q, predictedCostUsd: 0.005, backend: 'thompson-bandit' },
      ser:    { pick: 'sonnet', predictedQuality: q + 0.005, predictedCostUsd: 0.005, backend: 'bandit-only' },
      outcome: { actualModel: 'sonnet', actualQuality: q, actualUsd: 0.005, actualLatencyMs: 1500 },
    });
  }
  writeFileSync(badPath, badRows.map((r) => JSON.stringify(r)).join('\n') + '\n');
  const strictBad = spawnSync('node', [analyzer, '--input', badPath, '--strict'], { encoding: 'utf-8', timeout: 30_000 });
  assert(strictBad.status === 1, '--strict on NON-promotable fixture exits 1 (got ' + strictBad.status + ')');

  // Cleanup
  if (process.env.TEST_PIPELINE_KEEP_FIXTURE !== '1') {
    rmSync(fixture, { recursive: true, force: true });
  } else {
    console.log(`\n(fixture kept at ${fixture})`);
  }

  console.log(`\n${passed} passed, ${failed} failed`);
  if (failed > 0) {
    console.log('\nFailures:');
    for (const f of failures) console.log(`  - ${f}`);
    process.exit(1);
  }
  console.log('\n✓ End-to-end pipeline test PASSED.');
}

main().catch((e) => {
  console.error('test-parallel-pipeline crashed:', e.message || e);
  process.exit(2);
});

#!/usr/bin/env node
// test-pipeline-roundtrip.mjs — end-to-end test of the ADR-152 §3.1
// cross-pipeline integration shipped iters 36→46.
//
// THE GAP THIS CLOSES
//   Every prior iter test exercised ONE surface in isolation:
//     iter 35: spike — synthetic LEGAL/SUPPORT/DEVOPS fixtures
//     iter 37: MCP runtime test — fake mem keys
//     iter 38: audit-trend — hand-written audit JSON
//     iter 39: unit tests — pure-function arithmetic
//     iter 41: bench — synthetic payloads
//     iter 43: Phase 4 — file-path fixtures
//     iter 46: audit_trend file inputs — same fixtures
//
//   None of these proved the FULL chain works end-to-end with no
//   synthetic data. This test does.
//
// THE PIPELINE BEING TESTED
//   1. oia-audit --dry-run --path .         (real run against ruflo)
//   2. The audit record's fingerprint{score,genome}
//   3. audit-trend --baseline {same-record} --current {same-record}
//   4. delta.structuralDistance.verdict === 'near-identical'
//   5. delta.structuralDistance.overall === 1
//
// USAGE
//   node scripts/test-pipeline-roundtrip.mjs
//   node scripts/test-pipeline-roundtrip.mjs --format json
//
// EXIT CODES
//   0  full chain works
//   1  some assertion failed
//   2  oia-audit degraded (upstream metaharness absent — test cannot run)
//
// ADR-150 ARCHITECTURAL CONSTRAINT BEHAVIOR
//   If oia-audit returns {degraded:true} (no upstream metaharness), the
//   test exits 2 with a clear message — this is the "test cannot run"
//   case, NOT a "test failed" case. CI infrastructure can distinguish.

import { spawnSync } from 'node:child_process';
import { mkdtempSync, writeFileSync, readFileSync, rmSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join, dirname } from 'node:path';
import { fileURLToPath } from 'node:url';

const SCRIPTS_DIR = dirname(fileURLToPath(import.meta.url));
const REPO_ROOT = dirname(dirname(dirname(SCRIPTS_DIR))); // up out of plugins/ruflo-metaharness/scripts

const ARGS = (() => {
  const a = { format: 'table' };
  for (let i = 2; i < process.argv.length; i++) {
    if (process.argv[i] === '--format') a.format = process.argv[++i];
  }
  return a;
})();

let passed = 0, failed = 0;
const failures = [];
function assert(cond, label) {
  if (cond) { console.log(`  ✓ ${label}`); passed++; }
  else { console.log(`  ✗ ${label}`); failures.push(label); failed++; }
}

function runNode(scriptName, args, timeoutMs = 60_000) {
  const p = spawnSync('node', [join(SCRIPTS_DIR, scriptName), ...args], {
    encoding: 'utf-8',
    timeout: timeoutMs,
    cwd: REPO_ROOT,
  });
  return { stdout: p.stdout || '', stderr: p.stderr || '', status: p.status ?? -1 };
}

// ──────────────────────────────────────────────────────────────────
console.log(`# test-pipeline-roundtrip — ADR-152 §3.1 end-to-end (iter 47)\n`);

const tmp = mkdtempSync(join(tmpdir(), 'pipeline-roundtrip-'));

try {
  // ──────────────────────────────────────────────────────────────
  // STAGE 1: oia-audit --dry-run against ruflo repo itself
  // ──────────────────────────────────────────────────────────────
  console.log('Stage 1 — oia-audit --dry-run against ruflo repo');
  const auditRun = runNode('oia-audit.mjs', ['--path', REPO_ROOT, '--dry-run', '--format', 'json'], 90_000);

  // Extract the JSON object from stdout (script may emit some prelude)
  const auditMatch = /\{[\s\S]*\}/.exec(auditRun.stdout);
  if (!auditMatch) {
    console.log(`  ✗ oia-audit produced no JSON; stderr:\n${auditRun.stderr.slice(0, 500)}`);
    process.exit(1);
  }
  const audit = JSON.parse(auditMatch[0]);

  // If oia-audit reports degraded (no upstream metaharness installed), skip
  // — this test cannot run without real score/genome output.
  if (audit.degraded === true) {
    console.log(`  ⊘ oia-audit reports degraded — upstream metaharness absent`);
    console.log(`     This test exercises real metaharness output; cannot run.`);
    console.log(`     reason: ${audit.reason}`);
    process.exit(2);
  }

  assert(typeof audit === 'object' && audit !== null,
    'oia-audit produced a JSON object');
  assert(typeof audit.composite === 'object',
    'oia-audit has composite worst-severity');
  assert(typeof audit.components === 'object',
    'oia-audit has components bundle');

  // iter 38 — fingerprint must be present
  assert(typeof audit.fingerprint === 'object' && audit.fingerprint !== null,
    'oia-audit emits fingerprint field (iter 38)');
  if (!audit.fingerprint?.score || !audit.fingerprint?.genome) {
    console.log(`  ⊘ fingerprint partial; score+genome may have degraded individually`);
    console.log(`     fingerprint: ${JSON.stringify(audit.fingerprint).slice(0, 200)}`);
    process.exit(2);
  }
  assert(typeof audit.fingerprint.score?.harnessFit === 'number',
    'fingerprint.score has harnessFit');
  assert(Array.isArray(audit.fingerprint.genome?.agent_topology),
    'fingerprint.genome has agent_topology array');

  // iter 49 — schema contracts beyond similarity (the OTHER class of
  // silent drift). audit-trend reads specific upstream fields:
  //   - composite.worst                            (severity rollup)
  //   - components.threatModel.json.worst          (audit-trend.mjs:96-100)
  //   - components.mcpScan.json.findings           (audit-trend.mjs:124-127)
  // If upstream renames any of these, audit-trend silently breaks.
  // Gating them here forces a CI failure on the next PR after upstream
  // schema drift, instead of months later when someone notices the
  // severity verdict has been wrong all along.
  assert(typeof audit.composite?.worst === 'string',
    'iter 49 — audit.composite.worst is a string');
  assert(['clean', 'low', 'medium', 'high'].includes(audit.composite.worst),
    `iter 49 — composite.worst in valid severity vocab (got ${audit.composite.worst})`);
  // threatModel.json.worst is the upstream field audit-trend reads
  if (audit.components?.threatModel && !audit.components.threatModel.degraded) {
    assert(typeof audit.components.threatModel.json?.worst === 'string',
      'iter 49 — components.threatModel.json.worst is a string (audit-trend dep)');
  }
  // mcp-scan.mjs currently emits {rawStdout, durationMs, alert} —
  // no structured `findings` array. audit-trend.mjs reads
  // `json.findings` (guarded with Array.isArray fallback to []) so it
  // doesn't crash, but the introduced/cleared logic is effectively
  // a no-op on real output. iter 49 documents this gap rather than
  // asserting a contract that doesn't yet hold. If a future iter
  // promotes mcp-scan.mjs to emit structured findings, this assertion
  // should become a real type-check.
  if (audit.components?.mcpScan?.json?.findings !== undefined) {
    assert(Array.isArray(audit.components.mcpScan.json.findings),
      'iter 49 — IF mcpScan.json.findings exists THEN it must be an array');
  } else {
    console.log(`  ⊘ mcpScan.json.findings absent (mcp-scan.mjs currently text-only — known iter-49 gap)`);
  }

  // ──────────────────────────────────────────────────────────────
  // STAGE 2: persist the audit record as both baseline and current
  // ──────────────────────────────────────────────────────────────
  console.log('\nStage 2 — write audit record to baseline + current paths');
  const basePath = join(tmp, 'baseline.json');
  const currPath = join(tmp, 'current.json');
  writeFileSync(basePath, JSON.stringify(audit));
  writeFileSync(currPath, JSON.stringify(audit));
  assert(readFileSync(basePath, 'utf-8').length > 100, 'baseline file written');
  assert(readFileSync(currPath, 'utf-8').length > 100, 'current file written');

  // ──────────────────────────────────────────────────────────────
  // STAGE 3: audit-trend reading the same audit twice
  // ──────────────────────────────────────────────────────────────
  console.log('\nStage 3 — audit-trend against self (must report near-identical)');
  const trendRun = runNode('audit-trend.mjs', [
    '--baseline', basePath,
    '--current', currPath,
    '--format', 'json',
  ]);

  const trendMatch = /\{[\s\S]*\}/.exec(trendRun.stdout);
  assert(trendMatch !== null, 'audit-trend produced JSON');
  const trend = JSON.parse(trendMatch[0]);

  assert(typeof trend.delta?.structuralDistance === 'object',
    'trend exposes delta.structuralDistance');
  const sd = trend.delta.structuralDistance;
  assert(sd.verdict === 'near-identical',
    `self-roundtrip verdict === near-identical (got ${sd.verdict})`);
  assert(sd.overall === 1,
    `self-roundtrip overall === 1 (got ${sd.overall})`);
  assert(sd.distance === 0,
    `self-roundtrip distance === 0 (got ${sd.distance})`);

  // ──────────────────────────────────────────────────────────────
  // STAGE 4: alert-on-distance-below should NOT trigger on self-match
  // ──────────────────────────────────────────────────────────────
  console.log('\nStage 4 — distance alert does not trigger on self-match');
  const noAlertRun = runNode('audit-trend.mjs', [
    '--baseline', basePath,
    '--current', currPath,
    '--alert-on-distance-below', '0.5',
    '--format', 'json',
  ]);
  assert(noAlertRun.status === 0,
    `alert at threshold 0.5 does NOT fire on self-match (exit 0, got ${noAlertRun.status})`);

  // Now flip: any threshold above 1 must trigger
  console.log('\nStage 5 — distance alert triggers when threshold > self-match');
  const alertRun = runNode('audit-trend.mjs', [
    '--baseline', basePath,
    '--current', currPath,
    '--alert-on-distance-below', '1.01',
    '--format', 'json',
  ]);
  assert(alertRun.status === 1,
    `alert at threshold 1.01 fires on self-match (exit 1, got ${alertRun.status})`);

  // ──────────────────────────────────────────────────────────────
  // STAGE 6 (iter 49) — non-similarity schema contracts in the trend
  //
  // audit-trend reads `composite.worst`, `components.threatModel.json.worst`,
  // and `components.mcpScan.json.findings`. The trend output's
  // delta.worst.verdict on a self-match must be 'unchanged'. If upstream
  // renames any of these fields, the verdict silently becomes 'missing'
  // or undefined — this assertion catches that BEFORE shipping.
  // ──────────────────────────────────────────────────────────────
  // ──────────────────────────────────────────────────────────────
  // STAGE 7 (iter 51) — drift detection actually FIRES on mutated input
  //
  // Every prior stage uses the same audit record twice (self-match).
  // That proves the chain doesn't FALSELY report drift on identical
  // input, but doesn't prove the chain catches REAL drift. This stage
  // takes the audit record and synthetically mutates fields the
  // similarity module reads, then asserts the chain detects the
  // difference.
  //
  // Mutations applied (all measurable by similarity):
  //   - harnessFit:  unchanged   → -20   (cosine signal)
  //   - taskCoverage: unchanged  → -15   (cosine signal)
  //   - agent_topology: add one  → jaccard divergence
  //
  // Expected outcome:
  //   - structuralDistance.verdict !== 'near-identical'
  //   - structuralDistance.overall < 1
  //   - --alert-on-distance-below 0.95 should fire
  // ──────────────────────────────────────────────────────────────
  console.log('\nStage 7 — drift detection on mutated audit (iter 51)');
  const mutatedPath = join(tmp, 'mutated.json');
  const mutated = JSON.parse(JSON.stringify(audit));
  // Modify fields the similarity module actually reads. The mutation has
  // to be large enough to cross the verdict-bucket threshold (0.95 →
  // 'near-identical' boundary). The 9-dim cosine vector is dominated by
  // values already clustered around the same range, so single-field
  // changes don't move overall much. Mutate across all 3 components:
  //   - cosine: drop 4 scorecard fields by 25-40 points
  //   - categorical: swap archetype + template (2 of 4 enums diverge)
  //   - jaccard: rebuild agent_topology with a different set
  mutated.fingerprint.score.harnessFit = Math.max(0, audit.fingerprint.score.harnessFit - 40);
  mutated.fingerprint.score.taskCoverage = Math.max(0, audit.fingerprint.score.taskCoverage - 35);
  mutated.fingerprint.score.toolSafety = Math.max(0, audit.fingerprint.score.toolSafety - 30);
  mutated.fingerprint.score.compileConfidence = Math.max(0, audit.fingerprint.score.compileConfidence - 25);
  mutated.fingerprint.score.archetype = 'iter-51-synthetic-archetype';
  mutated.fingerprint.score.template = 'iter-51-synthetic-template';
  mutated.fingerprint.genome.agent_topology = ['iter-51-marker-a', 'iter-51-marker-b'];
  writeFileSync(mutatedPath, JSON.stringify(mutated));

  const driftRun = runNode('audit-trend.mjs', [
    '--baseline', basePath,
    '--current', mutatedPath,
    '--format', 'json',
  ]);
  const driftMatch = /\{[\s\S]*\}/.exec(driftRun.stdout);
  assert(driftMatch !== null, 'drift run produced JSON');
  const driftTrend = JSON.parse(driftMatch[0]);
  const driftSd = driftTrend.delta?.structuralDistance;
  assert(typeof driftSd === 'object', 'drift trend exposes structuralDistance');
  assert(driftSd.verdict !== 'near-identical',
    `drift detected — verdict !== near-identical (got ${driftSd?.verdict})`);
  assert(driftSd.overall < 1,
    `drift detected — overall < 1 (got ${driftSd?.overall})`);
  assert(driftSd.distance > 0,
    `drift detected — distance > 0 (got ${driftSd?.distance})`);

  // Alert chain: --alert-on-distance-below 0.95 must fire IF drift > 0.05
  // If the synthetic mutation produced overall ≥ 0.95, lower the threshold.
  const threshold = driftSd.overall < 0.95 ? '0.95' : String(driftSd.overall + 0.01);
  const alertDriftRun = runNode('audit-trend.mjs', [
    '--baseline', basePath,
    '--current', mutatedPath,
    '--alert-on-distance-below', threshold,
    '--format', 'json',
  ]);
  assert(alertDriftRun.status === 1,
    `drift alert at threshold ${threshold} fires on mutated audit (exit 1, got ${alertDriftRun.status})`);

  // ──────────────────────────────────────────────────────────────
  console.log('\nStage 6 — non-similarity schema contracts (iter 49)');
  assert(typeof trend.delta?.worst === 'object',
    'trend exposes delta.worst (severity-rollup)');
  assert(trend.delta.worst.verdict === 'unchanged',
    `self-roundtrip severity-verdict === unchanged (got ${trend.delta.worst.verdict})`);
  assert(trend.delta.worst.baseline === trend.delta.worst.current,
    'self-roundtrip baseline === current severity');
  assert(trend.delta.worst.rankDelta === 0,
    `self-roundtrip rankDelta === 0 (got ${trend.delta.worst.rankDelta})`);
  // Findings arrays: introduced/cleared must both be 0 on self-match
  assert(trend.delta?.findings?.introducedCount === 0,
    `self-roundtrip introducedCount === 0 (got ${trend.delta?.findings?.introducedCount})`);
  assert(trend.delta?.findings?.clearedCount === 0,
    `self-roundtrip clearedCount === 0 (got ${trend.delta?.findings?.clearedCount})`);

  // ──────────────────────────────────────────────────────────────
  // STAGE 8 (iter 68) — drift-from-history end-to-end via --baseline-file
  //
  // Every prior stage tested audit-trend (the underlying primitive).
  // None tested drift-from-history (the iter-53 user-facing wrapper).
  // This stage runs the iter-67 fastest path: baseline from a file,
  // skipping audit-list AND memory roundtrip entirely.
  // ──────────────────────────────────────────────────────────────
  console.log('\nStage 8 — drift-from-history end-to-end (iter 68)');
  const driftFromHistoryRun = runNode('drift-from-history.mjs', [
    '--baseline-file', basePath,
    '--dry-run',
    '--format', 'json',
  ], 120_000);
  const driftFromHistoryMatch = /\{[\s\S]*\}/.exec(driftFromHistoryRun.stdout);
  assert(driftFromHistoryMatch !== null, 'drift-from-history produced JSON');
  const dfh = JSON.parse(driftFromHistoryMatch[0]);

  // Iter-66/iter-67 contract: the fastest-path flags are surfaced in timing
  assert(dfh.timing?.skippedAuditList === true,
    'drift-from-history --baseline-file → skippedAuditList === true (iter 66)');
  assert(dfh.timing?.usedBaselineFile === true,
    'drift-from-history --baseline-file → usedBaselineFile === true (iter 67)');
  // Wall-clock fastpath proof: must be under 30s with file inputs
  // (vs ~26s minimum for the audit-list-loading slow path)
  assert(typeof dfh.timing?.parallelWallMs === 'number' && dfh.timing.parallelWallMs < 30000,
    `drift-from-history fastpath wall < 30s (got ${dfh.timing?.parallelWallMs}ms)`);
  // Same-file self-match → similarity 1.0
  assert(dfh.drift?.structuralDistance?.overall === 1,
    `drift-from-history self-match overall === 1 (got ${dfh.drift?.structuralDistance?.overall})`);
  assert(dfh.drift?.structuralDistance?.verdict === 'near-identical',
    `drift-from-history self-match verdict === near-identical (got ${dfh.drift?.structuralDistance?.verdict})`);
  // Alert chain end-to-end
  assert(dfh.alert?.triggered === false,
    'drift-from-history self-match alert NOT triggered at default threshold (0.95)');

  // ──────────────────────────────────────────────────────────────
  // STAGE 9 (iter 75) — drift-from-history detects drift via fast path
  //
  // Stage 8 proved the fast path correctly identifies self-match.
  // This stage proves it also CATCHES drift — feeds a mutated baseline
  // file and asserts the verdict flips. Without this, a regression
  // that breaks the fast path's similarity computation would still
  // pass Stage 8 (which only checks the identity case).
  //
  // Mutation: re-uses Stage 7's mutated audit shape, written to a
  // separate baseline file. drift-from-history runs fresh oia-audit
  // against current state and diffs against the mutated baseline.
  // ──────────────────────────────────────────────────────────────
  console.log('\nStage 9 — drift-from-history fastpath catches mutation (iter 75)');
  // mutatedPath was already populated in Stage 7. Re-use as baseline-file.
  const dfhDriftRun = runNode('drift-from-history.mjs', [
    '--baseline-file', mutatedPath,
    '--dry-run',
    '--threshold', '0.95',
    '--format', 'json',
  ], 120_000);
  const dfhDriftMatch = /\{[\s\S]*\}/.exec(dfhDriftRun.stdout);
  assert(dfhDriftMatch !== null, 'drift-from-history with mutated baseline produced JSON');
  const dfhDrift = JSON.parse(dfhDriftMatch[0]);

  // Fast path still fired
  assert(dfhDrift.timing?.usedBaselineFile === true,
    'Stage 9 fastpath: usedBaselineFile === true');

  // Drift detected — same invariants as Stage 7 but via the wrapper
  const dfhSd = dfhDrift.drift?.structuralDistance;
  assert(typeof dfhSd === 'object', 'Stage 9: structuralDistance present');
  assert(dfhSd.verdict !== 'near-identical',
    `Stage 9: verdict !== near-identical (got ${dfhSd?.verdict}) — fastpath catches drift`);
  assert(dfhSd.overall < 1,
    `Stage 9: overall < 1 (got ${dfhSd?.overall})`);
  assert(dfhSd.distance > 0,
    `Stage 9: distance > 0 (got ${dfhSd?.distance})`);

  // Alert end-to-end via the fast path
  // (mutation pushes overall ~0.7, below default 0.95 threshold → triggered)
  assert(dfhDrift.alert?.triggered === true,
    'Stage 9: --threshold 0.95 fires on mutated baseline via fastpath');
  // Exit code reflects alert
  assert(dfhDriftRun.status === 1,
    `Stage 9: drift-from-history exit=1 when alert triggered (got ${dfhDriftRun.status})`);

  // ──────────────────────────────────────────────────────────────
  // STAGE 10 (iter 76) — introduced/cleared findings diff actually works
  //
  // Iter 49 documented that mcp-scan emitted text only → audit-trend's
  // findings.introducedCount was dead code. Iter 50 added the parser
  // so findings ARE populated. But no test verified the diff on a
  // REAL finding-set change — Stage 7 mutates only the fingerprint
  // (score/genome), leaving mcpScan.json.findings unchanged.
  //
  // This stage takes the real audit (Stage 1) and mutates ONLY
  // mcpScan.json.findings — adds a synthetic finding to the baseline.
  // audit-trend should report clearedCount === 1 (the synthetic
  // disappeared in the current audit) with severity preserved.
  // ──────────────────────────────────────────────────────────────
  console.log('\nStage 10 — introduced/cleared findings diff (iter 76 — locks iter-50 fix)');
  const findingsBasePath = join(tmp, 'findings-base.json');
  const findingsMutated = JSON.parse(JSON.stringify(audit));
  // Ensure mcpScan.json.findings exists (it should post-iter-50)
  if (!findingsMutated.components?.mcpScan?.json?.findings) {
    findingsMutated.components.mcpScan = findingsMutated.components.mcpScan ?? {};
    findingsMutated.components.mcpScan.json = findingsMutated.components.mcpScan.json ?? {};
    findingsMutated.components.mcpScan.json.findings = [];
  }
  // Append a synthetic finding that wouldn't appear in a fresh audit.
  findingsMutated.components.mcpScan.json.findings.push({
    severity: 'medium',
    id: 'iter-76-synthetic-finding',
    server: 'synthetic-server',
    tool: 'synthetic-tool',
    message: 'Stage 10 synthetic finding for clearedCount verification',
  });
  writeFileSync(findingsBasePath, JSON.stringify(findingsMutated));

  // Diff: baseline has the synthetic, current (real audit) doesn't →
  // expect clearedCount === 1, introducedCount === 0.
  const findingsTrendRun = runNode('audit-trend.mjs', [
    '--baseline', findingsBasePath,
    '--current', basePath,  // basePath = unmodified audit
    '--format', 'json',
  ], 60_000);
  const findingsTrendMatch = /\{[\s\S]*\}/.exec(findingsTrendRun.stdout);
  assert(findingsTrendMatch !== null, 'Stage 10: audit-trend produced JSON');
  const findingsTrend = JSON.parse(findingsTrendMatch[0]);

  assert(findingsTrend.delta?.findings?.clearedCount === 1,
    `Stage 10: clearedCount === 1 (got ${findingsTrend.delta?.findings?.clearedCount}) — iter-50 fix functional`);
  assert(findingsTrend.delta?.findings?.introducedCount === 0,
    `Stage 10: introducedCount === 0 (got ${findingsTrend.delta?.findings?.introducedCount})`);
  // Cleared finding's severity preserved through the diff
  const cleared = findingsTrend.delta?.findings?.cleared?.[0];
  assert(cleared?.severity === 'medium',
    `Stage 10: cleared finding severity preserved (got ${cleared?.severity})`);
  assert(cleared?.id === 'iter-76-synthetic-finding',
    'Stage 10: cleared finding id preserved');

  // ──────────────────────────────────────────────────────────────
  // STAGE 11 (iter 77) — introducedCount symmetry + dedup discrimination
  //
  // Stage 10 proved the CLEARED side. Three more cases to lock the
  // diff logic completely:
  //
  //   11a. introducedCount: baseline clean, current has synthetic
  //   11b. both-different:  baseline has finding A, current has finding B
  //                          → introduced=1, cleared=1
  //   11c. identical:       baseline + current have SAME finding
  //                          → both counters stay at 0 (dedup works)
  // ──────────────────────────────────────────────────────────────
  console.log('\nStage 11 — introduced/cleared symmetric + dedup (iter 77)');
  const findingA = {
    severity: 'medium',
    id: 'iter-77-finding-A',
    server: 'server-A',
    tool: 'tool-A',
    message: 'finding A',
  };
  const findingB = {
    severity: 'high',
    id: 'iter-77-finding-B',
    server: 'server-B',
    tool: 'tool-B',
    message: 'finding B',
  };

  // 11a — introduced
  const baseClean = JSON.parse(JSON.stringify(audit));
  baseClean.components.mcpScan.json.findings = [];
  const currentWithA = JSON.parse(JSON.stringify(audit));
  currentWithA.components.mcpScan.json.findings = [findingA];
  const baseCleanPath = join(tmp, 'base-clean.json');
  const currentWithAPath = join(tmp, 'current-A.json');
  writeFileSync(baseCleanPath, JSON.stringify(baseClean));
  writeFileSync(currentWithAPath, JSON.stringify(currentWithA));
  const trendRun11a = runNode('audit-trend.mjs', [
    '--baseline', baseCleanPath, '--current', currentWithAPath, '--format', 'json',
  ], 60_000);
  const m11a = /\{[\s\S]*\}/.exec(trendRun11a.stdout);
  const trend11a = JSON.parse(m11a[0]);
  assert(trend11a.delta?.findings?.introducedCount === 1,
    `Stage 11a: introducedCount === 1 (got ${trend11a.delta?.findings?.introducedCount})`);
  assert(trend11a.delta?.findings?.clearedCount === 0,
    `Stage 11a: clearedCount === 0 (got ${trend11a.delta?.findings?.clearedCount})`);
  assert(trend11a.delta?.findings?.introduced?.[0]?.id === 'iter-77-finding-A',
    'Stage 11a: introduced finding id preserved');

  // 11b — both different
  const baselineWithB = JSON.parse(JSON.stringify(audit));
  baselineWithB.components.mcpScan.json.findings = [findingB];
  const baselineWithBPath = join(tmp, 'baseline-B.json');
  writeFileSync(baselineWithBPath, JSON.stringify(baselineWithB));
  const trendRun11b = runNode('audit-trend.mjs', [
    '--baseline', baselineWithBPath, '--current', currentWithAPath, '--format', 'json',
  ], 60_000);
  const m11b = /\{[\s\S]*\}/.exec(trendRun11b.stdout);
  const trend11b = JSON.parse(m11b[0]);
  assert(trend11b.delta?.findings?.introducedCount === 1,
    `Stage 11b: introducedCount === 1 (got ${trend11b.delta?.findings?.introducedCount})`);
  assert(trend11b.delta?.findings?.clearedCount === 1,
    `Stage 11b: clearedCount === 1 (got ${trend11b.delta?.findings?.clearedCount})`);
  // Dedup discriminates: B was cleared, A was introduced
  assert(trend11b.delta?.findings?.cleared?.[0]?.id === 'iter-77-finding-B',
    'Stage 11b: dedup correctly identifies B as cleared');
  assert(trend11b.delta?.findings?.introduced?.[0]?.id === 'iter-77-finding-A',
    'Stage 11b: dedup correctly identifies A as introduced');

  // 11c — identical findings on both sides
  const trendRun11c = runNode('audit-trend.mjs', [
    '--baseline', currentWithAPath, '--current', currentWithAPath, '--format', 'json',
  ], 60_000);
  const m11c = /\{[\s\S]*\}/.exec(trendRun11c.stdout);
  const trend11c = JSON.parse(m11c[0]);
  assert(trend11c.delta?.findings?.introducedCount === 0,
    `Stage 11c: identical findings → introducedCount === 0 (dedup works)`);
  assert(trend11c.delta?.findings?.clearedCount === 0,
    `Stage 11c: identical findings → clearedCount === 0`);

  // ──────────────────────────────────────────────────────────────
  // STAGE 12 (iter 79) — --alert-on-new-severity orthogonal gate
  //
  // Iter 78 added the gate. Iter 79 wires it into the weekly cron.
  // This stage verifies the gate fires correctly through the
  // drift-from-history wrapper:
  //   - baseline has no findings + current has 1 medium finding
  //   - --threshold 0.5 (similarity stays above)
  //   - --alert-on-new-severity medium should trigger
  //
  // Catches the "structural similarity high but new security
  // finding" case that iter-78 closed.
  // ──────────────────────────────────────────────────────────────
  console.log('\nStage 12 — --alert-on-new-severity orthogonal gate (iter 79)');

  // Re-use baseClean (no findings) from Stage 11
  // Run drift-from-history with --alert-on-new-severity info
  // (real ruflo audit has 1 INFO finding → introduced=1)
  const stage12Run = runNode('drift-from-history.mjs', [
    '--baseline-file', baseCleanPath,
    '--dry-run',
    '--threshold', '0.5',
    '--alert-on-new-severity', 'info',
    '--format', 'json',
  ], 120_000);
  const m12 = /\{[\s\S]*\}/.exec(stage12Run.stdout);
  assert(m12 !== null, 'Stage 12: drift-from-history produced JSON');
  const stage12 = JSON.parse(m12[0]);

  // The orthogonal gate fires
  assert(stage12.alert?.triggered === true,
    'Stage 12: --alert-on-new-severity info triggers on ruflo current INFO finding');
  // Reason mentions severity, not similarity (structural is fine at threshold 0.5)
  const reasons = stage12.alert?.reasons ?? [];
  const hasSeverityReason = reasons.some((r) => /finding\(s\) at or above/.test(r));
  assert(hasSeverityReason,
    `Stage 12: reasons mention new-finding severity (got ${JSON.stringify(reasons)})`);
  // elevatedFindings populated
  assert(Array.isArray(stage12.alert?.elevatedFindings) && stage12.alert.elevatedFindings.length >= 1,
    `Stage 12: elevatedFindings non-empty (got ${stage12.alert?.elevatedFindings?.length})`);
  // CLI exit reflects the alert
  assert(stage12Run.status === 1,
    `Stage 12: drift-from-history exit=1 on severity alert (got ${stage12Run.status})`);
  // newSeverityThreshold echoed in payload
  assert(stage12.alert?.newSeverityThreshold === 'info',
    'Stage 12: alert.newSeverityThreshold echoed');

} finally {
  try { rmSync(tmp, { recursive: true, force: true }); } catch { /* ignore */ }
}

// ──────────────────────────────────────────────────────────────────
const summary = { passed, failed, total: passed + failed, failures };

console.log(`\n${passed} passed, ${failed} failed`);
if (ARGS.format === 'json') console.log(JSON.stringify(summary, null, 2));
if (failed > 0) {
  console.log('\nFailures:');
  for (const f of failures) console.log(`  - ${f}`);
  process.exit(1);
}
console.log('\n✓ Full ADR-152 §3.1 pipeline works end-to-end with real metaharness output.');

#!/usr/bin/env node
// test-similarity.mjs — unit tests for the iter-36 production module
// `_similarity.mjs` (ADR-152 §3.1).
//
// The spike (_spike-similarity.mjs) verifies the two architectural
// invariants on synthetic fixtures. This test exercises each public
// function in isolation: projectToVec, cosine, categoricalAgreement,
// jaccard, similarity, opts.weights override, opts.perDimension shape.
//
// CONTRACT EACH FUNCTION MUST SATISFY
//   - input contract documented in _similarity.mjs holds
//   - missing optional fields default safely (graceful, never throws)
//   - numerical results are deterministic (no floats from Math.random)
//   - return shapes match ADR-152 §"return shape"
//
// USAGE
//   node scripts/test-similarity.mjs
//   node scripts/test-similarity.mjs --format json
//
// EXIT
//   0  all unit tests pass
//   1  at least one test failed

import {
  projectToVec, cosine, categoricalAgreement, jaccard, similarity,
} from './_similarity.mjs';
// iter 64 — also test the iter-63 shared severity primitives
import { SEVERITY_RANK, rankSeverity, parseMcpScanText } from './_harness.mjs';

const ARGS = (() => {
  const a = { format: 'table' };
  for (let i = 2; i < process.argv.length; i++) {
    if (process.argv[i] === '--format') a.format = process.argv[++i];
  }
  return a;
})();

let passed = 0, failed = 0;
const failures = [];

function assert(cond, label) {
  if (cond) { console.log(`  ✓ ${label}`); passed++; }
  else { console.log(`  ✗ ${label}`); failures.push(label); failed++; }
}

function approx(a, b, eps = 0.0001) {
  return Math.abs(a - b) < eps;
}

// ──────────────────────────────────────────────────────────────────
// FIXTURES — share two harness shapes across all tests
// ──────────────────────────────────────────────────────────────────

const A = {
  score: {
    harnessFit: 80, compileConfidence: 100, taskCoverage: 70, toolSafety: 90,
    memoryUsefulness: 50, estCostPerRunUsd: 0.05, recommendedMode: 'CLI + MCP',
    archetype: 'typescript-sdk-harness', template: 'vertical:coding',
  },
  genome: {
    repo_type: 'node_mcp_ci',
    agent_topology: ['maintainer', 'tester', 'security'],
    risk_score: 0.3, test_confidence: 0.85, publish_readiness: 0.9,
  },
};

const B = {
  score: {
    harnessFit: 60, compileConfidence: 80, taskCoverage: 50, toolSafety: 70,
    memoryUsefulness: 30, estCostPerRunUsd: 0.02, recommendedMode: 'CLI',
    archetype: 'python-agent-harness', template: 'vertical:devops',
  },
  genome: {
    repo_type: 'python_ops',
    agent_topology: ['deployer', 'rollback'],
    risk_score: 0.1, test_confidence: 0.6, publish_readiness: 0.5,
  },
};

// ──────────────────────────────────────────────────────────────────
console.log(`# test-similarity — _similarity.mjs unit tests (iter 39)\n`);

console.log('Phase 1 — projectToVec');
const vA = projectToVec(A);
assert(Array.isArray(vA), 'returns an array');
assert(vA.length === 9, 'returns 9-dim vector (ADR-152 §Decision Table 1)');
assert(approx(vA[0], 0.80), 'index 0 = harnessFit/100 (80 → 0.80)');
assert(approx(vA[1], 1.00), 'index 1 = compileConfidence/100 (100 → 1.00)');
assert(approx(vA[2], 0.70), 'index 2 = taskCoverage/100');
assert(approx(vA[3], 0.90), 'index 3 = toolSafety/100');
assert(approx(vA[4], 0.50), 'index 4 = memoryUsefulness/100');
assert(approx(vA[5], 0.30), 'index 5 = risk_score (already 0..1)');
assert(approx(vA[6], 0.85), 'index 6 = test_confidence');
assert(approx(vA[7], 0.90), 'index 7 = publish_readiness');
// Missing-field defaults safely (graceful degradation)
const vEmpty = projectToVec({});
assert(vEmpty.length === 9, 'empty input still returns 9-dim');
assert(vEmpty.every((x) => typeof x === 'number'), 'all elements numeric (no NaN propagation)');
const vNoGenome = projectToVec({ score: A.score });
assert(approx(vNoGenome[5], 0), 'missing genome → risk_score=0 default');
assert(approx(vNoGenome[0], 0.80), 'missing genome does not corrupt score-derived indices');

console.log('\nPhase 2 — cosine');
assert(approx(cosine(vA, vA), 1), 'cosine(x, x) === 1');
assert(approx(cosine([1, 0], [0, 1]), 0), 'orthogonal vectors → 0');
assert(approx(cosine([0, 0, 0], [1, 1, 1]), 0), 'zero vector → 0 (graceful divide-by-zero)');
assert(cosine([1, 2], [1, 2, 3]) === 0, 'length mismatch → 0 (graceful)');
assert(cosine(null, vA) === 0, 'null input → 0 (graceful)');
const cosAB = cosine(vA, projectToVec(B));
assert(cosAB >= 0 && cosAB <= 1, 'output bounded to [0, 1] for nonneg vectors');

console.log('\nPhase 3 — categoricalAgreement');
assert(approx(categoricalAgreement(A, A), 1), 'identical input → 1 (all 4 enums match)');
assert(approx(categoricalAgreement(A, B), 0), 'A vs B → 0 (all 4 enums differ)');
assert(approx(categoricalAgreement({}, {}), 0), 'both empty → 0 (no matches counted)');
// Partial match — 2 of 4 fields agree
const partial = {
  score: { archetype: A.score.archetype, template: 'different', recommendedMode: A.score.recommendedMode },
  genome: { repo_type: 'different' },
};
assert(approx(categoricalAgreement(A, partial), 0.5),
  '2-of-4 partial match → 0.5 (archetype + recommendedMode)');

console.log('\nPhase 4 — jaccard');
assert(approx(jaccard(A, A), 1), 'identical topology → 1');
assert(approx(jaccard(A, B), 0), 'disjoint topology → 0');
assert(approx(jaccard({ genome: {} }, { genome: {} }), 1),
  'both empty topology → 1 (set-equality convention)');
const overlap = {
  genome: { agent_topology: ['maintainer', 'tester', 'extra'] },
};
// A has {maintainer, tester, security}; overlap has {maintainer, tester, extra}
// |A ∩ B|=2, |A ∪ B|=4 → 2/4 = 0.5
assert(approx(jaccard(A, overlap), 0.5), 'partial topology overlap → |∩|/|∪|');

console.log('\nPhase 5 — similarity composite + return shape');
const sAA = similarity(A, A);
assert(typeof sAA === 'object' && sAA !== null, 'returns object');
assert(typeof sAA.overall === 'number', 'overall is numeric');
assert(approx(sAA.overall, 1), 'similarity(X, X).overall === 1');
assert(typeof sAA.components === 'object', 'components present');
assert(approx(sAA.components.cosine, 1), 'components.cosine === 1 on self-match');
assert(approx(sAA.components.categorical, 1), 'components.categorical === 1');
assert(approx(sAA.components.jaccard, 1), 'components.jaccard === 1');
assert(typeof sAA.weights === 'object', 'weights echoed in return');
assert(approx(sAA.weights.cosine, 0.6), 'default cosine weight = 0.6 (ADR-152)');
assert(approx(sAA.weights.categorical, 0.25), 'default categorical weight = 0.25');
assert(approx(sAA.weights.jaccard, 0.15), 'default jaccard weight = 0.15');
assert(approx(sAA.weights.cosine + sAA.weights.categorical + sAA.weights.jaccard, 1),
  'default weights sum to 1');

console.log('\nPhase 6 — similarity opts.weights override');
const reweighted = similarity(A, B, { weights: { cosine: 0, categorical: 0, jaccard: 1 } });
const jacOnly = jaccard(A, B);
assert(approx(reweighted.overall, jacOnly),
  'opts.weights cosine=0/cat=0/jac=1 → overall === jaccard');
const reweighted2 = similarity(A, A, { weights: { cosine: 0.5, categorical: 0.3, jaccard: 0.2 } });
assert(approx(reweighted2.overall, 1),
  'self-match holds under any weight scheme');

console.log('\nPhase 7 — similarity opts.perDimension shape');
const sPD = similarity(A, B, { perDimension: true });
assert(typeof sPD.perDimension === 'object', 'perDimension included when requested');
assert('numeric.harnessFit' in sPD.perDimension,
  'perDimension exposes each numeric feature by name');
assert('categorical.archetype' in sPD.perDimension,
  'perDimension exposes each categorical field by name');
assert('set.agent_topology' in sPD.perDimension,
  'perDimension exposes the set-typed feature');
const hf = sPD.perDimension['numeric.harnessFit'];
assert(hf.a === 80 && hf.b === 60, 'perDimension preserves raw a/b values');
assert(typeof hf.contribution === 'number', 'perDimension has numeric contribution');
const sNoPD = similarity(A, B);
assert(!('perDimension' in sNoPD), 'perDimension omitted by default');

console.log('\nPhase 8 — round-trip with the iter-35 spike fixtures (regression anchor)');
// Hard-coded spike numbers from `_spike-similarity.mjs` — ANY change
// here means the production module drifted from the spike's frozen
// invariants (catches future weight or normalization changes).
const LEGAL = {
  score: { harnessFit: 78, compileConfidence: 92, taskCoverage: 65, toolSafety: 88, memoryUsefulness: 70, estCostPerRunUsd: 0.04, recommendedMode: 'CLI + MCP', archetype: 'compliance-harness', template: 'vertical:legal' },
  genome: { repo_type: 'node_mcp_ci', agent_topology: ['contract-analyst', 'redline-reviewer', 'risk-rater', 'compliance-officer'], risk_score: 0.45, test_confidence: 0.7, publish_readiness: 0.6 },
};
const SUPPORT = {
  score: { harnessFit: 75, compileConfidence: 90, taskCoverage: 70, toolSafety: 90, memoryUsefulness: 72, estCostPerRunUsd: 0.05, recommendedMode: 'CLI + MCP', archetype: 'compliance-harness', template: 'vertical:support' },
  genome: { repo_type: 'node_mcp_ci', agent_topology: ['triager', 'kb-searcher', 'responder', 'risk-rater', 'compliance-officer'], risk_score: 0.40, test_confidence: 0.75, publish_readiness: 0.65 },
};
const sLS = similarity(LEGAL, SUPPORT);
assert(sLS.overall === 0.8296,
  `LEGAL × SUPPORT overall must be exactly 0.8296 (got ${sLS.overall})`);
assert(sLS.components.cosine === 0.9987,
  `LEGAL × SUPPORT cosine must be 0.9987 (got ${sLS.components.cosine})`);
assert(sLS.components.categorical === 0.75,
  `LEGAL × SUPPORT categorical must be 0.75 (got ${sLS.components.categorical})`);
assert(sLS.components.jaccard === 0.2857,
  `LEGAL × SUPPORT jaccard must be 0.2857 (got ${sLS.components.jaccard})`);

console.log('\nPhase 9 — iter-63 shared SEVERITY_RANK + rankSeverity()');
// Known severities — full vocab the iter-50 parser produces
assert(SEVERITY_RANK.clean === 0, 'rank.clean === 0');
assert(SEVERITY_RANK.info === 0, 'rank.info === 0 (informational, no harm)');
assert(SEVERITY_RANK.low === 1, 'rank.low === 1');
assert(SEVERITY_RANK.medium === 2, 'rank.medium === 2');
assert(SEVERITY_RANK.warn === 2, 'rank.warn === 2 (warn ≈ medium)');
assert(SEVERITY_RANK.high === 3, 'rank.high === 3');
assert(SEVERITY_RANK.error === 3, 'rank.error === 3 (error ≈ high)');
assert(SEVERITY_RANK.critical === 4, 'rank.critical === 4 (elevated above high)');

// Object.freeze blocks mutation — anti-tamper guard
const before = SEVERITY_RANK.high;
let mutated = false;
try { SEVERITY_RANK.high = 999; mutated = SEVERITY_RANK.high !== before; } catch { /* strict mode throws */ }
assert(!mutated, 'SEVERITY_RANK frozen — mutation does not stick');

// rankSeverity safe accessor
assert(rankSeverity('info') === 0, 'rankSeverity("info") === 0');
assert(rankSeverity('CRITICAL') === 4, 'rankSeverity case-insensitive ("CRITICAL" → 4)');
assert(rankSeverity('Warn') === 2, 'rankSeverity case-insensitive ("Warn" → 2)');
assert(rankSeverity('unknown') === 0, 'rankSeverity("unknown") === 0 (no NaN)');
assert(rankSeverity(null) === 0, 'rankSeverity(null) === 0');
assert(rankSeverity(undefined) === 0, 'rankSeverity(undefined) === 0');
assert(rankSeverity('') === 0, 'rankSeverity("") === 0');
assert(rankSeverity(' high ') === 0,
  'rankSeverity does not strip whitespace (returns 0 for non-normalized input)');

// Rollup pattern mirrors oia-audit's reduce
function rollup(findings) {
  return findings.reduce((acc, f) => {
    const s = String(f.severity || 'low').toLowerCase();
    return rankSeverity(s) > rankSeverity(acc) ? s : acc;
  }, 'clean');
}
assert(rollup([{ severity: 'info' }]) === 'clean',
  'rollup info-only stays clean');
assert(rollup([{ severity: 'warn' }]) === 'warn',
  'rollup warn-only elevates to warn (was NaN-ignored pre-iter-63)');
assert(rollup([{ severity: 'critical' }, { severity: 'info' }]) === 'critical',
  'rollup with critical elevates above info');
assert(rollup([{ severity: 'low' }, { severity: 'warn' }, { severity: 'high' }, { severity: 'critical' }]) === 'critical',
  'rollup picks max across mixed severities');
assert(rollup([{ severity: 'unknown-strange-value' }]) === 'clean',
  'rollup with unknown severity stays clean (safe default)');

console.log('\nPhase 10 — iter-50 parseMcpScanText edge cases');

// Empty input — graceful return shape
const empty = parseMcpScanText('');
assert(Array.isArray(empty.findings) && empty.findings.length === 0,
  'parseMcpScanText("") → findings:[]');
assert(empty.summary === null, 'parseMcpScanText("") → summary:null');

// null / undefined safe
const nullParsed = parseMcpScanText(null);
assert(Array.isArray(nullParsed.findings) && nullParsed.findings.length === 0,
  'parseMcpScanText(null) → findings:[]');
const undefParsed = parseMcpScanText(undefined);
assert(Array.isArray(undefParsed.findings) && undefParsed.findings.length === 0,
  'parseMcpScanText(undefined) → findings:[]');

// Single finding — happy path
const single = parseMcpScanText(`harness mcp-scan — /repo

  [INFO] No MCP security issues found

Result: INFO (1 finding, 0 high)
`);
assert(single.findings.length === 1, 'single [INFO] block → 1 finding');
assert(single.findings[0].severity === 'info', 'severity lowercased');
assert(single.findings[0].message === 'No MCP security issues found',
  'message extracted');
assert(single.summary?.overallSeverity === 'info',
  'summary.overallSeverity from Result: line');
assert(single.summary?.totalCount === 1,
  'summary.totalCount === 1 from "(1 finding,"');

// Continuation line — indented text appends to previous finding
const cont = parseMcpScanText(`
  [HIGH] Exposed credential path
         Detected in .mcp/servers.json line 12
         Recommended action: rotate immediately

Result: HIGH (1 finding, 1 high)
`);
assert(cont.findings.length === 1, 'finding with continuation = 1 entry');
assert(cont.findings[0].severity === 'high', 'HIGH lowercased to high');
assert(cont.findings[0].message.includes('Detected in') &&
       cont.findings[0].message.includes('rotate immediately'),
  'continuation lines appended to message');

// Multiple findings — distinct entries
const multi = parseMcpScanText(`
  [WARN] First issue
  [HIGH] Second issue
  [CRITICAL] Third issue

Result: HIGH (3 findings, 2 high)
`);
assert(multi.findings.length === 3, 'multiple findings = 3 entries');
assert(multi.findings.map((f) => f.severity).join(',') === 'warn,high,critical',
  'severities preserved in order');
assert(multi.summary?.totalCount === 3, 'multi summary totalCount === 3');

// No Result: line — summary stays null but findings still parsed
const noResult = parseMcpScanText(`  [INFO] Lone finding\n`);
assert(noResult.findings.length === 1, 'no Result: line → still parses findings');
assert(noResult.summary === null, 'no Result: line → summary === null');

// Mixed-case severity in source — parser is intentionally strict: regex
// captures `[A-Z]+` so mixed-case 'Warn' WON'T match. This is the
// documented contract — upstream emits all-uppercase markers.
const mixed = parseMcpScanText('  [Warn] Something\n  [HIGH] Other\n');
assert(mixed.findings.length === 1,
  'strict regex skips mixed-case [Warn], captures [HIGH] only');
assert(mixed.findings[0].severity === 'high',
  'strict regex captured the uppercase entry');

// ──────────────────────────────────────────────────────────────────
const summary = {
  passed, failed,
  failures,
  total: passed + failed,
  graduates: failed === 0,
};

console.log(`\n${passed} passed, ${failed} failed`);
if (ARGS.format === 'json') {
  console.log(JSON.stringify(summary, null, 2));
}
if (failed > 0) {
  console.log('\nFailures:');
  for (const f of failures) console.log(`  - ${f}`);
  process.exit(1);
}
console.log('\n✓ All _similarity.mjs unit tests pass (ADR-152 §3.1 production contract).');

#!/usr/bin/env node
// test-with-openrouter.mjs — runtime test that exercises metaharness
// scaffolding + lifecycle commands using OPENROUTER_API_KEY fetched
// from GCP Secret Manager.
//
// WHAT IT DOES (end-to-end)
//   1. Fetch OPENROUTER_API_KEY from GCP Secret Manager via
//      `gcloud secrets versions access latest --secret=OPENROUTER_API_KEY`
//   2. Verify the secret authenticates against OpenRouter by listing
//      models (1 HTTP call, ~$0)
//   3. Scaffold a fresh harness into a temp dir via
//      `metaharness new --name test-h --template vertical:coding
//      --host claude-code --yes`
//   4. Run lifecycle commands against the scaffold:
//        - harness doctor    (smoke health check)
//        - harness validate  (full validation; --skip-gcp to avoid
//                             nested GCP fetches in this test)
//        - harness score     (5-dim scorecard of the scaffolded
//                             harness itself)
//        - harness genome    (7-section report)
//   5. (Optional) make one real LLM call through OpenRouter to a
//      cheap model (e.g. openrouter/auto with a 1-token prompt) to
//      prove the token works for actual inference
//   6. Clean up the temp dir
//
// COST: ~$0 (1 model-list call + optional <$0.0001 inference call)
//
// USAGE
//   node scripts/test-with-openrouter.mjs                 # full e2e
//   node scripts/test-with-openrouter.mjs --skip-inference  # no LLM call
//   node scripts/test-with-openrouter.mjs --keep-fixtures # leave scaffold for inspection
//
// EXIT CODES
//   0  all checks passed
//   1  at least one assertion failed
//   2  setup error (gcloud not authed, OPENROUTER_API_KEY missing in GCP, etc.)
//   3  cost/safety guard tripped

import { spawnSync, execSync } from 'node:child_process';
import { mkdtempSync, rmSync, mkdirSync, existsSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';

const ARGS = (() => {
  const a = { skipInference: false, keep: false, format: 'table' };
  for (let i = 2; i < process.argv.length; i++) {
    const v = process.argv[i];
    if (v === '--skip-inference') a.skipInference = true;
    else if (v === '--keep-fixtures') a.keep = true;
    else if (v === '--format') a.format = process.argv[++i];
  }
  return a;
})();

let passed = 0, failed = 0;
const failures = [];
function assert(cond, label) {
  if (cond) { console.log(`  ✓ ${label}`); passed++; }
  else { console.log(`  ✗ ${label}`); failures.push(label); failed++; }
}

function fetchSecretFromGcp(secretName) {
  try {
    const out = execSync(
      `gcloud secrets versions access latest --secret=${secretName}`,
      { encoding: 'utf-8', stdio: ['ignore', 'pipe', 'pipe'], timeout: 15_000 },
    );
    return out.trim();
  } catch (e) {
    console.error(`  ⚠ gcloud secret fetch failed: ${(e.message || '').slice(0, 120)}`);
    return null;
  }
}

async function listOpenRouterModels(apiKey) {
  const resp = await fetch('https://openrouter.ai/api/v1/models', {
    headers: { Authorization: `Bearer ${apiKey}` },
  });
  if (!resp.ok) {
    return { ok: false, status: resp.status, body: (await resp.text()).slice(0, 200) };
  }
  const data = await resp.json();
  return { ok: true, modelCount: data.data?.length ?? 0 };
}

async function cheapInferenceCall(apiKey) {
  // openrouter/auto picks the cheapest viable model; 5-token prompt;
  // max_tokens=1 to bound cost at ~$0.00005.
  const resp = await fetch('https://openrouter.ai/api/v1/chat/completions', {
    method: 'POST',
    headers: {
      Authorization: `Bearer ${apiKey}`,
      'Content-Type': 'application/json',
      'HTTP-Referer': 'https://github.com/ruvnet/ruflo',
      'X-Title': 'ruflo-metaharness-test',
    },
    body: JSON.stringify({
      model: 'openrouter/auto',
      messages: [{ role: 'user', content: 'OK' }],
      max_tokens: 1,
    }),
  });
  if (!resp.ok) return { ok: false, status: resp.status, body: (await resp.text()).slice(0, 200) };
  const data = await resp.json();
  return { ok: true, model: data.model, usage: data.usage };
}

function runHarness(args, opts = {}) {
  const r = spawnSync('npx', ['-y', '-p', 'metaharness@latest', 'harness', ...args], {
    stdio: ['ignore', 'pipe', 'pipe'], encoding: 'utf-8',
    timeout: opts.timeoutMs ?? 60_000,
    env: { ...process.env, ...opts.env },
  });
  return { exitCode: r.status ?? 1, stdout: r.stdout || '', stderr: r.stderr || '' };
}

function runMetaharness(args, opts = {}) {
  const r = spawnSync('npx', ['-y', 'metaharness@latest', ...args], {
    stdio: ['ignore', 'pipe', 'pipe'], encoding: 'utf-8',
    timeout: opts.timeoutMs ?? 120_000,
    cwd: opts.cwd,  // metaharness new writes to cwd/<name>; --target is ignored
    env: { ...process.env, ...opts.env },
  });
  return { exitCode: r.status ?? 1, stdout: r.stdout || '', stderr: r.stderr || '' };
}

async function main() {
  console.log('# test-with-openrouter — metaharness × GCP × OpenRouter e2e\n');

  // ── 0. Preflight ──────────────────────────────────────────────────
  console.log('Phase 0 — preflight');
  const gcloudWho = execSync('gcloud config get-value account 2>&1', { encoding: 'utf-8' }).trim();
  assert(!!gcloudWho && !/None/.test(gcloudWho), `gcloud authenticated (${gcloudWho || 'none'})`);

  // ── 1. Fetch OPENROUTER_API_KEY ───────────────────────────────────
  console.log('\nPhase 1 — fetch OPENROUTER_API_KEY from GCP Secret Manager');
  const apiKey = fetchSecretFromGcp('OPENROUTER_API_KEY');
  assert(typeof apiKey === 'string' && apiKey.length > 20, 'OPENROUTER_API_KEY fetched (length OK)');
  if (!apiKey) {
    console.error('Setup error: cannot proceed without OPENROUTER_API_KEY. Skipping further phases.');
    process.exit(2);
  }
  // Echo only length+prefix, never the raw key
  console.log(`  key length: ${apiKey.length}, prefix: ${apiKey.slice(0, 7)}…`);

  // ── 2. Verify the key authenticates against OpenRouter ────────────
  console.log('\nPhase 2 — verify OpenRouter authentication');
  const modelsResp = await listOpenRouterModels(apiKey);
  assert(modelsResp.ok, `OpenRouter /api/v1/models returns 2xx (got ${modelsResp.ok ? 'ok' : modelsResp.status})`);
  if (modelsResp.ok) {
    assert(modelsResp.modelCount > 10, `model list non-empty (${modelsResp.modelCount} models)`);
  }

  // ── 3. Scaffold a fresh harness ───────────────────────────────────
  // CRITICAL: `metaharness new <name>` writes to $CWD/<name> — the
  // --target flag is ignored by the CLI (verified 2026-06-16 against
  // metaharness@0.1.11). Run from inside a fresh temp dir so the
  // scaffold lands there, not in the ruflo project root.
  console.log('\nPhase 3 — scaffold a fresh harness');
  const fixture = mkdtempSync(join(tmpdir(), 'ruflo-mh-openrouter-'));
  const target = join(fixture, 'test-harness');
  console.log(`  fixture cwd: ${fixture}`);
  console.log(`  expected target: ${target}`);
  const scaffold = runMetaharness(
    ['test-harness', '--template', 'vertical:coding', '--host', 'claude-code'],
    { timeoutMs: 180_000, cwd: fixture },
  );
  assert(scaffold.exitCode === 0, `metaharness new exit 0 (got ${scaffold.exitCode})`);
  assert(existsSync(target), `target dir created at ${target}`);

  // ── 4. Run lifecycle commands against the scaffold ────────────────
  console.log('\nPhase 4 — lifecycle commands on the scaffold');
  // harness doctor — quick smoke
  const doc = runHarness(['doctor', target]);
  assert(doc.exitCode === 0, `harness doctor exit 0 (got ${doc.exitCode})`);

  // harness score on the scaffold itself
  const score = runHarness(['score', target, '--json']);
  assert(score.exitCode === 0, `harness score exit 0 (got ${score.exitCode})`);
  const scoreJson = (() => {
    const m = /\{[\s\S]*\}/.exec(score.stdout);
    try { return m ? JSON.parse(m[0]) : null; } catch { return null; }
  })();
  assert(scoreJson && typeof scoreJson.score === 'number', 'score.json has numeric score');

  // harness genome — exit 0 (ready) or 1 (needs-work) both acceptable.
  // Only exit 2 (blocked / scan-error) is a real failure.
  const gen = runHarness(['genome', target, '--json']);
  assert(gen.exitCode === 0 || gen.exitCode === 1, `harness genome exit 0 or 1 (got ${gen.exitCode})`);

  // harness mcp-scan
  const scan = runHarness(['mcp-scan', target]);
  // mcp-scan can exit 1 on findings; either 0 or 1 is acceptable here.
  assert(scan.exitCode === 0 || scan.exitCode === 1, `harness mcp-scan exit 0 or 1 (got ${scan.exitCode})`);

  // ── 5. (Optional) one real OpenRouter inference call ──────────────
  if (!ARGS.skipInference) {
    console.log('\nPhase 5 — single OpenRouter inference call (cheapest auto-route, max_tokens=1)');
    const inf = await cheapInferenceCall(apiKey);
    assert(inf.ok, `OpenRouter inference 2xx (got ${inf.ok ? 'ok' : inf.status})`);
    if (inf.ok) {
      console.log(`  model used: ${inf.model}`);
      console.log(`  usage: prompt=${inf.usage?.prompt_tokens} completion=${inf.usage?.completion_tokens}`);
    }
  } else {
    console.log('\nPhase 5 — SKIPPED (--skip-inference)');
  }

  // ── 6. Cleanup ────────────────────────────────────────────────────
  if (!ARGS.keep) {
    rmSync(fixture, { recursive: true, force: true });
    console.log(`\nFixture cleaned: ${fixture}`);
  } else {
    console.log(`\nFixture kept at: ${fixture}`);
  }

  console.log(`\n${passed} passed, ${failed} failed`);
  if (failed > 0) {
    console.log('\nFailures:');
    for (const f of failures) console.log(`  - ${f}`);
    process.exit(1);
  }
  console.log('\n✓ All harness × OpenRouter integration checks passed.');
}

main().catch((e) => {
  console.error('test-with-openrouter crashed:', e.message || e);
  process.exit(2);
});

#!/usr/bin/env node
// threat-model.mjs — wrapper around `harness threat-model <path>`.
//
// USAGE
//   node scripts/threat-model.mjs --path . --fail-on high --format json

import { runHarness, emitDegradedJsonAndExit } from './_harness.mjs';

const SEVERITY_RANK = { clean: 0, low: 1, medium: 2, high: 3 };

const ARGS = (() => {
  const a = { path: '.', format: 'json', failOn: 'high' };
  for (let i = 2; i < process.argv.length; i++) {
    const v = process.argv[i];
    if (v === '--path') a.path = process.argv[++i];
    else if (v === '--fail-on') a.failOn = String(process.argv[++i] || 'high').toLowerCase();
    else if (v === '--format') a.format = process.argv[++i];
  }
  return a;
})();

function main() {
  if (!SEVERITY_RANK.hasOwnProperty(ARGS.failOn)) {
    console.error(`threat-model: --fail-on must be one of clean|low|medium|high`);
    process.exit(2);
  }
  const r = runHarness(['threat-model', ARGS.path]);
  if (r.degraded) { emitDegradedJsonAndExit(r.reason); return; }
  if (r.exitCode !== 0 && r.exitCode !== 1) {
    console.error(`threat-model: harness exited ${r.exitCode}`);
    if (r.stderr) console.error(r.stderr.slice(0, 400));
    process.exit(2);
  }
  const payload = r.json ?? { rawStdout: r.stdout.slice(0, 400) };
  const worst = String(payload?.worst || 'clean').toLowerCase();
  const threshold = SEVERITY_RANK[ARGS.failOn];
  const triggered = SEVERITY_RANK[worst] >= threshold && threshold > 0;
  const alert = {
    threshold: ARGS.failOn, worst, triggered,
    reason: triggered
      ? `worst=${worst} at or above ${ARGS.failOn}`
      : `worst=${worst} below ${ARGS.failOn} — OK`,
  };

  if (ARGS.format === 'json') {
    console.log(JSON.stringify({ ...payload, durationMs: r.durationMs, alert }, null, 2));
  } else {
    console.log(`# harness threat-model — ${ARGS.path}`);
    console.log('');
    console.log(`Worst severity: ${worst}`);
    console.log(`Findings: ${(payload?.findings || []).length}`);
    console.log('');
    console.log(alert.triggered ? `⚠ **ALERT**: ${alert.reason}` : `✓ ${alert.reason}`);
  }

  if (alert.triggered) process.exit(1);
}

main();
